INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jeremylongshore/claude-code-plugins-plus-skills/log-analysis-security', 'log-analysis-security', 'jeremylongshore', 'claude-code-plugins-plus-skills', 'community', 'log-analysis-security jeremylongshore claude-code-plugins-plus-skills community 日志分析安全技能提供自动化的安全任务帮助，涵盖安全高级领域 ログ分析セキュリティスキルは、セキュリティの高度なドメインをカバーする自動化されたセキュリティタスクを提供 로그 분석 보안 스킬은 보안 고급 도메인을 포함한 자동화된 보안 작업을 제공 Esta habilidad proporciona asistencia automatizada para tareas de análisis de registros de seguridad dentro del dominio de Seguridad Avanzada Cette compétence fournit une assistance automatisée pour les tâches d''analyse de journaux de sécurité dans le domaine de la Sécurité Avancée Diese Fähigkeit bietet automatisierte Unterstützung für Aufgaben zur Analyse von Protokollen innerhalb des Bereichs erweiterte Sicherheit A habilidade de log-analysis-security fornece assistência automatizada para tarefas de análise de log de segurança. Fornece padrões de orquestração de produção e tutoriais interativos. Навык log-analysis-security предоставляет автоматизированную помощь для задач анализа логов безопасности. Предоставляет шаблоны оркестровки производства и интерактивные уроки. المهارة log-analysis-security توفر مساعدة آلية للمهام تحليل سجل الأمان. توفر أنماطا لتنسيق الإنتاج والدروس التفاعلية. 270+ Claude Code plugins with 739 agent skills. Production orchestration patterns, interactive tutorials (11 Jupyter notebooks), and CCPI package manager. 4.13.0 日志分析安全 自动化安全任务 安全高级领域 交互式教程 生产编排模式 代理技能 270+ Claude Code plugins with 739 agent skills. Production orchestration patterns, interactive tutorials (11 Jupyter notebooks), and CCPI package manager. 4.13.0');
