INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mims-harvard/ToolUniverse/tooluniverse', 'tooluniverse', 'mims-harvard', 'ToolUniverse', 'community', 'tooluniverse mims-harvard ToolUniverse community ToolUniverse是一个民主化的AI科学平台，帮助开发者更好地理解和解决用户问题，通过路由器和通用策略提供更好的用户体验 ToolUniverseは、開発者がユーザーの質問をよりよく理解し解決するための民主的なAI科学プラットフォームです。ルーターと一般的な戦略を使用して、より良いユーザーエクスペリエンスを提供します ToolUniverse는 개발자가 사용자의 질문을 더 잘 이해하고 해결할 수 있는 민주적인 AI 과학 플랫폼입니다. 라우터와 일반 전략을 사용하여 더好的 사용자 경험을 제공합니다 ToolUniverse es una plataforma que democratiza la ciencia de la IA, permitiendo a los usuarios encontrar soluciones personalizadas para sus preguntas ToolUniverse est une plateforme qui démocratise la science de l''IA, permettant aux utilisateurs de trouver des solutions personnalisées pour leurs questions ToolUniverse ist eine Plattform, die die KI-Wissenschaft demokratisiert und es den Benutzern ermöglicht, individuelle Lösungen für ihre Fragen zu finden O ToolUniverse é uma ferramenta que ajuda a democratizar cientistas de IA, fornecendo estratégias gerais para routear perguntas de usuários ToolUniverse - это инструмент, который помогает демократизировать ученых ИИ, предоставляя общие стратегии для маршрутизации вопросов пользователей ToolUniverse هو أداة تساعد في ديمقراطية علماء الذكاء الاصطناعي، وتوفر استراتيجيات عامة لتوجيه أسئلة المستخدمين Democratizing AI scientists with ToolUniverse ToolUniverse AI科学 路由器 通用策略 用户问题解析 实体识别 操作识别 范围识别 Democratizing AI scientists with ToolUniverse');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dojoengine/book/dojo-indexer', 'community', 'dojoengine', 'book', 'dojoengine/book', 'dojo-indexer', 0, 0, 65, '2026-02-20T04:13:19.578Z', '2026-02-20T04:58:28.068Z', 'c6712331d16ddffd6952a19ef54a650ef23588e2ec297d24345ea7680a9130db', '{"id":"dojoengine/book/dojo-indexer","name":"dojo-indexer","description":{"zh":"Dojo Indexer Torii, ","ja":"Dojo ","ko":"Dojo ","es":"El indexador Dojo, Torii, permite consultas eficientes y suscripciones en tiempo real. Configura Torii para mejorar el rendimiento de tus consultas","fr":"L''indexeur Dojo, Torii, permet des requêtes efficaces et des abonnements en temps réel. Configurez Torii pour améliorer les performances de vos requêtes","de":"Der Dojo-Indexer, Torii, ermöglicht effiziente Abfragen und Echtzeitsubskriptionen. Konfigurieren Sie Torii, um die Leistung Ihrer Abfragen zu verbessern","pt":"O Dojo Indexer é uma ferramenta para consultas eficientes e assinaturas em tempo real. Configure o Torii para gerenciar seu estado de mundo","ru":"Dojo Индексер — это инструмент для эффективных запросов и подписок в реальном времени. Настройте Torii для управления своим состоянием мира","ar":"مؤشر دوچو هو أداة للاستفسارات الفعالة والتسجيلات في الوقت الفعلي. 구성 تورى لإدارة حالتك العالمية","en":"The Dojo Book"},"seo":{"title":{"zh":"Dojo Indexer Torii","ja":"Dojo ","ko":"Dojo ","es":"Indexador Dojo: Torii para consultas eficientes","fr":"Indexeur Dojo : Torii pour des requêtes efficaces","de":"Dojo-Indexer: Torii für effiziente Abfragen","pt":"Dojo Indexer: Torii para Consultas Eficientes","ru":"Dojo Индексер: Torii для Эффективных Запросов","ar":"مؤشر دوچو: تورى للاستفسارات الفعالة","en":"dojo-indexer"},"description":{"zh":"Dojo Indexer Torii, ","ja":"Dojo ","ko":"Dojo ","es":"El indexador Dojo, Torii, permite consultas eficientes y suscripciones en tiempo real. Configura Torii para mejorar el rendimiento de tus consultas","fr":"L''indexeur Dojo, Torii, permet des requêtes efficaces et des abonnements en temps réel. Configurez Torii pour améliorer les performances de vos requêtes","de":"Der Dojo-Indexer, Torii, ermöglicht effiziente Abfragen und Echtzeitsubskriptionen. Konfigurieren Sie Torii, um die Leistung Ihrer Abfragen zu verbessern","pt":"O Dojo Indexer é uma ferramenta para consultas eficientes e assinaturas em tempo real. Configure o Torii para gerenciar seu estado de mundo","ru":"Dojo Индексер — это инструмент для эффективных запросов и подписок в реальном времени. Настройте Torii для управления своим состоянием мира","ar":"مؤشر دوچو هو أداة للاستفسارات الفعالة والتسجيلات في الوقت الفعلي. 구성 تورى لإدارة حالتك العالمية","en":"The Dojo Book"},"definition":{"en":"The Dojo Book"},"features":{"zh":["Torii","GraphQL","","SQL",""],"ja":["Torii","GraphQL","","SQL",""],"ko":["Torii","GraphQL","","SQL",""],"es":["Configuración de Torii","Creación de consultas GraphQL","Suscripciones en tiempo real","Acceso directo a la base de datos SQL"],"fr":["Configuration de Torii","Création de requêtes GraphQL","Abonnements en temps réel","Accès direct à la base de données SQL"],"de":["Konfiguration von Torii","Erstellung von GraphQL-Abfragen","Echtzeitsubskriptionen","Direkter Zugriff auf die SQL-Datenbank"],"pt":["Configuração do Torii","Criação de consultas GraphQL","Assinaturas em tempo real","Acesso direto ao banco de dados SQL","Gerenciamento de estado de mundo"],"ru":["Настройка Torii","Создание запросов GraphQL","Подписки в реальном времени","Прямой доступ к базе данных SQL","Управление состоянием мира"],"ar":["تكوين تورى","إنشاء استفسارات جرافكول","التسجيلات في الوقت الفعلي","الدخول المباشر إلى قاعدة بيانات إس كيو إل","إدارة حالة العالم"]},"keywords":{"zh":["Dojo Indexer","Torii","GraphQL","SQL","",""],"ja":["Dojo ","Torii","GraphQL","SQL","",""],"ko":["Dojo ","Torii","GraphQL","SQL","",""],"es":["indexador Dojo","Torii","consultas eficientes","suscripciones en tiempo real","GraphQL","base de datos SQL"],"fr":["indexeur Dojo","Torii","requêtes efficaces","abonnements en temps réel","GraphQL","base de données SQL"],"de":["Dojo-Indexer","Torii","effiziente Abfragen","Echtzeitsubskriptionen","GraphQL","SQL-Datenbank"],"pt":["Dojo Indexer","Torii","Consultas Eficientes","Assinaturas em Tempo Real","GraphQL","SQL","Desenvolvimento de Software","Estado de Mundo"],"ru":["Dojo Индексер","Torii","Эффективные Запросы","Подписки в Реальном Времени","GraphQL","SQL","Разработка Программного Обеспечения","Состояние Мира"],"ar":["مؤشر دوچو","تورى","الاستفسارات الفعالة","التسجيلات في الوقت الفعلي","جرافكول","إس كيو إل","تطوير البرمجيات","حالة العالم"]}},"owner":"dojoengine","repo":"book","repoPath":"dojoengine/book","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.578Z","topics":[],"category":"community","skillMd":{"name":"dojo-indexer","description":"Set up and configure Torii indexer for GraphQL queries, gRPC subscriptions, and SQL access. Use when indexing your deployed world for client queries or real-time updates.","bodyPreview":"# Dojo Indexer (Torii)\n\nSet up and use Torii, the Dojo indexer, for efficient querying and real-time subscriptions to your world state.\n\n## When to Use This Skill\n\n- \"Set up Torii indexer\"\n- \"Configure GraphQL for my world\"\n- \"Create subscriptions for entity updates\"\n- \"Query world state efficiently\"\n\n## What This Skill Does\n\nManages Torii indexer:\n- Start and configure Torii\n- Create GraphQL queries\n- Set up real-time subscriptions\n- Access SQL database directly\n\n## Quick Start\n\n**Start Torii:*","body":"# Dojo Indexer (Torii)\n\nSet up and use Torii, the Dojo indexer, for efficient querying and real-time subscriptions to your world state.\n\n## When to Use This Skill\n\n- \"Set up Torii indexer\"\n- \"Configure GraphQL for my world\"\n- \"Create subscriptions for entity updates\"\n- \"Query world state efficiently\"\n\n## What This Skill Does\n\nManages Torii indexer:\n- Start and configure Torii\n- Create GraphQL queries\n- Set up real-time subscriptions\n- Access SQL database directly\n\n## Quick Start\n\n**Start Torii:**\n```bash\ntorii --world <WORLD_ADDRESS>\n```\n\nThis starts Torii with default settings:\n- GraphQL API at `http://localhost:8080/graphql`\n- gRPC API at `http://localhost:8080`\n- In-memory database (for development)\n\n**With Controller indexing (recommended):**\n```bash\ntorii --world <WORLD_ADDRESS> --indexing.controllers\n```\n\n**Production configuration:**\n```bash\ntorii --world <WORLD_ADDRESS> --db-dir ./torii-db --indexing.controllers\n```\n\n## What is Torii?\n\nTorii is the Dojo indexer that:\n- Watches blockchain for world events\n- Indexes model state changes\n- Provides GraphQL API for queries\n- Provides gRPC API for subscriptions\n- Offers SQL access for complex queries\n\n**Why use Torii:**\n- Faster than direct RPC queries\n- Complex queries (filters, pagination)\n- Real-time subscriptions\n- Type-safe GraphQL schema\n\n## GraphQL API\n\nTorii provides GraphQL endpoint at `http://localhost:8080/graphql`\n\nUse the GraphiQL IDE in your browser to explore the schema and test queries.\n\n### Schema Structure\n\nTorii generates two types of queries:\n\n**Generic Queries:**\n- `entities` - Access all entities with filtering\n- `models` - Retrieve model definitions\n- `transactions` - Query indexed transactions\n\n**Model-Specific Queries:**\n- `{modelName}Models` - Custom queries for each model\n- Example: `positionModels`, `movesModels`\n\n### Basic Queries\n\n**Get all entities of a model:**\n```graphql\nquery {\n    movesModels {\n        edges {\n            node {\n                player\n                remaining\n                last_direction\n            }\n        }\n    }\n}\n```\n\n**Get model metadata:**\n```graphql\nquery {\n    models {\n        edges {\n            node {\n                id\n                name\n                classHash\n                contractAddress\n            }\n        }\n        totalCount\n    }\n}\n```\n\n### Pagination\n\n**Cursor-based pagination:**\n```graphql\nquery {\n    entities(first: 10) {\n        edges {\n            cursor\n            node {\n                id\n            }\n        }\n        pageInfo {\n            hasNextPage\n            endCursor\n        }\n    }\n}\n```\n\n**Get next page:**\n```graphql\nquery {\n    entities(first: 10, after: \"cursor_value\") {\n        edges {\n            cursor\n            node { id }\n        }\n    }\n}\n```\n\n**Offset/limit pagination:**\n```graphql\nquery {\n    entities(offset: 20, limit: 10) {\n        edges {\n            node { id }\n        }\n        totalCount\n    }\n}\n```\n\n## Real-time Subscriptions\n\nSubscribe to world state changes via WebSocket.\n\n### Entity Updates\n\n```graphql\nsubscription {\n    entityUpdated(id: \"0x54f58...\") {\n        id\n        updatedAt\n        models {\n            __typename\n            ... on Position {\n                vec {\n                    x\n                    y\n                }\n            }\n            ... on Moves {\n                remaining\n            }\n        }\n    }\n}\n```\n\n### Event Stream\n\nMonitor all world events:\n\n```graphql\nsubscription {\n    eventEmitted {\n        id\n        keys\n        data\n        transactionHash\n    }\n}\n```\n\n### Model Registration\n\nListen for new model registrations:\n\n```graphql\nsubscription {\n    modelRegistered {\n        id\n        name\n        namespace\n    }\n}\n```\n\n## SQL Access\n\nTorii stores data in SQLite, accessible for complex queries.\n\n**Connect to database:**\n```bash\nsqlite3 torii.db\n```\n\n**Example queries:**\n```sql\n-- Count entities\nSELECT COUNT(*) FROM entities;\n\n-- Custom aggregations\nSELECT AVG(value) FROM model_data WHERE model_name = ''Health'';\n```\n\n## Client Integration\n\n### JavaScript/TypeScript\n\n```typescript\nimport { createClient } from ''@dojoengine/torii-client'';\n\nconst client = await createClient({\n    rpcUrl: \"http://localhost:5050\",\n    toriiUrl: \"http://localhost:8080\",\n    worldAddress: WORLD_ADDRESS,\n});\n\n// Query entities\nconst positions = await client.getEntities({\n    model: \"Position\",\n    limit: 10\n});\n\n// Subscribe to updates\nawait client.onEntityUpdated(\n    [{ model: \"Position\", keys: [playerId] }],\n    (entity) => console.log(\"Position updated:\", entity)\n);\n```\n\n### Apollo Client (GraphQL)\n\n```typescript\nimport { ApolloClient, InMemoryCache, gql } from ''@apollo/client'';\n\nconst client = new ApolloClient({\n    uri: ''http://localhost:8080/graphql'',\n    cache: new InMemoryCache(),\n});\n\nconst { data } = await client.query({\n    query: gql`\n        query GetMoves {\n            movesModels {\n                edges {\n                    node {\n                        player\n                        remaining\n                    }\n                }\n            }\n        }\n    `\n});\n```\n\n## Configuration Options\n\n| Option | Description | Default |\n|--------|-------------|---------|\n| `--world` | World contract address | Optional (since Torii 1.6.0) |\n| `--rpc` | RPC endpoint URL | `http://localhost:5050` |\n| `--db-dir` | Database directory | In-memory |\n| `--config` | Path to TOML configuration file | None |\n| `--http.cors_origins` | CORS origins | `*` |\n\n## Slot Deployment (Remote)\n\n[Slot](https://docs.cartridge.gg/slot) provides hosted Torii instances. Slot requires a TOML configuration file.\n\n### Create Configuration\n\n```toml\n# torii.toml\nworld_address = \"<WORLD_ADDRESS>\"\nrpc = \"<RPC_URL>\"\n\n[indexing]\ncontrollers = true\n```\n\nSee the [Torii configuration guide](/toolchain/torii/configuration) for all TOML options (indexing, polling, namespaces, etc.).\n\n### Deploy\n\n```bash\nslot auth login\n\nslot deployments create <PROJECT_NAME> torii --config torii.toml --version <DOJO_VERSION>\n```\n\n### Manage\n\n```bash\n# Stream logs\nslot deployments logs <PROJECT_NAME> torii -f\n\n# Delete and recreate (safe — all data is on-chain)\nslot deployments delete <PROJECT_NAME> torii\n```\n\n## Development Workflow\n\n**Terminal 1: Start Katana**\n```bash\nkatana --dev --dev.no-fee\n```\n\n**Terminal 2: Deploy world**\n```bash\nsozo build && sozo migrate\n```\n\n**Terminal 3: Start Torii**\n```bash\ntorii --world <WORLD_ADDRESS> --http.cors_origins \"*\"\n```\n\n## Troubleshooting\n\n### \"Connection refused\"\n- Check Torii is running\n- Verify port (default 8080)\n- Check firewall rules\n\n### \"World not found\"\n- Verify world address is correct\n- Check RPC URL is accessible\n- Ensure world is deployed\n\n### \"Slow queries\"\n- Use model-specific queries instead of generic `entities`\n- Use pagination\n- Request only needed fields\n\n## Next Steps\n\nAfter Torii setup:\n1. Integrate with client (`dojo-client` skill)\n2. Create optimized queries\n3. Set up subscriptions\n4. Monitor performance\n\n## Related Skills\n\n- **dojo-deploy**: Deploy world first\n- **dojo-client**: Use Torii in clients\n- **dojo-world**: Configure what Torii indexes\n- **dojo-migrate**: Restart Torii after migrations\n"},"lastSynced":"2026-02-20T04:58:28.068Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing efficient querying and real-time subscriptions to their world state, such as those utilizing GraphQL and SQL databases.","zh":"适合需要高效查询和实时订阅其世界状态的AI代理，例如使用GraphQL和SQL数据库的代理。","ja":"GraphQLやSQLデータベースを使用するなど、効率的なクエリとリアルタイムのサブスクリプションが必要なAIエージェントに適しています。","ko":"GraphQL 및 SQL 데이터베이스를 사용하는 것과 같이 효율적인 쿼리 및 실시간 구독이 필요한 AI 에이전트에게 적합합니다.","es":"Perfecto para agentes de IA que necesitan consultas eficientes y suscripciones en tiempo real a su estado de mundo, como aquellos que utilizan GraphQL y bases de datos SQL.","fr":"Parfait pour les agents IA ayant besoin d''interrogations efficaces et d''abonnements en temps réel à leur état de monde, tels que ceux utilisant GraphQL et des bases de données SQL.","de":"Perfekt für KI-Agents, die effiziente Abfragen und Echtzeitsubskriptionen zu ihrem Weltzustand benötigen, wie z.B. solche, die GraphQL und SQL-Datenbanken verwenden.","pt":"Perfeito para Agentes de IA que necessitam de consultas eficientes e assinaturas em tempo real para o estado do seu mundo, como aqueles que utilizam GraphQL e bancos de dados SQL.","ru":"Идеально для агентов ИИ, которым необходимы эффективные запросы и подписки в режиме реального времени на их состояние мира, такие как те, которые используют GraphQL и базы данных SQL.","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يحتاجون إلى استفسارات فعالة وتسجيلات في الوقت الفعلي لcurrentState العالم، مثل تلك التي تستخدم GraphQL وقواعد البيانات SQL."},"recommendation":{"en":"Empowers agents to manage Torii indexer for efficient querying and real-time subscriptions, leveraging GraphQL queries and direct SQL database access for optimized world state management.","zh":"赋予代理管理Torii索引器的能力，以实现高效的查询和实时订阅，利用GraphQL查询和直接的SQL数据库访问来优化世界状态管理。","ja":"Toriiインデクサーの管理をエージェントに可能にし、効率的なクエリとリアルタイムのサブスクリプションを実現します。GraphQLクエリと直接のSQLデータベースアクセスを利用して、世界状態の管理を最適化します。","ko":"에이전트가 Torii 인덱서를 관리하여 효율적인 쿼리 및 실시간 구독을 가능하게 하며, GraphQL 쿼리 및 직접 SQL 데이터베이스 액세스를 활용하여 세계 상태 관리를 최적화합니다.","es":"Permite a los agentes gestionar el indexador Torii para consultas eficientes y suscripciones en tiempo real, aprovechando las consultas GraphQL y el acceso directo a la base de datos SQL para una gestión óptima del estado de mundo.","fr":"Permet aux agents de gérer l''indexeur Torii pour des interrogations efficaces et des abonnements en temps réel, en exploitant les requêtes GraphQL et l''accès direct à la base de données SQL pour une gestion optimale de l''état de monde.","de":"Ermöglicht es Agents, den Torii-Indexer für effiziente Abfragen und Echtzeitsubskriptionen zu verwalten, indem es GraphQL-Abfragen und direkten SQL-Datenbankzugriff für eine optimale Weltzustandsverwaltung nutzt.","pt":"Habilita os agentes a gerenciar o índice Torii para consultas eficientes e assinaturas em tempo real, aproveitando consultas GraphQL e acesso direto ao banco de dados SQL para gerenciamento otimizado do estado do mundo.","ru":"Наделяет агентов возможностью управлять индексом Torii для эффективных запросов и подписок в режиме реального времени, используя запросы GraphQL и прямой доступ к базе данных SQL для оптимизированного управления состоянием мира.","ar":"يمنح الوكلاء القدرة على إدارة فهرس Torii للاستفسارات الفعالة والتسجيلات في الوقت الفعلي، مستفيداً من استفسارات GraphQL والوصول المباشر إلى قاعدة البيانات SQL لتدبير حالة العالم الأمثل."},"useCases":{"en":["Setting up Torii indexer for real-time entity updates","Configuring GraphQL for efficient world state querying","Creating subscriptions for automated world state monitoring"],"zh":["设置Torii索引器以实现实体的实时更新","配置GraphQL以实现世界状态的高效查询","创建订阅以实现世界状态的自动监控"],"ja":["Toriiインデクサーの設定によるリアルタイムエンティティ更新","GraphQLの設定による効率的な世界状態のクエリ","サブスクリプションの作成による世界状態の自動モニタリング"],"ko":["Torii 인덱서 설정을 통해 엔티티의 실시간 업데이트","GraphQL 설정을 통해 세계 상태의 효율적인 쿼리","구독 생성을 통해 세계 상태의 자동 모니터링"],"es":["Configuración del indexador Torii para actualizaciones de entidades en tiempo real","Configuración de GraphQL para consultas eficientes del estado de mundo","Creación de suscripciones para la supervisión automática del estado de mundo"],"fr":["Configuration de l''indexeur Torii pour des mises à jour d''entités en temps réel","Configuration de GraphQL pour des interrogations efficaces de l''état de monde","Création d''abonnements pour la surveillance automatique de l''état de monde"],"de":["Einrichtung des Torii-Indexers für Echtzeit-Entitätsupdates","Konfiguration von GraphQL für effiziente Weltzustandsabfragen","Erstellung von Subskriptionen für automatisierte Weltzustandsüberwachung"],"pt":["Configurar o índice Torii para atualizações de entidades em tempo real","Configurar o GraphQL para consultas eficientes de estado do mundo","Criar assinaturas para monitoramento automático de estado do mundo"],"ru":["Настройка индекса Torii для обновлений сущностей в режиме реального времени","Настройка GraphQL для эффективных запросов состояния мира","Создание подписок для автоматического мониторинга состояния мира"],"ar":["تكوين فهرس Torii لتحديثات الكيانات في الوقت الفعلي","تكوين GraphQL للاستفسارات الفعالة لcurrentState العالم","إنشاء التسجيلات للت_MONITORING التلقائي لcurrentState العالم"]},"limitations":{"en":["Requires Torii indexer setup","GraphQL and SQL database compatibility needed"],"zh":["需要设置Torii索引器","需要GraphQL和SQL数据库的兼容性"],"ja":["Toriiインデクサーの設定が必要","GraphQLとSQLデータベースの互換性が必要"],"ko":["Torii 인덱서 설정이 필요","GraphQL 및 SQL 데이터베이스의 호환성이 필요"],"es":["Requiere configuración del indexador Torii","Se requiere compatibilidad con GraphQL y base de datos SQL"],"fr":["Nécessite la configuration de l''indexeur Torii","Nécessite la compatibilité avec GraphQL et la base de données SQL"],"de":["Benötigt Einrichtung des Torii-Indexers","Benötigt Kompatibilität mit GraphQL und SQL-Datenbank"],"pt":["Requer configuração do índice Torii","Compatibilidade com banco de dados GraphQL e SQL necessária"],"ru":["Требуется настройка индекса Torii","Необходима совместимость с базой данных GraphQL и SQL"],"ar":["يتطلب تكوين فهرس Torii","التوافق مع قاعدة البيانات GraphQL و SQL ضروري"]},"version":3},"contentHash":"c6712331d16ddffd6952a19ef54a650ef23588e2ec297d24345ea7680a9130db","qualityScore":65}');
