INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/presentation-slide-outliner', 'presentation-slide-outliner', 'majiayu000', 'claude-skill-registry', 'community', 'presentation-slide-outliner majiayu000 claude-skill-registry community 该技能提供自动化的演示文稿大纲功能，帮助开发者提高工作效率 このスキルは、プレゼンテーションの準備を自動化する機能を提供します 이 스킬은 프레젠테이션 슬라이드 아웃라인을 자동화하여 개발자의 작업 효율성을 높여줍니다 Este skill proporciona asistencia automatizada para tareas de esquema de diapositivas de presentación en el dominio de contenido visual. Cette compétence fournit une assistance automatisée pour les tâches de plan de diapositive de présentation dans le domaine du contenu visuel. Dieses Tool bietet automatisierte Unterstützung für die Erstellung von Präsentationsfolien-Gliederungen im Bereich visueller Inhalte. O apresentação slide outliner é uma ferramenta que fornece assistência automatizada para tarefas de esboço de slide de apresentação. Создатель конспекта слайда презентации - это инструмент, который предоставляет автоматизированную помощь для задач создания конспекта слайда презентации. مُصمم مخطط عرض شرائح هو أداة توفر مساعدة آلية لمهام تصميم مخططات شرائح العرض. The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app 自动化演示文稿大纲 presentation-slide-outliner 演示文稿准备 工作效率 自动化工具 开发者工具 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
