INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/backlog-grooming-assistant', 'backlog-grooming-assistant', 'majiayu000', 'claude-skill-registry', 'community', 'backlog-grooming-assistant majiayu000 claude-skill-registry community Backlog Grooming Assistant是一种自动化的技能，用于改善企业工作流程管理，提供项目管理、合规性、治理和企业集成模式的支持 バックロググルーミングアシスタントは、エンタープライズワークフローの管理を改善する自動化されたスキルで、プロジェクト管理、コンプライアンス、ガバナンス、エンタープライズ統合パターンをサポートします 백로그 그루밍 어시스턴트는 엔터프라이즈 워크플로우의 관리를 개선하는 자동화된 스킬로, 프로젝트 관리, 컴플라이언스, 거버넌스, 엔터프라이즈 통합 패턴을 지원합니다 El asistente de limpieza de backlog proporciona asistencia automatizada para tareas de gestión de proyectos y cumplimiento normativo. L''assistant de nettoyage de backlog fournit une assistance automatisée pour les tâches de gestion de projets et de conformité. Der Backlog-Bereinigungsassistent bietet automatisierte Unterstützung für Aufgaben im Projektmanagement und der Einhaltung von Vorschriften. O Assistente de Refinamento de Backlog fornece assistência automatizada para tarefas de refinamento de backlog dentro do domínio de Fluxos de Trabalho Empresariais. Помощник по уходу за бэклогом предоставляет автоматизированную помощь для задач по уходу за бэклогом в рамках домена Эンタprise-работах. مساعد تصفية الوعي يوفر مساعدة آلية لمهام تصفية الوعي داخل مجال تدفقات العمل المؤسسية. The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app Backlog Grooming Assistant 企业工作流程管理 项目管理 合规性 治理 企业集成模式 自动化工具 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
