INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/doc-workflow', 'doc-workflow', 'majiayu000', 'claude-skill-registry', 'community', 'doc-workflow majiayu000 claude-skill-registry community 本文介绍 Claude Code 的文档工作流技能，包括 llmdoc 文档系统和工作流指南。帮助开发者提高文档管理效率 本稿では、Claude Code のドキュメント ワークフロー スキルについて説明します。llmdoc ドキュメント システムとワークフロー ガイドを含み、開発者の文書管理効率を向上させます 본 문서는 Claude Code의 문서 작업 흐름 스킬을 소개합니다. llmdoc 문서 시스템과 작업 흐름 가이드를 포함하여 개발자의 문서 관리 효율성을 향상시킵니다 La habilidad doc-workflow proporciona orientación sobre el sistema de documentación llmdoc y los flujos de trabajo disponibles. La compétence doc-workflow fournit des conseils sur le système de documentation llmdoc et les flux de travail disponibles. Die Fähigkeit doc-workflow bietet Anleitung über das Dokumentationssystem llmdoc und die verfügbaren Workflows. O skill doc-workflow fornece orientação sobre o sistema de documentação llmdoc e fluxos de trabalho disponíveis. Навык doc-workflow предоставляет руководство по системе документации llmdoc и доступным рабочим процессам. يقدم مهارة doc-workflow إرشادات حول نظام توثيق llmdoc والتدفقات العملية المتاحة. The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app 文档工作流 llmdoc Claude Code 文档管理 开发效率 文档系统 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/parallel-task', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'parallel-task', 0, 0, 65, '2026-02-20T04:13:19.581Z', '2026-02-20T05:12:33.417Z', '75eca254bb3dcb067fa1636a2e19eab12336a2a1f30b7b880fee87015d04504e', '{"id":"majiayu000/claude-skill-registry/parallel-task","name":"parallel-task","description":{"zh":"并行任务执行器是一种管理子代理的工具，用于并行执行任务和依赖管理","ja":"並列タスク実行者はサブエージェントを管理するツールであり、タスクの並列実行と依存関係の管理を実現","ko":"병렬 작업 실행기는 하위 에이전트를 관리하는 도구로 작업을 병렬로 실행 및 의존성 관리","es":"El ejecutor de tareas paralelas es un orchestrador que delega tareas a subagentes de forma paralela","fr":"L''exécuteur de tâches parallèles est un orchestrateur qui délègue des tâches à des sous-agents de manière parallèle","de":"Der parallele Aufgaben-Ausführer ist ein Orchestrator, der Aufgaben an Subagenten parallel delegiert","pt":"O executor de tarefas paralelas é um orchestrador de subagentes que executa tarefas de forma paralela","ru":"Параллельный исполнитель задач является оркестратором субагентов, который выполняет задачи параллельно","ar":"منفذ المهام الموازية هو منسق للموكلين الفرعيين الذي ينفذ المهام بشكل موازي","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"并行任务执行器","ja":"並列タスク実行者","ko":"병렬 작업 실행기","es":"Ejecutor de Tareas Paralelas","fr":"Exécuteur de Tâches Parallèles","de":"Parallele Aufgaben-Ausführer","pt":"Executor de Tarefas Paralelas","ru":"Параллельный Исполнитель Задач","ar":"منفذ مهام موازية","en":"parallel-task"},"description":{"zh":"并行任务执行器是一种管理子代理的工具，用于并行执行任务和依赖管理","ja":"並列タスク実行者はサブエージェントを管理するツールであり、タスクの並列実行と依存関係の管理を実現","ko":"병렬 작업 실행기는 하위 에이전트를 관리하는 도구로 작업을 병렬로 실행 및 의존성 관리","es":"El ejecutor de tareas paralelas es un orchestrador que delega tareas a subagentes de forma paralela","fr":"L''exécuteur de tâches parallèles est un orchestrateur qui délègue des tâches à des sous-agents de manière parallèle","de":"Der parallele Aufgaben-Ausführer ist ein Orchestrator, der Aufgaben an Subagenten parallel delegiert","pt":"O executor de tarefas paralelas é um orchestrador de subagentes que executa tarefas de forma paralela","ru":"Параллельный исполнитель задач является оркестратором субагентов, который выполняет задачи параллельно","ar":"منفذ المهام الموازية هو منسق للموكلين الفرعيين الذي ينفذ المهام بشكل موازي","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"definition":{"en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"features":{"zh":["并行任务执行","子代理管理","任务依赖管理","计划文档更新","日志记录"],"ja":["並列タスク実行","サブエージェント管理","タスク依存関係管理","プラン文書更新","ログ記録"],"ko":["병렬 작업 실행","하위 에이전트 관리","작업 의존성 관리","계획 문서 업데이트","로그 기록"],"es":["Orquestación de tareas paralelas","Delegación de tareas a subagentes","Gestión de dependencias entre tareas","Actualización de documentos de planificación","Ejecución de tareas en bucle hasta su completación"],"fr":["Orchestration de tâches parallèles","Délégation de tâches à des sous-agents","Gestion des dépendances entre tâches","Mise à jour des documents de planification","Exécution de tâches en boucle jusqu''à leur completition"],"de":["Orchestrierung von parallelen Aufgaben","Delegierung von Aufgaben an Subagenten","Verwaltung von Abhängigkeiten zwischen Aufgaben","Aktualisierung von Planungsunterlagen","Ausführung von Aufgaben in einer Schleife bis zur Fertigstellung"],"pt":["Execução de tarefas paralelas","Orquestração de subagentes","Gestão de dependências de tarefas","Atualização de logs de tarefas","Melhoria da eficiência do código"],"ru":["Параллельное выполнение задач","Оркестрация субагентов","Управление зависимостями задач","Обновление журналов задач","Повышение эффективности кода"],"ar":["تنفيذ المهام الموازية","تنسيق الموكلين الفرعيين","إدارة التبعيات المهام","تحديث سجلات المهام","تحسين كفاءة الكود"]},"keywords":{"zh":["并行任务执行器","子代理管理","任务依赖管理","计划文档更新","日志记录","并行计算"],"ja":["並列タスク実行者","サブエージェント管理","タスク依存関係管理","プラン文書更新","ログ記録","並列計算"],"ko":["병렬 작업 실행기","하위 에이전트 관리","작업 의존성 관리","계획 문서 업데이트","로그 기록","병렬 계산"],"es":["tareas paralelas","orquestación de tareas","subagentes","dependencias entre tareas","planificación de tareas","optimización de rendimiento"],"fr":["tâches parallèles","orchestration de tâches","sous-agents","dépendances entre tâches","planification de tâches","optimisation des performances"],"de":["parallele Aufgaben","Orchestrierung von Aufgaben","Subagenten","Abhängigkeiten zwischen Aufgaben","Planung von Aufgaben","Leistungsoptimierung"],"pt":["tarefas paralelas","executor de tarefas","orquestração de subagentes","programação paralela","eficiência do código","desenvolvimento de software"],"ru":["параллельные задачи","исполнитель задач","оркестрация субагентов","параллельное программирование","эффективность кода","разработка программного обеспечения"],"ar":["المهام الموازية","منفذ المهام","تنسيق الموكلين الفرعيين","البرمجة الموازية","كفاءة الكود","تطوير البرمجيات"]}},"owner":"majiayu000","repo":"claude-skill-registry","repoPath":"majiayu000/claude-skill-registry","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.581Z","topics":[],"category":"community","skillMd":{"name":"parallel-task","description":">","bodyPreview":"# Parallel Task Executor\n\nYou are an Orchestrator for subagents. Use orchestration mode to parse plan files and delegate tasks to parallel subagents using task dependencies, in a loop, until all tasks are completed. Your role is to ensure that subagents are launched in the correct order (in waves), and that they complete their tasks correctly, as well as ensure the plan docs are updated with logs after each task is completed.\n\n## Process\n\n### Step 1: Parse Request\n\nExtract from user request:\n1.","body":"# Parallel Task Executor\n\nYou are an Orchestrator for subagents. Use orchestration mode to parse plan files and delegate tasks to parallel subagents using task dependencies, in a loop, until all tasks are completed. Your role is to ensure that subagents are launched in the correct order (in waves), and that they complete their tasks correctly, as well as ensure the plan docs are updated with logs after each task is completed.\n\n## Process\n\n### Step 1: Parse Request\n\nExtract from user request:\n1. **Plan file**: The markdown plan to read\n2. **Task subset** (optional): Specific task IDs to run\n\nIf no subset provided, run the full plan.\n\n### Step 2: Read & Parse Plan\n\n1. Find task subsections (e.g., `### T1:` or `### Task 1.1:`)\n2. For each task, extract:\n   - Task ID and name\n   - **depends_on** list (from `- **depends_on**: [...]`)\n   - Full content (description, location, acceptance criteria, validation)\n3. Build task list\n4. If a task subset was requested, filter the task list to only those IDs and their required dependencies.\n\n### Step 3: Launch Subagents\n\nFor each **unblocked** task, launch subagent with:\n- **description**: \"Implement task [ID]: [name]\"\n- **prompt**: Use template below\n\nLaunch all unblocked tasks in parallel. A task is unblocked if all IDs in its depends_on list are complete.\n\n### Task Prompt Template\n\n```\nYou are implementing a specific task from a development plan.\n\n## Context\n- Plan: [filename]\n- Goals: [relevant overview from plan]\n- Dependencies: [prerequisites for this task]\n- Related tasks: [tasks that depend on or are depended on by this task]\n- Constraints: [risks from plan]\n\n## Your Task\n**Task [ID]: [Name]**\n\nLocation: [File paths]\nDescription: [Full description]\n\nAcceptance Criteria:\n[List from plan]\n\nValidation:\n[Tests or verification from plan]\n\n## Instructions\n1. Examine working plan and any relevant or dependent files\n2. Implement changes for all acceptance criteria\n3. Keep work **atomic and committable**\n4. For each file: read first, edit carefully, preserve formatting\n5. Run validation if feasible\n6. **ALWAYS mark completed tasks IN THE *-plan.md file AS SOON AS YOU COMPLETE IT!** and update with:\n    - Concise work log\n    - Files modified/created\n    - Errors or gotchas encountered\n7. Commit your work\n   - Note: There are other agents working in parallel to you, so only stage and commit the files you worked on. NEVER PUSH. ONLY COMMIT.\n8. Double Check that you updated the *-plan.md file and committed your work before yielding\n9. Return summary of:\n   - Files modified/created\n   - Changes made\n   - How criteria are satisfied\n   - Validation performed or deferred\n\n## Important\n- Be careful with paths\n- Stop and describe blockers if encountered\n- Focus on this specific task\n```\n\nEnsure that the agent marked its task complete before moving on to the next task or set of tasks.\n\n### Step 4: Check and Validate.\n\nAfter a wave of subagents complete their work:\n1. Inspect their outputs for correctness and completeness.\n2. Validate the results against the expected outcomes.\n3. If the task is truly completed correctly, ENSURE THAT TASK WAS MARKED COMPLETE WITH LOGS.\n4. If a task was not successful, have the agent retry or escalate the issue.\n5. Ensure that that wave of work has been committed to github before moving on to the next wave of tasks.\n\n### Step 5: Repeat\n\n1. Review the plan again to see what new set of unblocked tasks are available.\n2. Continue launching unblocked tasks in parallel until plan is done.\n3. Repeat the process until *all** tasks are both complete, validated, and working without errors. \n\n\n## Error Handling\n\n- Task subset not found: List available task IDs\n- Parse failure: Show what was tried, ask for clarification\n\n## Example Usage\n\n```\n/parallel-task plan.md\n/parallel-task ./plans/auth-plan.md T1 T2 T4\n/parallel-task user-profile-plan.md --tasks T3 T7\n```\n\n## Execution Summary Template\n\n```markdown\n# Execution Summary\n\n## Tasks Assigned: [N]\n\n### Completed\n- Task [ID]: [Name] - [Brief summary]\n\n### Issues\n- Task [ID]: [Name]\n  - Issue: [What went wrong]\n  - Resolution: [How resolved or what''s needed]\n\n### Blocked\n- Task [ID]: [Name]\n  - Blocker: [What''s preventing completion]\n  - Next Steps: [What needs to happen]\n\n## Overall Status\n[Completion summary]\n\n## Files Modified\n[List of changed files]\n\n## Next Steps\n[Recommendations]\n```\n"},"lastSynced":"2026-02-20T05:12:33.417Z","agentAnalysis":{"suitability":{"en":"Ideal for Autonomous Agents requiring efficient task orchestration and parallel processing capabilities.","zh":"适合需要高效任务编排和并行处理能力的自主代理。","ja":"タスクの効率的なオーケストレーションと並行処理能力を必要とする自律エージェントに最適です。","ko":"효율적인 작업 오케스트레이션 및 병렬 처리 기능을 필요로 하는 자율 에이전트에 적합합니다.","es":"Ideal para Agentes Autónomos que requieren una orquestación de tareas eficiente y capacidades de procesamiento paralelo.","fr":"Idéal pour les Agents Autonomes nécessitant une orchestration de tâches efficace et des capacités de traitement parallèle.","de":"Ideal für Autonome Agenten, die eine effiziente Aufgabenorchestrierung und parallele Verarbeitungsfähigkeiten erfordern.","pt":"Ideal para Agentes Autônomos que exigem orquestração de tarefas eficiente e capacidades de processamento paralelo.","ru":"Идеально для автономных агентов, требующих эффективной оркестровки задач и возможностей параллельной обработки.","ar":"مثالي للوكلاء المستقلين الذين يتطلبون تنسيق مهام فعال وسمات المعالجة الموازية."},"recommendation":{"en":"Empowers agents to execute tasks in parallel using orchestration mode, delegate tasks to subagents based on task dependencies, and update plan documents with logs after each task completion, leveraging task dependencies and plan files.","zh":"赋予代理在编排模式下并行执行任务的能力，根据任务依赖将任务委托给子代理，并在每个任务完成后使用任务依赖和计划文件更新计划文档。","ja":"オーケストレーションモードでタスクを並行して実行し、タスク依存関係に基づいてタスクをサブエージェントに委任し、各タスクの完了後にタスク依存関係とプランファイルを使用してプランドキュメントを更新するエージェントの能力を付与します。","ko":"오케스트레이션 모드에서 작업을 병렬로 실행할 수 있는 능력과 작업 종속성에 따라 작업을 하위 에이전트에 위임하며 각 작업이 완료된 후에 작업 종속성과 계획 파일을 사용하여 계획 문서를 업데이트하는 에이전트의 능력을 부여합니다.","es":"Habilita a los agentes a ejecutar tareas en paralelo utilizando el modo de orquestación, delegar tareas a subagentes en función de las dependencias de las tareas y actualizar los documentos de planificación con registros después de cada finalización de tarea, aprovechando las dependencias de las tareas y los archivos de planificación.","fr":"Permet aux agents d''exécuter des tâches en parallèle en utilisant le mode d''orchestration, de déléguer des tâches à des sous-agents en fonction des dépendances des tâches et de mettre à jour les documents de planification avec des journaux après chaque achèvement de tâche, en exploitant les dépendances des tâches et les fichiers de planification.","de":"Ermöglicht es Agenten, Aufgaben parallel mithilfe des Orchestrierungsmodus auszuführen, Aufgaben an Subagenten basierend auf Aufgabenabhängigkeiten zu delegieren und Planunterlagen mit Protokollen nach jedem Aufgabenabschluss zu aktualisieren, wobei die Aufgabenabhängigkeiten und Plandateien genutzt werden.","pt":"Habilita os agentes a executar tarefas em paralelo usando o modo de orquestração, delegar tarefas a subagentes com base nas dependências de tarefas e atualizar documentos de plano com logs após a conclusão de cada tarefa, aproveitando as dependências de tarefas e arquivos de plano.","ru":"Наделяет агентов возможностью выполнять задачи параллельно с помощью режима оркестровки, делегировать задачи субагентам на основе зависимостей задач и обновлять документы плана с журналами после завершения каждой задачи, используя зависимости задач и файлы плана.","ar":"تمكّن الوكلاء من تشغيل المهام بالتوازي باستخدام وضع التنسيق، وتفويض المهام إلى وكلاء فرعيين بناءً على اعتمادات المهام، وتحديث وثائق الخطة بسجلات بعد إكمال كل مهمة، مستفيداً من اعتمادات المهام ومستندات الخطة."},"useCases":{"en":["Orchestrating complex workflows with interdependent tasks","Executing parallel tasks to improve agent responsiveness","Managing subagents to optimize task completion rates"],"zh":["编排具有相互依赖的复杂工作流程","使用并行任务来提高代理响应速度","管理子代理以优化任务完成率"],"ja":["相互依存タスクを持つ複雑なワークフローのオーケストレーション","並行タスクを使用してエージェントのレスポンス性を向上させる","サブエージェントを管理してタスク完了率を最適化する"],"ko":["상호 종속 작업을 가진 복잡한 워크플로우 오케스트레이션","병렬 작업을 사용하여 에이전트의 응답 속도를 개선하는 것","하위 에이전트를 관리하여 작업 완료율을 최적화하는 것"],"es":["Orquestar flujos de trabajo complejos con tareas interdependientes","Ejecutar tareas paralelas para mejorar la respuesta del agente","Gestionar subagentes para optimizar las tasas de finalización de tareas"],"fr":["Orchestrer des flux de travail complexes avec des tâches interdépendantes","Exécuter des tâches parallèles pour améliorer la réactivité de l''agent","Gérer des sous-agents pour optimiser les taux d''achèvement des tâches"],"de":["Komplexe Workflows mit voneinander abhängigen Aufgaben orchestrieren","Parallele Aufgaben ausführen, um die Reaktionsfähigkeit des Agenten zu verbessern","Subagenten verwalten, um die Aufgabenabschlussraten zu optimieren"],"pt":["Orquestrar fluxos de trabalho complexos com tarefas interdependentes","Executar tarefas paralelas para melhorar a capacidade de resposta do agente","Gerenciar subagentes para otimizar as taxas de conclusão de tarefas"],"ru":["Оркестровка сложных рабочих процессов с взаимозависимыми задачами","Выполнение параллельных задач для улучшения отзывчивости агента","Управление субагентами для оптимизации скорости завершения задач"],"ar":["تنسيق سلاسل عمل معقدة ذات مهام متعلقة","تشغيل مهام متوازية لتحسين استجابة الوكيل","إدارة الوكلاء الفرعيين لتحسين معدلات إكمال المهام"]},"limitations":{"en":["Requires plan files with defined task dependencies","Limited to agents capable of subagent delegation and orchestration mode"],"zh":["需要具有定义的任务依赖的计划文件","仅限于能够委托子代理和编排模式的代理"],"ja":["定義されたタスク依存関係を持つプランファイルが必要","サブエージェントの委任とオーケストレーションモードが可能なエージェントに限定される"],"ko":["정의된 작업 종속성을 가진 계획 파일이 필요","하위 에이전트의 위임 및 오케스트레이션 모드가 가능한 에이전트로 제한됨"],"es":["Requiere archivos de planificación con dependencias de tareas definidas","Limitado a agentes capaces de delegación de subagentes y modo de orquestación"],"fr":["Nécessite des fichiers de planification avec des dépendances de tâches définies","Limité aux agents capables de délégation de sous-agents et de mode d''orchestration"],"de":["Benötigt Planungsdateien mit definierten Aufgabenabhängigkeiten","Begrenzt auf Agenten, die eine Delegierung von Subagenten und Orchestrierungsmodus unterstützen"],"pt":["Exige arquivos de plano com dependências de tarefas definidas","Limitado a agentes capazes de delegação de subagentes e modo de orquestração"],"ru":["Требует файлов плана с определёнными зависимостями задач","Ограничен агентами, способными к делегированию субагентов и режиму оркестровки"],"ar":["يتطلب ملفات خطة مع اعتمادات مهام محددة","محدود بالوكلاء القادرة على تفويض الوكلاء الفرعيين ووضع التنسيق"]},"version":3},"contentHash":"75eca254bb3dcb067fa1636a2e19eab12336a2a1f30b7b880fee87015d04504e","qualityScore":65}');
