INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nodays-off/rack-reserve/ffmpeg', 'ffmpeg', 'nodays-off', 'rack-reserve', 'community', 'ffmpeg nodays-off rack-reserve community ffmpeg AI工具是一种服务器硬件兼容性检查工具，帮助开发者验证服务器硬件是否兼容 ffmpeg AIエージェントはサーバーハードウェアの互換性を確認するツールです ffmpeg AI 에이전트는 서버 하드웨어 호환성을 확인하는 도구입니다 ffmpeg es una herramienta de Inteligencia Artificial para verificar la compatibilidad de hardware de servidor. Verifica componentes de servidor. ffmpeg est un outil d''Intelligence Artificielle pour vérifier la compatibilité du matériel serveur. Vérifiez les composants du serveur. ffmpeg ist ein KI-Tool zum Überprüfen der Server-Hardware-Kompatibilität. Überprüft Serverkomponenten. O ffmpeg é uma ferramenta de linha de comando para processamento de vídeo e áudio, e pode ser usado para verificar a compatibilidade de hardware de servidor. ИИ Агенты: ffmpeg - это инструмент командной строки для обработки видео и аудио, используемый для проверки совместимости серверного оборудования. ffmpeg هي أداة سطر أوامر لمعالجة الفيديو والصوت، يمكن استخدامها لفحص توافق الأجهزة الخادوم Server hardware compatibility checker - instantly verify if parts work with your server ffmpeg AI工具 服务器硬件兼容性检查 AI工具 ffmpeg安装 ffmpeg设置 服务器硬件兼容性 ffmpeg使用 ffmpeg教程 服务器硬件检查 Server hardware compatibility checker - instantly verify if parts work with your server');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('masx200/http-proxy-go-server/github-cli', 'community', 'masx200', 'http-proxy-go-server', 'masx200/http-proxy-go-server', 'github-cli', 0, 0, 65, '2026-03-06T06:23:00.159Z', '2026-03-06T07:23:46.578Z', 'b3ecba7721483e8030119571f54fa70157a9439d3545cf689ddcfad94a58782a', '{"id":"masx200/http-proxy-go-server/github-cli","name":"github-cli","description":{"en":"The github-cli skill enables developers to work with GitHub from the command line, covering repository management, issues, and authentication. It benefits developers who need to manage GitHub operations efficiently.","zh":"GitHub CLI（gh）是一种命令行工具，用于管理 GitHub 仓库和相关操作","ja":"GitHub CLI（gh）は、GitHub リポジトリと関連操作を管理するためのコマンドラインツール","ko":"GitHub CLI(gh)는 GitHub 리포지토리와 관련 작업을 관리하는 명령어 인터페이스","pt":"O GitHub CLI é uma ferramenta poderosa para desenvolvedores, permitindo gerenciar repositórios, problemas e solicitações de pull de forma eficiente.","ru":"GitHub CLI — это мощный инструмент для разработчиков, позволяющий эффективно управлять репозиториями, проблемами и запросами на включение.","ar":"واجهة سطر الأوامر GitHub هي أداة قوية لمطوري البرمجيات، تمكنهم من إدارة المستودعات والمشكلات وطلبات السحب بفعالية"},"seo":{"title":{"en":"github-cli: Master GitHub Operations Setup Guide | AI Age...","zh":"GitHub CLI Setup Guide - AIエージェント","ja":"GitHub CLI ベストプラクティス - AIエージェント","ko":"GitHub CLI 사용법 - AI Tools","pt":"Guia de Configuração do GitHub CLI: Ferramentas de Desenv...","ru":"ИИ Агенты: Настройка GitHub CLI для Продуктивной Работы","ar":"إعداد واجهة سطر الأوامر GitHub: أداة تطوير ممتازة"},"description":{"en":"Unlock seamless GitHub workflow with github-cli. Learn how to create PRs, manage repositories, and authenticate with ease. Get started now!","zh":"学习 GitHub CLI（gh）命令行工具，实现 GitHub 仓库管理、问题、拉取请求、发布等操作","ja":"GitHub CLI（gh）をマスターして、GitHub リポジトリの管理、イシュー、プルリクエスト、リリースなどを効率化","ko":"GitHub CLI(gh)로 GitHub 리포지토리 관리, 이슈, 풀 리퀘스트, 릴리즈 등 작업 자동화","pt":"Aprenda a dominar o GitHub CLI para trabalhar de forma eficiente com repositórios, problemas, solicitações de pull e muito mais.","ru":"Освойте GitHub CLI для продуктивной работы с репозиториями, проблемами, запросами на включение и другими функциями.","ar":"تعلم كيفية العمل بفعالية مع واجهة سطر الأوامر GitHub لتحقيق أقصى استفادة من مستودعاتك والمشكلات والطلبات وسجلات الإصدار"},"definition":{"en":"github-cli is a command-line interface for GitHub that allows developers to manage repositories, issues, and pull requests, among other operations.","zh":"GitHub CLI（gh）是 GitHub 官方提供的命令行工具","ja":"GitHub CLI（gh）は、GitHub 公式のコマンドラインツール","ko":"GitHub CLI(gh)는 GitHub에서 제공하는 공식 명령어 인터페이스","pt":"O GitHub CLI é uma interface de linha de comando para interagir com o GitHub, permitindo gerenciar repositórios e realizar operações.","ru":"GitHub CLI — это интерфейс командной строки для взаимодействия с GitHub, позволяющий управлять репозиториями и выполнять операции.","ar":"واجهة سطر الأوامر GitHub هي واجهة سطر الأوامر للتفاعل مع GitHub، تمكن من إدارة المستودعات والقيام بالعمليات"},"features":{"en":["Manages GitHub repositories using the `gh` command","Creates and manages pull requests, issues, and releases","Handles authentication with GitHub using `gh auth`","Supports working with GitHub Actions and codespaces","Enables cloning, forking, and updating repositories with ease"],"zh":["仓库管理","问题和拉取请求管理","发布和认证管理","GitHub Actions 集成","代码空间管理"],"ja":["リポジトリ管理","イシューとプルリクエスト管理","リリースと認証管理","GitHub Actions 統合","コードスペース管理"],"ko":["리포지토리 관리","이슈와 풀 리퀘스트 관리","릴리즈와 인증 관리","GitHub Actions 통합","코드스페이스 관리"],"pt":["Gerenciamento de repositórios","Criação e gerenciamento de problemas","Criação e gerenciamento de solicitações de pull","Autenticação com o GitHub","Trabalho com GitHub Actions","Gerenciamento de codespaces"],"ru":["Управление репозиториями","Создание и управление проблемами","Создание и управление запросами на включение","Аутентификация с GitHub","Работа с GitHub Actions","Управление codespaces"],"ar":["إدارة المستودعات","إنشاء وتحديث المشكلات","إنشاء وتحديث طلبات السحب","التحقق من هوية المستخدم مع GitHub","العمل مع إجراءات GitHub","إدارة مساحات التعليمات البرمجية"]},"keywords":{"en":["how to use github-cli","github-cli setup guide","github-cli vs git","github-cli install","github-cli tutorial","github-cli alternative"],"zh":["GitHub CLI","gh命令行工具","GitHub 仓库管理","问题和拉取请求","发布和认证","GitHub Actions","代码空间","AIエージェント"],"ja":["GitHub CLI","ghコマンドラインツール","GitHub リポジトリ管理","イシューとプルリクエスト","リリースと認証","GitHub Actions","コードスペース","AIエージェント"],"ko":["GitHub CLI","gh 명령어 인터페이스","GitHub 리포지토리 관리","이슈와 풀 리퀘스트","릴리즈와 인증","GitHub Actions","코드스페이스","AI Tools"],"pt":["github cli","ferramentas de desenvolvimento","gerenciamento de repositórios","problemas github","solicitações de pull","autenticação github","github actions","codespaces","desenvolvimento de software"],"ru":["github cli","инструменты разработки","управление репозиториями","проблемы github","запросы на включение","аутентификация github","github actions","codespaces","разработка программного обеспечения"],"ar":["واجهة سطر الأوامر github","أدوات التطوير","إدارة المستودعات","مشكلات github","طلبات السحب","التحقق من هوية المستخدم github","إجراءات github","مساحات التعليمات البرمجية","تطوير البرمجيات"]}},"owner":"masx200","repo":"http-proxy-go-server","repoPath":"masx200/http-proxy-go-server","stars":0,"forks":0,"updatedAt":"2026-03-06T06:23:00.159Z","topics":[],"category":"community","skillMd":{"name":"github-cli","description":"Use this skill when the user asks to work with GitHub from the command line using gh CLI. This includes managing repositories, issues, pull requests, releases, authentication, codespaces, actions, and any other GitHub operations. Use this skill for phrases like create a PR, manage issues, clone a repo, check gh status, or any GitHub CLI workflow.","version":"1.0.0","bodyPreview":"# GitHub CLI (gh) Comprehensive Skill\n\nMaster the GitHub CLI (`gh`) to seamlessly work with GitHub from the command\nline. This skill covers all major GitHub operations including repository\nmanagement, issues, pull requests, releases, authentication, and more.\n\n## When to Use This Skill\n\nTrigger this skill when the user asks to:\n\n- \"Create a PR/issue/release\"\n- \"Manage GitHub repository\"\n- \"Clone/fork/update a repo\"\n- \"Check/authenticate with gh\"\n- \"Work with GitHub Actions\"\n- \"Manage codespaces\"","body":"# GitHub CLI (gh) Comprehensive Skill\n\nMaster the GitHub CLI (`gh`) to seamlessly work with GitHub from the command\nline. This skill covers all major GitHub operations including repository\nmanagement, issues, pull requests, releases, authentication, and more.\n\n## When to Use This Skill\n\nTrigger this skill when the user asks to:\n\n- \"Create a PR/issue/release\"\n- \"Manage GitHub repository\"\n- \"Clone/fork/update a repo\"\n- \"Check/authenticate with gh\"\n- \"Work with GitHub Actions\"\n- \"Manage codespaces\"\n- \"Search repos/issues/PRs\"\n- Any GitHub CLI operation\n\n## Prerequisites\n\n### Installation & Authentication\n\n**Check if gh is installed:**\n\n```bash\ngh --version\n```\n\n**Install gh (if not installed):**\n\n```bash\n# macOS\nbrew install gh\n\n# Windows (winget)\nwinget install --id GitHub.cli\n\n# Linux\ncurl -fsSL https://cli.github.com/packages/githubcli-archive-keyring.gpg | sudo dd of=/usr/share/keyrings/githubcli-archive-keyring.gpg\necho \"deb [arch=$(dpkg --print-architecture) signed-by=/usr/share/keyrings/githubcli-archive-keyring.gpg] https://cli.github.com/packages stable main\" | sudo tee /etc/apt/sources.list.d/github-cli.list > /dev/null\nsudo apt update\nsudo apt install gh\n```\n\n**Authenticate with GitHub:**\n\n```bash\ngh auth login\n# Follow prompts:\n# - GitHub.com\n# - HTTPS protocol\n# - Login with web browser OR token\n```\n\n**Verify authentication:**\n\n```bash\ngh auth status\n```\n\nExpected output:\n\n```\ngithub.com\n  ✓ Logged in to github.com account <username> (keyring)\n  - Active account: true\n  - Git operations protocol: https\n  - Token: ghp_************************************\n```\n\n## Core Command Categories\n\n### 1. Repository Management\n\n#### View Repository Info\n\n```bash\n# View current repository\ngh repo view\n\n# View specific repository\ngh repo view owner/repo\n\n# View with JSON output\ngh repo view --json name,description,visibility,owner\n\n# Open repository in browser\ngh repo view --web\n```\n\n#### Clone Repository\n\n```bash\n# Clone current repository (if in directory)\ngh repo clone\n\n# Clone specific repository\ngh repo clone owner/repo\n\n# Clone to specific directory\ngh repo clone owner/repo my-directory\n\n# Clone with SSH\ngh repo clone owner/repo -- --ssh\n```\n\n#### Create Repository\n\n```bash\n# Create new repository (interactive)\ngh repo create\n\n# Create with specific settings\ngh repo create my-repo \\\n  --public \\\n  --description \"My awesome repository\" \\\n  --source=. \\\n  --remote=origin \\\n  --push\n\n# Create private repository\ngh repo create my-private-repo --private\n\n# Create without cloning\ngh repo create my-repo --clone=false\n```\n\n#### Fork Repository\n\n```bash\n# Fork repository\ngh repo fork owner/repo\n\n# Fork to specific organization\ngh repo fork owner/repo --org my-org\n\n# Fork and clone\ngh repo fork owner/repo --clone\n```\n\n#### Update Repository Settings\n\n```bash\n# Update repository description\ngh repo edit --description \"New description\"\n\n# Change visibility\ngh repo edit --visibility private\n\n# Add topics\ngh repo edit --add-topic \"golang\" --add-topic \"proxy\"\n\n# Set default branch\ngh repo edit --default-branch main\n```\n\n### 2. Issue Management\n\n#### List Issues\n\n```bash\n# List issues in current repository\ngh issue list\n\n# List with filters\ngh issue list \\\n  --state open \\\n  --author masx200 \\\n  --label bug,enhancement \\\n  --limit 20\n\n# List closed issues\ngh issue list --state closed\n\n# List with JSON output\ngh issue list --json number,title,state,labels\n\n# List across repositories\ngh issue list --repo owner/repo1 --repo owner/repo2\n```\n\n#### View Issue\n\n```bash\n# View specific issue\ngh issue view 123\n\n# View with comments\ngh issue view 123 --comments\n\n# View in browser\ngh issue view 123 --web\n\n# View as JSON\ngh issue view 123 --json title,body,comments\n```\n\n#### Create Issue\n\n```bash\n# Create interactively\ngh issue create\n\n# Create with title and body\ngh issue create \\\n  --title \"Bug in authentication\" \\\n  --body \"Detailed description of the bug\"\n\n# Create with labels\ngh issue create \\\n  --title \"Feature request\" \\\n  --body \"Feature description\" \\\n  --label enhancement,good-first-issue\n\n# Create with assignees\ngh issue create \\\n  --title \"Fix critical bug\" \\\n  --body \"Bug details\" \\\n  --assignee @me\n\n# Create with template\ngh issue create --template bug-report.md\n```\n\n#### Edit Issue\n\n```bash\n# Edit issue interactively\ngh issue edit 123\n\n# Add comment\ngh issue comment 123 --body \"This is a comment\"\n\n# Add labels\ngh issue edit 123 --add-label \"bug,priority\"\n\n# Remove labels\ngh issue edit 123 --remove-label \"wontfix\"\n\n# Change state\ngh issue close 123\ngh issue reopen 123\n\n# Add assignees\ngh issue edit 123 --add-assignee username1,username2\n\n# Remove assignees\ngh issue edit 123 --remove-assignee username1\n```\n\n#### Search Issues\n\n```bash\n# Search issues\ngh issue search \"authentication\" --open\n\n# Search across repos\ngh search issues --repo owner/repo \"label:bug\"\n\n# Advanced search\ngh search issues \\\n  --state open \\\n  --label \"good first issue\" \\\n  --language go \\\n  \"stars:>100\"\n```\n\n### 3. Pull Request Management\n\n#### List Pull Requests\n\n```bash\n# List PRs in current repository\ngh pr list\n\n# List with filters\ngh pr list \\\n  --state open \\\n  --author masx200 \\\n  --base main \\\n  --limit 20\n\n# List merged PRs\ngh pr list --state merged\n\n# List ready for review\ngh pr list --state open --review required\n\n# List with JSON output\ngh pr list --json number,title,state,author,headRefName\n```\n\n#### View Pull Request\n\n```bash\n# View specific PR\ngh pr view 123\n\n# View with diffs\ngh pr view 123 --diff\n\n# View with comments\ngh pr view 123 --comments\n\n# View checks/status\ngh pr view 123 --json statusCheckRollup\n\n# View in browser\ngh pr view 123 --web\n```\n\n#### Create Pull Request\n\n```bash\n# Create PR interactively\ngh pr create\n\n# Create with title and body\ngh pr create \\\n  --title \"Add new feature\" \\\n  --body \"Description of changes\"\n\n# Create from specific branch\ngh pr create \\\n  --base main \\\n  --head feature-branch \\\n  --title \"Feature implementation\"\n\n# Create with reviewers\ngh pr create \\\n  --title \"Refactor code\" \\\n  --body \"Refactoring details\" \\\n  --reviewer username1,username2\n\n# Create with labels\ngh pr create \\\n  --title \"Bug fix\" \\\n  --label bug,priority-high\n\n# Create with draft\ngh pr create \\\n  --title \"WIP feature\" \\\n  --body \"Work in progress\" \\\n  --draft\n\n# Create from issue\ngh pr create \\\n  --issue 123 \\\n  --title \"Fix issue #123\"\n\n# Create with template\ngh pr create --template pr-template.md\n```\n\n#### Checkout Pull Request\n\n```bash\n# Checkout PR (alias: gh pr checkout)\ngh pr checkout 123\n\n# Checkout and create branch\ngh pr checkout 123 --branchname pr-123\n```\n\n#### Edit Pull Request\n\n```bash\n# Edit PR interactively\ngh pr edit 123\n\n# Add reviewers\ngh pr edit 123 --add-reviewer username1,username2\n\n# Add assignees\ngh pr edit 123 --add-assignee username1\n\n# Change title\ngh pr edit 123 --title \"Updated title\"\n\n# Add labels\ngh pr edit 123 --add-label \"needs-review\"\n\n# Remove labels\ngh pr edit 123 --remove-label \"wip\"\n\n# Convert to draft\ngh pr edit 123 --mark-draft\n\n# Ready for review (remove draft)\ngh pr edit 123 --ready-for-review\n```\n\n#### Manage Pull Request Reviews\n\n```bash\n# Request review\ngh pr edit 123 --add-reviewer username\n\n# View reviews\ngh pr view 123 --json reviews --jq ''.reviews[]''\n\n# Approve PR\ngh pr review 123 --approve --body \"LGTM!\"\n\n# Request changes\ngh pr review 123 --request-changes --body \"Please fix these issues\"\n\n# Comment on PR\ngh pr review 123 --comment --body \"Just a comment\"\n\n# Dismiss reviews\ngh pr review 123 --dismiss \"No longer relevant\"\n```\n\n#### Merge Pull Request\n\n```bash\n# Merge PR\ngh pr merge 123\n\n# Merge with specific method\ngh pr merge 123 --merge\ngh pr merge 123 --squash\ngh pr merge 123 --rebase\n\n# Merge with commit title/body\ngh pr merge 123 \\\n  --merge \\\n  --subject \"Merge PR #123\" \\\n  --body \"Detailed message\"\n\n# Delete branch after merge\ngh pr merge 123 --delete-branch\n\n# Merge without confirmation\ngh pr merge 123 --yes\n```\n\n#### Close/Reopen Pull Request\n\n```bash\n# Close PR\ngh pr close 123\n\n# Close with comment\ngh pr close 123 --comment \"Superseded by PR #456\"\n\n# Reopen PR\ngh pr reopen 123\n```\n\n### 4. Authentication Management\n\n#### Login/Logout\n\n```bash\n# Login\ngh auth login\n\n# Login to GitHub Enterprise\ngh auth login --hostname enterprise.github.com\n\n# Logout\ngh auth logout\n\n# Logout from specific hostname\ngh auth logout --hostname enterprise.github.com\n```\n\n#### Status & Token\n\n```bash\n# Check auth status\ngh auth status\n\n# Get authentication token\ngh auth token\n\n# Get token for specific hostname\ngh auth token --hostname enterprise.github.com\n```\n\n#### Switch Accounts\n\n```bash\n# Switch active account\ngh auth switch --username username\n\n# Refresh credentials\ngh auth refresh\n```\n\n#### Git Integration\n\n```bash\n# Setup git with gh credentials\ngh auth setup-git\n\n# This configures git to use gh for authentication\n# instead of password prompts\n```\n\n### 5. Codespaces Management\n\n#### List Codespaces\n\n```bash\n# List all codespaces\ngh codespace list\n\n# List for specific repository\ngh codespace list --repo owner/repo\n\n# List with detailed info\ngh codespace list --json name,state,repository,createdAt\n```\n\n#### Create Codespace\n\n```bash\n# Create codespace\ngh codespace create\n\n# Create for specific branch\ngh codespace create --branch main\n\n# Create with specific machine\ngh codespace create --machine standardLinux32gb\n\n# Create and open in browser\ngh codespace create --web\n```\n\n#### Connect to Codespace\n\n```bash\n# Connect interactively\ngh codespace codespace\n\n# SSH into codespace\ngh codespace ssh --codespace codespace-name\n\n# Open in VS Code\ngh codespace code --codespace codespace-name\n\n# Open in browser\ngh codespace view --web --codespace codespace-name\n```\n\n#### Delete Codespace\n\n```bash\n# Delete codespace\ngh codespace delete --codespace codespace-name\n\n# Delete all codespaces\ngh codespace delete --all\n```\n\n### 6. GitHub Actions Management\n\n#### List Workflow Runs\n\n```bash\n# List recent workflow runs\ngh run list\n\n# List for specific workflow\ngh run list --workflow \"ci.yml\"\n\n# List with branch filter\ngh run list --branch main\n\n# List with limit\ngh run list --limit 50\n\n# List with JSON output\ngh run list --json databaseId,status,conclusion,event,headBranch\n```\n\n#### View Run Details\n\n```bash\n# View run details\ngh run view 123456789\n\n# View with logs\ngh run view 123456789 --log\n\n# View with failed jobs\ngh run view 123456789 --log-failed\n\n# View in browser\ngh run view 123456789 --web\n\n# Watch run in real-time\ngh run watch 123456789\n```\n\n#### Rerun Workflows\n\n```bash\n# Rerun failed tests\ngh run rerun 123456789\n\n# Rerun all failed jobs\ngh run rerun 123456789 --failed\n\n# Cancel run\ngh run cancel 123456789\n\n# Trigger workflow\ngh workflow run ci.yml\n```\n\n#### Manage Workflow Files\n\n```bash\n# List workflows\ngh workflow list\n\n# View workflow\ngh workflow view ci.yml\n\n# View workflow YAML\ngh workflow view ci.yml --yaml\n\n# Enable workflow\ngh workflow enable ci.yml\n\n# Disable workflow\ngh workflow disable ci.yml\n```\n\n### 7. Release Management\n\n#### List Releases\n\n```bash\n# List releases\ngh release list\n\n# List with limit\ngh release list --limit 20\n\n# List with JSON output\ngh release list --json name,tagName,publishedAt\n```\n\n#### View Release\n\n```bash\n# View specific release\ngh release view v1.0.0\n\n# View latest release\ngh release view --latest\n\n# View in browser\ngh release view v1.0.0 --web\n\n# Download release assets\ngh release download v1.0.0\n\n# Download specific assets\ngh release download v1.0.0 --pattern \"*.tar.gz\"\n```\n\n#### Create Release\n\n```bash\n# Create release\ngh release create v1.0.0\n\n# Create with title and notes\ngh release create v1.0.0 \\\n  --title \"Version 1.0.0\" \\\n  --notes \"Release notes here\"\n\n# Create from notes file\ngh release create v1.0.0 \\\n  --notes-file RELEASE_NOTES.md\n\n# Create draft release\ngh release create v1.0.0 \\\n  --notes \"Draft notes\" \\\n  --draft\n\n# Create pre-release\ngh release create v1.0.0-beta.1 \\\n  --notes \"Beta release\" \\\n  --prerelease\n\n# Create with target commit\ngh release create v1.0.0 \\\n  --target main \\\n  --notes \"Release notes\"\n\n# Create with assets\ngh release create v1.0.0 \\\n  --notes \"Release\" \\\n  ./dist/binary-linux \\\n  ./dist/binary-darwin \\\n  ./dist/binary-windows.exe\n```\n\n#### Edit/Delete Release\n\n```bash\n# Edit release\ngh release edit v1.0.0 --notes \"Updated notes\"\n\n# Delete release\ngh release delete v1.0.0 --yes\n```\n\n### 8. Search & Browse\n\n#### Search Repositories\n\n```bash\n# Search repositories\ngh search repos \"http proxy\"\n\n# Search with filters\ngh search repos \\\n  --language go \\\n  --stars \">100\" \\\n  \"http proxy\"\n\n# Search in specific topic\ngh search repos --topic \"proxy\"\n\n# Search with JSON output\ngh search repos \"proxy\" --json name,description,stargazersCount --limit 10\n```\n\n#### Search Issues & PRs\n\n```bash\n# Search issues\ngh search issues \"label:bug state:open\"\n\n# Search PRs\ngh search prs \"state:open author:masx200\"\n\n# Search code\ngh search code \"language:go Proxy()\"\n```\n\n#### Browse in Browser\n\n```bash\n# Open repository in browser\ngh browse\n\n# Open specific file\ngh browse --branch main --filename README.md\n\n# Open issues\ngh browse --issues\n\n# Open PRs\ngh browse --pulls\n\n# Open specific PR\ngh browse --commit 9a8ebda\n\n# Open settings\ngh browse --settings\n```\n\n### 9. Organization Management\n\n#### View Organization\n\n```bash\n# View organization\ngh org view my-org\n\n# View with JSON\ngh org view my-org --json name,description,teams\n\n# View in browser\ngh org view my-org --web\n```\n\n#### List Organization Members\n\n```bash\n# List members\ngh org list-members my-org\n\n# List with role filter\ngh org list-members my-org --role admin\n\n# List with JSON output\ngh org list-members my-org --json login,role\n```\n\n#### Manage Organization Repositories\n\n```bash\n# List organization repos\ngh repo list my-org\n\n# Create org repository\ngh repo create my-org/new-repo --public\n```\n\n### 10. Gist Management\n\n#### List Gists\n\n```bash\n# List your gists\ngh gist list\n\n# List all gists (including starred)\ngh gist list --public\n\n# List with limit\ngh gist list --limit 50\n```\n\n#### View Gist\n\n```bash\n# View gist\ngh gist view gist-id\n\n# View in browser\ngh gist view gist-id --web\n\n# View with files\ngh gist view gist-id --files\n```\n\n#### Create/Edit Gist\n\n```bash\n# Create gist\ngh gist create file.txt\n\n# Create with description\ngh gist create file.txt --desc \"My gist\"\n\n# Create public gist\ngh gist create file.txt --public\n\n# Create secret gist\ngh gist create file.txt --private\n\n# Edit gist\ngh gist edit gist-id --file new-file.txt\n\n# Delete gist\ngh gist delete gist-id\n```\n\n### 11. Label Management\n\n#### List Labels\n\n```bash\n# List labels in current repo\ngh label list\n\n# List with colors\ngh label list --json name,color,description\n```\n\n#### Create Label\n\n```bash\n# Create label\ngh label create \"bug\" \\\n  --color \"d73a4a\" \\\n  --description \"Something isn''t working\"\n\n# Create with hex color\ngh label create \"enhancement\" \\\n  --color \"#a2eeef\" \\\n  --description \"New feature or request\"\n```\n\n#### Edit/Delete Label\n\n```bash\n# Edit label\ngh label edit \"bug\" --color \"ff0000\"\n\n# Delete label\ngh label delete \"wontfix\" --yes\n```\n\n### 12. Project Management\n\n#### List Projects\n\n```bash\n# List projects in current repo\ngh project list\n\n# List projects in org\ngh project list --org my-org\n\n# List with JSON output\ngh project list --json number,title,state\n```\n\n#### View Project\n\n```bash\n# View project\ngh project view 1\n\n# View with items\ngh project view 1 --json title,status,items\n\n# View in browser\ngh project view 1 --web\n```\n\n### 13. Status Command\n\n#### Check Status\n\n```bash\n# Check status (issues, PRs, notifications)\ngh status\n\n# Check with specific repos\ngh status --repo owner/repo1 --repo owner/repo2\n\n# Check with limit\ngh status --limit 10\n```\n\n### 14. Alias & Extensions\n\n#### Create Aliases\n\n```bash\n# Create alias for command\ngh alias set prc ''pr create''\n\n# Create complex alias\ngh alias set list-prs ''pr list --state open --limit 20''\n\n# List aliases\ngh alias list\n\n# Delete alias\ngh alias delete prc\n```\n\n#### Manage Extensions\n\n```bash\n# Install extension\ngh extension install owner/extension-repo\n\n# List extensions\ngh extension list\n\n# Remove extension\ngh extension remove extension-name\n```\n\n### 15. API Requests\n\n#### Make API Requests\n\n```bash\n# Make authenticated API request\ngh api /user\n\n# Make request with query parameters\ngh api \"/repos/masx200/http-proxy-go-server/issues?state=open\"\n\n# Make POST request\ngh api \\\n  --method POST \\\n  -H \"Accept: application/vnd.github.v3+json\" \\\n  /repos/owner/repo/issues \\\n  -f title=\"New issue\" \\\n  -f body=\"Issue description\"\n\n# Make request with JSON input\ngh api \\\n  --method PATCH \\\n  /repos/owner/repo/issues/123 \\\n  -f state=closed\n\n# Get paginated results\ngh api /user/repos --paginate\n\n# Use jq to filter results\ngh api /user | jq ''.name, .public_repos''\n```\n\n### 16. Configuration\n\n#### View Configuration\n\n```bash\n# View all config\ngh config set\n\n# View specific config\ngh config get git_protocol\n\n# Set config\ngh config set git_protocol ssh\ngh config set editor vim\ngh config set prompt enabled\n```\n\n#### Configuration Options\n\n```bash\n# Set git protocol\ngh config set git_protocol ssh   # or https\n\n# Set editor for editing text\ngh config set editor code --wait\n\n# Enable/disable prompts\ngh config set prompt enabled    # or disabled\n\n# Set pagination\ngh config set pager less\n```\n\n### 17. SSH & GPG Keys\n\n#### SSH Keys\n\n```bash\n# List SSH keys\ngh ssh-key list\n\n# Add SSH key\ngh ssh-key add ~/.ssh/id_ed25519 --title \"My laptop\"\n\n# Delete SSH key\ngh ssh-key delete 123456789\n```\n\n#### GPG Keys\n\n```bash\n# List GPG keys\ngh gpg-key list\n\n# Add GPG key\ngh gpg-key add ~/.ssh/mykey.asc\n\n# Delete GPG key\ngh gpg-key delete 123456789\n```\n\n### 18. Secrets Management\n\n#### List Secrets\n\n```bash\n# List repository secrets\ngh secret list\n\n# List organization secrets\ngh secret list --org my-org\n\n# List environment secrets\ngh secret list --env production\n```\n\n#### Set/Delete Secret\n\n```bash\n# Set secret (interactive)\ngh secret set MY_SECRET\n\n# Set secret from file\ngh secret set MY_SECRET < secret.txt\n\n# Set secret for environment\ngh secret set MY_SECRET --env production\n\n# Delete secret\ngh secret delete MY_SECRET\n```\n\n### 19. Variables Management (GitHub Actions)\n\n#### List Variables\n\n```bash\n# List variables\ngh variable list\n\n# List with JSON output\ngh variable list --json name,value\n```\n\n#### Set/Delete Variable\n\n```bash\n# Set variable\ngh variable set VAR_NAME \"value\"\n\n# Set variable for environment\ngh variable set VAR_NAME \"value\" --env production\n\n# Delete variable\ngh variable delete VAR_NAME\n```\n\n### 20. Completion Scripts\n\n#### Generate Shell Completion\n\n```bash\n# Generate completion for bash\ngh completion -s bash > /etc/bash_completion.d/gh\n\n# Generate completion for zsh\ngh completion -s zsh > /usr/local/share/zsh/site-functions/_gh\n\n# Generate completion for fish\ngh completion -s fish > ~/.config/fish/completions/gh.fish\n\n# Generate completion for powershell\ngh completion -s powershell | Out-File gh.ps1\n```\n\n## Common Workflows & Examples\n\n### Workflow 1: Complete PR Creation Flow\n\n```bash\n# 1. Update main branch\ngit checkout main\ngit pull\n\n# 2. Create feature branch\ngit checkout -b feature/new-feature\n\n# 3. Make changes and commit\ngit add .\ngit commit -m \"feat: Add new feature\"\n\n# 4. Push to remote\ngit push -u origin feature/new-feature\n\n# 5. Create PR with reviewers\ngh pr create \\\n  --title \"Add new feature\" \\\n  --body \"Detailed description\" \\\n  --reviewer username1,username2 \\\n  --label enhancement\n\n# 6. View PR status\ngh pr status\n```\n\n### Workflow 2: Issue Triage\n\n```bash\n# 1. List open issues\ngh issue list --state open --limit 50\n\n# 2. View specific issue\ngh issue view 123\n\n# 3. Add label and assign\ngh issue edit 123 \\\n  --add-label \"bug,priority-high\" \\\n  --add-assignee @me\n\n# 4. Comment on issue\ngh issue comment 123 --body \"Working on this\"\n\n# 5. Create branch and fix\ngit checkout -b fix/issue-123\n# ... make changes ...\n\n# 6. Create PR from issue\ngh pr create \\\n  --issue 123 \\\n  --title \"Fix issue #123\" \\\n  --body \"Fixes #123\"\n```\n\n### Workflow 3: Repository Setup\n\n```bash\n# 1. Create repository\ngh repo create my-new-repo --public --clone\n\n# 2. Navigate to repository\ncd my-new-repo\n\n# 3. Initialize with README\necho \"# My New Repo\" > README.md\ngit add README.md\ngit commit -m \"Initial commit\"\ngit push\n\n# 4. Add topics\ngh repo edit --add-topic \"golang,cli,tool\"\n\n# 5. Create labels\ngh label create \"bug\" --color \"d73a4a\"\ngh label create \"enhancement\" --color \"a2eeef\"\n\n# 6. Add protect branch (via API)\ngh api \\\n  --method PUT \\\n  -H \"Accept: application/vnd.github.v3+json\" \\\n  /repos/$(gh repo view --json owner,name --jq ''.owner.login + \"/\" + .name'')/branches/main/protection \\\n  -f required_status_checks=''{\"strict\":true,\"contexts\":[]}'' \\\n  -f enforce_admins=true \\\n  -f required_pull_request_reviews=''{\"dismiss_stale_reviews\":true}''\n```\n\n### Workflow 4: Release Management\n\n```bash\n# 1. Create release tag\ngit tag -a v1.0.0 -m \"Release v1.0.0\"\ngit push origin v1.0.0\n\n# 2. Create release\ngh release create v1.0.0 \\\n  --title \"Version 1.0.0\" \\\n  --notes-file RELEASE_NOTES.md\n\n# 3. Upload assets\ngh release upload v1.0.0 \\\n  ./dist/binary-linux-amd64 \\\n  ./dist/binary-darwin-amd64 \\\n  ./dist/binary-windows-amd64.exe\n\n# 4. View release\ngh release view v1.0.0 --web\n```\n\n### Workflow 5: Fork & Contribute\n\n```bash\n# 1. Fork repository\ngh repo fork owner/repo --clone\n\n# 2. Navigate to fork\ncd repo\n\n# 3. Create feature branch\ngit checkout -b feature/contribution\n\n# 4. Make changes\n# ... edit files ...\ngit add .\ngit commit -m \"feat: Add contribution\"\n\n# 5. Push to fork\ngit push -u origin feature/contribution\n\n# 6. Create PR to original repo\ngh pr create \\\n  --repo owner/repo \\\n  --base main \\\n  --title \"Add contribution\" \\\n  --body \"Description of changes\"\n```\n\n### Workflow 6: Bulk Operations\n\n```bash\n# Bulk close issues\ngh issue list --label \"wontfix\" --json number --jq ''.[].number'' | \\\n  xargs -I {} gh issue close {} --comment \"Closed as wontfix\"\n\n# Bulk add labels\ngh issue list --state open --json number --jq ''.[].number'' | \\\n  xargs -I {} gh issue edit {} --add-label \"triage\"\n\n# Bulk PR merge (careful!)\ngh pr list --state open --label \"ready-to-merge\" --json number --jq ''.[].number'' | \\\n  xargs -I {} gh pr merge {} --merge --yes\n```\n\n## Tips & Best Practices\n\n### DO ✅\n\n1. **Use aliases** for frequently used commands\n   ```bash\n   gh alias set prs ''pr list --state open''\n   gh alias set issues ''issue list --state open''\n   ```\n\n2. **Enable shell completion** for better productivity\n\n3. **Use JSON output** with `jq` for scripting:\n   ```bash\n   gh pr list --json number,title --jq ''.[] | select(.title | contains(\"fix\"))''\n   ```\n\n4. **Create templates** for common PR/issue descriptions\n\n5. **Use web flag** to open in browser for complex operations:\n   ```bash\n   gh pr view --web\n   ```\n\n6. **Check auth status** before running sensitive operations\n\n7. **Use `--help`** flag to explore subcommands:\n   ```bash\n   gh pr create --help\n   ```\n\n8. **Leverage search** for complex queries\n\n9. **Use pagination** for large result sets:\n   ```bash\n   gh issue list --limit 100\n   ```\n\n10. **Automate with scripts** using gh in CI/CD pipelines\n\n### DON''T ❌\n\n1. **NEVER hardcode tokens** - let gh handle authentication\n\n2. **DON''T ignore errors** - check exit codes and handle failures\n\n3. **NEVER commit secrets** - use gh secret for sensitive data\n\n4. **DON''T use --yes** in scripts without proper validation\n\n5. **NEVER delete resources** without confirmation (unless intentional)\n\n6. **DON''T forget to push** tags before creating releases\n\n7. **NEVER use --web** in automated scripts\n\n8. **DON''T ignore rate limits** when making API calls\n\n9. **NEVER assume gh is installed** - check and handle missing\n\n10. **DON''T use personal access tokens** when gh auth is available\n\n## Troubleshooting\n\n### Issue: \"gh not found\"\n\n**Solution:**\n\n```bash\n# Check if gh is installed\nwhich gh\n\n# If not, install it\n# See Installation section above\n```\n\n### Issue: \"gh: not logged in\"\n\n**Solution:**\n\n```bash\ngh auth login\ngh auth status  # Verify\n```\n\n### Issue: \"Permission denied\"\n\n**Solution:**\n\n```bash\n# Check permissions\ngh repo view\n\n# Ensure you have correct access\ngh auth refresh\n```\n\n### Issue: \"Repository not found\"\n\n**Solution:**\n\n```bash\n# Check current repo\ngit remote -v\n\n# Set correct remote\ngit remote set-url origin https://github.com/owner/repo.git\n```\n\n### Issue: \"gh is slow\"\n\n**Solution:**\n\n```bash\n# Check git protocol\ngh config get git_protocol\n\n# Switch to ssh (faster for authenticated requests)\ngh config set git_protocol ssh\n```\n\n### Issue: \"API rate limit exceeded\"\n\n**Solution:**\n\n```bash\n# Check rate limit\ngh api /rate_limit\n\n# Wait or authenticate to increase limit\ngh auth login\n```\n\n## Advanced Usage\n\n### JSON Processing with jq\n\n```bash\n# Get all open PR titles\ngh pr list --json title --jq ''.[].title''\n\n# Get PRs with specific label\ngh pr list --json number,title,labels --jq ''.[] | select(.labels[].name == \"bug\")''\n\n# Get issues assigned to me\ngh issue list --assignee @me --json number,title --jq ''.[] | \"#\\(.number): \\(.title)\"''\n\n# Count PRs by author\ngh pr list --json author --jq ''group_by(.author.login) | map({author: .[0].author.login, count: length})''\n```\n\n### Shell Scripting\n\n```bash\n#!/bin/bash\n# Script to create release with proper checks\n\n# Check authentication\nif ! gh auth status &> /dev/null; then\n  echo \"Not authenticated with gh\"\n  exit 1\nfi\n\n# Check if tag exists\nif git rev-parse \"$1\" &> /dev/null; then\n  echo \"Tag $1 already exists\"\n  exit 1\nfi\n\n# Create tag\ngit tag -a \"$1\" -m \"Release $1\"\ngit push origin \"$1\"\n\n# Create release\ngh release create \"$1\" --notes-file RELEASE_NOTES.md\n```\n\n### Git Integration\n\n```bash\n# Use gh in git hooks\n# .git/hooks/pre-push\n#!/bin/bash\nBRANCH=$(git branch --show-current)\nif [[ $BRANCH == feature/* ]]; then\n  echo \"Creating PR for $BRANCH\"\n  gh pr create --base main --head \"$BRANCH\" --draft\nfi\n```\n\n## Additional Resources\n\n- [Official GitHub CLI Documentation](https://cli.github.com/manual/)\n- [GitHub Blog - Introducing gh CLI](https://github.blog/2020-09-17-introducing-github-cli/)\n- [Awesome gh Extensions](https://github.com/topics/gh-extension)\n- [gh Extensions Repository](https://github.com/github/gh-extensions)\n\n## Keyboard Shortcuts & Tips\n\n```bash\n# Use gh with fzf for interactive selection\ngh pr list | fzf | gh pr view $(awk ''{print $1}'')\n\n# Quick view latest PR\ngh pr view --web $(gh pr list --json number --jq ''.[0].number'')\n\n# Quick issue creation with template\ngh issue create --title \"$1\" --body \"$(cat issue-template.md)\"\n```\n\n---\n\n**Remember**: The GitHub CLI is a powerful tool - use it wisely to automate your\nGitHub workflows and boost your productivity! 🚀\n"},"lastSynced":"2026-03-06T07:23:46.578Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing streamlined GitHub repository management and automation","zh":"非常适合需要简化GitHub仓库管理和自动化的开发代理","ja":"GitHubリポジトリの管理と自動化をストリームライン化する必要がある開発エージェントに最適","ko":"GitHub 저장소 관리 및 자동화를 간소화해야 하는 개발 에이전트에게 완벽함","es":"Perfecto para agentes de desarrollo que necesitan una gestión de repositorios de GitHub simplificada y automatizada","fr":"Parfait pour les agents de développement ayant besoin d''une gestion de référentiels GitHub simplifiée et automatisée","de":"Perfekt für EntwicklungssAgenten, die eine vereinfachte und automatisierte GitHub-Repository-Verwaltung benötigen","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de gerenciamento de repositórios GitHub e automação simplificados","ru":"Идеально подходит для агентов разработки, которым необходим упрощенный менеджмент репозиториев GitHub и автоматизация","ar":"مثالي للوكلاء التطوير الذين يحتاجون إلى إدارة مستودعات GitHub وتوفر التutomatisation"},"recommendation":{"en":"Empowers agents to manage GitHub operations efficiently using the GitHub CLI (gh), covering repository management, issues, pull requests, and authentication, all from the command line, leveraging protocols like SSH and HTTPS","zh":"赋予代理使用GitHub CLI（gh）高效管理GitHub操作的能力，涵盖仓库管理、问题、拉取请求和身份验证等，所有操作均从命令行执行，利用SSH和HTTPS等协议","ja":"エージェントがGitHub CLI（gh）を使用してGitHub操作を効率的に管理できるようにし、リポジトリ管理、問題、プルリクエスト、認証などをすべてコマンドラインから実行し、SSHやHTTPSなどのプロトコルを利用する","ko":"에이전트가 GitHub CLI(gh)를 사용하여 GitHub 작업을 효율적으로 관리할 수 있도록 하며, 저장소 관리, 문제, 풀 리퀘스트 및 인증 등을 모두 명령줄에서 수행하며, SSH 및 HTTPS와 같은 프로토콜을 활용함","es":"Permite a los agentes gestionar operaciones de GitHub de forma eficiente utilizando la GitHub CLI (gh), que cubre la gestión de repositorios, problemas, solicitudes de extracción y autenticación, todo desde la línea de comandos, utilizando protocolos como SSH y HTTPS","fr":"Permet aux agents de gérer les opérations GitHub de manière efficace en utilisant la GitHub CLI (gh), qui couvre la gestion des référentiels, des problèmes, des demandes d''extraction et de l''authentification, le tout depuis la ligne de commande, en utilisant des protocoles comme SSH et HTTPS","de":"Ermöglicht es den Agenten, GitHub-Operationen effizient mithilfe der GitHub-CLI (gh) zu verwalten, die Repository-Verwaltung, Probleme, Pull-Requests und Authentifizierung abdeckt, alles von der Kommandozeile aus, unter Verwendung von Protokollen wie SSH und HTTPS","pt":"Habilita os agentes a gerenciar operações do GitHub de forma eficiente usando o GitHub CLI (gh), cobrindo gerenciamento de repositórios, problemas, solicitações de pull e autenticação, tudo a partir da linha de comando, aproveitando protocolos como SSH e HTTPS","ru":"Позволяет агентам управлять операциями GitHub эффективно, используя GitHub CLI (gh), покрывая управление репозиториями, проблемы, запросы на слияние и аутентификацию, все из командной строки, используя протоколы как SSH и HTTPS","a