INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('masx200/http-proxy-go-server/github-cli', 'github-cli', 'masx200', 'http-proxy-go-server', 'community', 'github-cli masx200 http-proxy-go-server community The github-cli skill enables developers to work with GitHub from the command line, covering repository management, issues, and authentication. It benefits developers who need to manage GitHub operations efficiently. GitHub CLI（gh）是一种命令行工具，用于管理 GitHub 仓库和相关操作 GitHub CLI（gh）は、GitHub リポジトリと関連操作を管理するためのコマンドラインツール GitHub CLI(gh)는 GitHub 리포지토리와 관련 작업을 관리하는 명령어 인터페이스 O GitHub CLI é uma ferramenta poderosa para desenvolvedores, permitindo gerenciar repositórios, problemas e solicitações de pull de forma eficiente. GitHub CLI — это мощный инструмент для разработчиков, позволяющий эффективно управлять репозиториями, проблемами и запросами на включение. واجهة سطر الأوامر GitHub هي أداة قوية لمطوري البرمجيات، تمكنهم من إدارة المستودعات والمشكلات وطلبات السحب بفعالية how to use github-cli github-cli setup guide github-cli vs git github-cli install github-cli tutorial github-cli alternative GitHub CLI gh命令行工具 GitHub 仓库管理 问题和拉取请求 发布和认证 GitHub Actions 代码空间 AIエージェント Manages GitHub repositories using the `gh` command Creates and manages pull requests, issues, and releases Handles authentication with GitHub using `gh auth` Supports working with GitHub Actions and codespaces Enables cloning, forking, and updating repositories with ease github-cli is a command-line interface for GitHub that allows developers to manage repositories, issues, and pull requests, among other operations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/continuous-agent-loop', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'continuous-agent-loop', 61988, 7678, 65, '2026-03-06T03:39:20Z', '2026-03-06T03:53:18.958Z', '9a014a9cf31cbc43dc2e48e4323438de562fa28de017a9c3b9bad8863d16eb6d', '{"id":"affaan-m/everything-claude-code/continuous-agent-loop","name":"continuous-agent-loop","description":{"en":"The continuous-agent-loop skill provides canonical patterns for building autonomous AI agent loops with built-in quality gates, evaluations, and recovery controls. It is designed for developers using MCP servers and Claude to create robust, self-correcting AI agent workflows.","zh":"持续代理循环是一种实现AI代理高效开发的模式，包括质量门、评估和恢复控制等功能","ja":"連続エージェントループは、AIエージェントの効率的な開発を実現するためのパターンです","ko":"연속 에이전트 루프는 효율적인 AI 에이전트 개발을 위한 패턴으로, 품질 게이트, 평가, 복구 제어 등을 포함","es":"El patrón de continuous-agent-loop permite la creación de bucles autónomos continuos con control de calidad y recuperación para agentes de IA","fr":"Le modèle de continuous-agent-loop permet la création de boucles autonomes continues avec contrôle de qualité et récupération pour les agents d''IA","de":"Das Muster von continuous-agent-loop ermöglicht die Erstellung kontinuierlicher autonome Schleifen mit Qualitätskontrolle und Wiederherstellung für KI-Agents","pt":"O Continuous Agent Loop é um padrão para loops autônomos contínuos com portas de qualidade, avaliações e controles de recuperação. Aprenda a configurá-lo para melhorar a produtividade dos seus projetos de desenvolvimento de AI Agents","ru":"Continuous Agent Loop - это шаблон для непрерывных автономных циклов с контрольными воротами, оценками и механизмами восстановления. Узнайте, как настроить его для повышения производительности ваших проектов по разработке ИИ Агентов","ar":"Continuous Agent Loop هو نمط لتحقيق التكرارات المستقلة المستمرة مع بوابات جودة وتقييمات وضوابط استعادة. تعرف على كيفية إعدادها لتحسين إنتاجية مشاريعك في مجال تطوير الإي جي أجهزة"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"continuous-agent-loop","description":"Patterns for continuous autonomous agent loops with quality gates, evals, and recovery controls.","bodyPreview":"# Continuous Agent Loop\n\nThis is the v1.8+ canonical loop skill name. It supersedes `autonomous-loops` while keeping compatibility for one release.\n\n## Loop Selection Flow\n\n```text\nStart\n  |\n  +-- Need strict CI/PR control? -- yes --> continuous-pr\n  |                                    \n  +-- Need RFC decomposition? -- yes --> rfc-dag\n  |\n  +-- Need exploratory parallel generation? -- yes --> infinite\n  |\n  +-- default --> sequential\n```\n\n## Combined Pattern\n\nRecommended production stack:\n1. RF","body":"# Continuous Agent Loop\n\nThis is the v1.8+ canonical loop skill name. It supersedes `autonomous-loops` while keeping compatibility for one release.\n\n## Loop Selection Flow\n\n```text\nStart\n  |\n  +-- Need strict CI/PR control? -- yes --> continuous-pr\n  |                                    \n  +-- Need RFC decomposition? -- yes --> rfc-dag\n  |\n  +-- Need exploratory parallel generation? -- yes --> infinite\n  |\n  +-- default --> sequential\n```\n\n## Combined Pattern\n\nRecommended production stack:\n1. RFC decomposition (`ralphinho-rfc-pipeline`)\n2. quality gates (`plankton-code-quality` + `/quality-gate`)\n3. eval loop (`eval-harness`)\n4. session persistence (`nanoclaw-repl`)\n\n## Failure Modes\n\n- loop churn without measurable progress\n- repeated retries with same root cause\n- merge queue stalls\n- cost drift from unbounded escalation\n\n## Recovery\n\n- freeze loop\n- run `/harness-audit`\n- reduce scope to failing unit\n- replay with explicit acceptance criteria\n"},"category":"official","lastSynced":"2026-03-06T03:53:18.958Z","seo":{"title":{"en":"continuous-agent-loop: Setup Guide for Autonomous AI Agen...","zh":"持续代理循环设置指南","ja":"連続エージェントループのベストプラクティス","ko":"연속 에이전트 루프 구축 가이드","es":"Guía de configuración de continuous-agent-loop para agent...","fr":"Mise en place de continuous-agent-loop pour les agents d''IA","de":"Einrichtungsleitfaden für continuous-agent-loop in KI-Age...","pt":"Guia de Configuração do Continuous Agent Loop para Desenv...","ru":"Настройка Continuous Agent Loop: Лучшие Практики для Разр...","ar":"دليل إعداد Continuous Agent Loop لاحترافيين التطوير"},"description":{"en":"Master the continuous-agent-loop skill for MCP & Claude. Learn to implement production-ready autonomous loops with sequential, continuous-pr, rfc-dag, and in...","zh":"了解持续代理循环的工作原理，包括质量门、评估和恢复控制，实现高效的AI代理开发","ja":"連続エージェントループの詳細をご紹介。品質ゲート、評価、リカバリーコントロールを含む","ko":"연속 에이전트 루프를 통해 효율적인 AI 에이전트 개발을 실현하세요. 품질 게이트, 평가, 복구 제어 등","es":"Aprende a implementar patrones de bucles autónomos continuos con control de calidad y recuperación para agentes de IA","fr":"Découvrez comment mettre en œuvre des modèles de boucles autonomes continues avec contrôle de qualité et récupération pour les agents d''IA","de":"Erfahren Sie, wie Sie Muster für kontinuierliche autonome Schleifen mit Qualitätskontrolle und Wiederherstellung für KI-Agents implementieren","pt":"Aprenda a configurar o Continuous Agent Loop para melhorar a produtividade e a qualidade dos seus projetos de desenvolvimento de AI Agents","ru":"Узнайте, как настроить Continuous Agent Loop для повышения производительности и качества ваших проектов по разработке ИИ Агентов","ar":"تعرف على كيفية إعداد Continuous Agent Loop لتحسين الإنتاجية وجودة مشاريعك في مجال تطوير الإي جي أجهزة"},"definition":{"en":"continuous-agent-loop is a canonical skill for v1.8+ that provides patterns for implementing continuous autonomous agent loops. It features a loop selection flow for different use cases and includes quality gates, evals, and recovery controls for building reliable AI agent systems.","zh":"持续代理循环是一种实现AI代理循环的模式，包括循环选择流、质量门、评估和恢复控制等","ja":"連続エージェントループは、ループ選択フロー、品質ゲート、評価、リカバリーコントロールを含むAIエージェントのループ実現パターン","ko":"연속 에이전트 루프는 루프 선택 흐름, 품질 게이트, 평가, 복구 제어 등을 포함하는 AI 에이전트 루프 구현 패턴","es":"Continuous-agent-loop es un patrón de diseño para agentes de IA que permite la creación de bucles autónomos continuos","fr":"Continuous-agent-loop est un modèle de conception pour les agents d''IA qui permet la création de boucles autonomes continues","de":"Continuous-agent-loop ist ein Entwurfsmuster für KI-Agents, das die Erstellung kontinuierlicher autonome Schleifen ermöglicht","pt":"O Continuous Agent Loop é um padrão de desenvolvimento de software que permite a criação de loops autônomos contínuos com controle de qualidade e recuperação","ru":"Continuous Agent Loop - это шаблон разработки программного обеспечения, позволяющий создавать непрерывные автономные циклы с контролем качества и восстановлением","ar":"Continuous Agent Loop هو نمط لتطوير البرمجيات الذي يسمح بإنشاء التكرارات المستقلة المستمرة مع ضبط الجودة والاستعادة"},"features":{"en":["Provides a loop selection flow for sequential, continuous-pr, rfc-dag, and infinite patterns","Supersedes the `autonomous-loops` skill while maintaining backward compatibility","Includes built-in quality gates and evaluation controls for agent output","Implements recovery controls for handling agent loop failures","Supports RFC decomposition for complex task breakdown via the rfc-dag pattern"],"zh":["循环选择流","质量门","评估","恢复控制","连续PR控制","RFC分解"],"ja":["ループ選択フロー","品質ゲート","評価","リカバリーコントロール","連続PRコントロール","RFC分解"],"ko":["루프 선택 흐름","품질 게이트","평가","복구 제어","연속 PR 제어","RFC 분해"],"es":["Patrones de bucles autónomos continuos","Control de calidad y recuperación","Compatibilidad con continuous-pr y rfc-dag","Soporte para generación paralela exploratoria","Integración con tecnologías como Claude y MCP"],"fr":["Modèles de boucles autonomes continues","Contrôle de qualité et récupération","Compatibilité avec continuous-pr et rfc-dag","Prise en charge de la génération parallèle exploratoire","Intégration avec des technologies comme Claude et MCP"],"de":["Muster für kontinuierliche autonome Schleifen","Qualitätskontrolle und Wiederherstellung","Kompatibilität mit continuous-pr und rfc-dag","Unterstützung für parallele explorative Generierung","Integration mit Technologien wie Claude und MCP"],"pt":["Implementação de portas de qualidade para garantir a consistência dos resultados","Avaliações e controles de recuperação para minimizar erros e melhorar a produtividade","Compatibilidade com o padrão anterior de loops autônomos","Suporte à decomposição de solicitações de recurso (RFC) em grafos direcionados (DAG)","Opção de geração paralela infinita para melhorar a eficiência"],"ru":["Реализация контрольных ворот для обеспечения согласованности результатов","Оценки и механизмы восстановления для минимизации ошибок и повышения производительности","Совместимость с предыдущим шаблоном автономных циклов","Поддержка декомпозиции запросов на ресурсы (RFC) в направленных графах (DAG)","Возможность бесконечной параллельной генерации для повышения эффективности"],"ar":["تنفيذ بوابات جودة لضمان الاتساق في النتائج","التقييمات وضوابط الاستعادة لتقليل الأخطاء وتحسين الإنتاجية","التوافق مع نمط التكرارات المستقلة السابق","دعم تحليل طلبات الموارد (RFC) إلى رسوم بيانية موجهة (DAG)","خيار التوليد الموازي اللانهائي لتحسين الكفاءة"]},"keywords":{"en":["how to use continuous-agent-loop","what is continuous-agent-loop","continuous-agent-loop vs autonomous-loops","continuous-agent-loop install","continuous-agent-loop setup guide","mcp continuous agent loops","claude code autonomous agent patterns","rfc-dag pattern implementation","ai agent quality gates"],"zh":["AI代理","持续代理循环","质量门","评估","恢复控制","连续PR控制","RFC分解","AI工具","AI开发"],"ja":["AIエージェント","連続エージェントループ","品質ゲート","評価","リカバリーコントロール","連続PRコントロール","RFC分解","AIツール","AI開発"],"ko":["AI 에이전트","연속 에이전트 루프","품질 게이트","평가","복구 제어","연속 PR 제어","RFC 분해","AI 툴","AI 개발"],"es":["agentes de IA","bucles autónomos continuos","control de calidad","recuperación","continuous-pr","rfc-dag","Claude","MCP","desarrollo de agentes de IA"],"fr":["agents d''IA","boucles autonomes continues","contrôle de qualité","récupération","continuous-pr","rfc-dag","Claude","MCP","développement d''agents d''IA"],"de":["KI-Agents","kontinuierliche autonome Schleifen","Qualitätskontrolle","Wiederherstellung","continuous-pr","rfc-dag","Claude","MCP","Entwicklung von KI-Agents"],"pt":["Continuous Agent Loop","desenvolvimento de AI Agents","padrões de desenvolvimento de software","controle de qualidade","recuperação de erros","produtividade em desenvolvimento de software","RFC","DAG","geração paralela infinita"],"ru":["Continuous Agent Loop","разработка ИИ Агентов","шаблоны разработки программного обеспечения","контроль качества","восстановление ошибок","производительность разработки программного обеспечения","RFC","DAG","бесконечная параллельная генерация"],"ar":["Continuous Agent Loop","تطوير الإي جي أجهزة","نماذج تطوير البرمجيات","ضبط الجودة","استعادة الأخطاء","إنتاجية تطوير البرمجيات","RFC","DAG","التوليد الموازي اللانهائي"]}},"agentAnalysis":{"suitability":{"en":"Ideal for Autonomous AI Agents requiring robust, self-correcting execution loops with quality control mechanisms.","zh":"非常适合需要具有质量控制机制的强大自我校正执行循环的自主AI Agent。","ja":"品質管理メカニズムを備えた堅牢な自己修正実行ループを必要とする自律AIエージェントに理想的です。","ko":"품질 관리 메커니즘이 포함된 강력한 자체 수정 실행 루프가 필요한 자율 AI 에이전트에 이상적입니다.","es":"Ideal para Autonomous AI Agents que requieren bucles de ejecución robustos y auto-correctoras con mecanismos de control de calidad.","fr":"Idéal pour les Autonomous AI Agents nécessitant des boucles d''exécution robustes et auto-correctrices avec des mécanismes de contrôle de qualité.","de":"Ideal für Autonomous AI Agents, die robuste, selbstkorrigierende Ausführungsschleifen mit Qualitätskontrollmechanismen erfordern.","pt":"Ideal para Agentes de IA Autónomos que requerem loops de execução robustos e autocorretivos com mecanismos de controlo de qualidade.","ru":"Идеально подходит для автономных ИИ-агентов, требующих надежные самокорректирующиеся циклы выполнения с механизмами контроля качества.","ar":"مثالي لوكلاء الذكاء الاصطناعي المستقلين الذين يتطلبون حلقات تنفيذ قوية وذاتية التصحيح مع آليات ضمان الجودة."},"recommendation":{"en":"Enables agents to implement production-grade autonomous loops with built-in quality gates, evaluation protocols, and recovery controls. Supports multiple loop patterns including RFC decomposition, parallel generation, and CI/PR-controlled workflows for reliable continuous operation.","zh":"使Agent能够实施具有内置质量门、评估协议和恢复控制的生产级自主循环。支持多种循环模式，包括RFC分解、并行生成以及CI/PR控制的工作流，以实现可靠的持续操作。","ja":"組み込みの品質ゲート、評価プロトコル、回復制御を備えたプロダクショングレードの自律ループの実装を可能にします。信頼性の高い継続的な運用のために、RFC分解、並列生成、CI/PR制御ワークフローを含む複数のループパターンをサポートします。","ko":"내장된 품질 게이트, 평가 프로토콜 및 복구 제어를 갖춘 프로덕션 등급의 자율 루프 구현을 가능하게 합니다. 신뢰할 수 있는 지속적인 운영을 위해 RFC 분해, 병렬 생성 및 CI/PR 제어 워크플로우를 포함한 여러 루프 패턴을 지원합니다.","es":"Permite a los agentes implementar bucles autónomos de grado de producción con compuertas de calidad integradas, protocolos de evaluación y controles de recuperación. Es compatible con múltiples patrones de bucle, incluida la descomposición RFC, la generación paralela y los flujos de trabajo controlados por CI/PR para una operación continua confiable.","fr":"Permet aux agents de mettre en œuvre des boucles autonomes de qualité production avec des portes de qualité intégrées, des protocoles d''évaluation et des contrôles de récupération. Prend en charge plusieurs modèles de boucles, y compris la décomposition RFC, la génération parallèle et les workflows contrôlés par CI/PR pour une opération continue fiable.","de":"Ermöglicht es Agents, produktionsreife autonome Schleifen mit integrierten Quality Gates, Evaluierungsprotokollen und Recovery-Controls zu implementieren. Unterstützt mehrere Schleifenmuster, einschließlich RFC-Zerlegung, parallele Generierung und CI/PR-gesteuerte Workflows für einen zuverlässigen Dauerbetrieb.","pt":"Permite que os agentes implementem loops autónomos de nível de produção com portões de qualidade incorporados, protocolos de avaliação e controlos de recuperação. Suporta múltiplos padrões de loop, incluindo decomposição RFC, geração paralela e fluxos de trabalho controlados por CI/PR para operação contínua fiável.","ru":"Позволяет агентам реализовывать автономные циклы производственного уровня со встроенными контрольными точками качества, протоколами оценки и механизмами восстановления. Поддерживает несколько моделей циклов, включая декомпозицию RFC, параллельное выполнение и рабочие процессы, управляемые CI/PR, для надежной непрерывной работы.","ar":"يمكن الوكلاء من تنفيذ حلقات عمل مستقلة من مستوى الإنتاج مع بوابات جودة مدمجة، وبروتوكولات تقييم، وضوابط استعادة. يدعم أنماط حلقات متعددة بما في ذلك تحليل RFC، والتوليد المتوازي، وسير العمل الخاضعة لتحكم CI/PR للتشغيل المستمر الموثوق."},"useCases":{"en":["Implementing strict CI/PR control workflows","Decomposing RFCs into executable DAGs","Running exploratory parallel generation tasks","Maintaining sequential execution with quality gates"],"zh":["实施严格的CI/PR控制工作流","将RFC分解为可执行的DAG","运行探索性并行生成任务","通过质量门保持顺序执行"],"ja":["厳格なCI/PR制御ワークフローの実装","RFCを実行可能なDAGに分解","探索的並列生成タスクの実行","品質ゲートを用いた順次実行の維持"],"ko":["엄격한 CI/PR 제어 워크플로우 구현","RFC를 실행 가능한 DAG로 분해","탐색적 병렬 생성 작업 실행","품질 게이트를 통한 순차적 실행 유지"],"es":["Implementación de flujos de trabajo de control estricto de CI/PR","Descomposición de RFCs en DAGs ejecutables","Ejecución de tareas de generación paralela exploratoria","Mantenimiento de ejecución secuencial con compuertas de calidad"],"fr":["Mise en œuvre de workflows de contrôle CI/PR stricts","Décomposition des RFCs en DAGs exécutables","Exécution de tâches de génération parallèle exploratoire","Maintenance d''une exécution séquentielle avec des portes de qualité"],"de":["Implementierung strenger CI/PR-gesteuerter Workflows","Zerlegung von RFCs in ausführbare DAGs","Ausführung explorativer Parallel-Generierungsaufgaben","Aufrechterhaltung der sequentiellen Ausführung mit Quality Gates"],"pt":["Implementação de fluxos de trabalho de controlo de CI/PR rigorosos","Decomposição de RFCs em DAGs executáveis","Execução de tarefas de geração paralela exploratória","Manutenção de execução sequencial com portões de qualidade"],"ru":["Внедрение строгих рабочих процессов управления CI/PR","Разложение RFC в исполняемые DAG","Выполнение исследовательских задач параллельного выполнения","Поддержание последовательного выполнения с контрольными точками качества"],"ar":["تنفيذ سير عمل تحكم صارمة بـ CI/PR","تحليل RFCs إلى DAGs قابلة للتنفيذ","تشغيل مهام توليد متوازية استكشافية","الحفاظ على التنفيذ التسلسلي مع بوابات الجودة"]},"limitations":{"en":["Requires v1.8+ agent framework compatibility","Needs evaluation infrastructure for quality gates","Demands recovery control implementation"],"zh":["需要v1.8+版本的Agent框架兼容性","需要用于质量门的评估基础设施","需要实施恢复控制"],"ja":["v1.8以降のAgentフレームワーク互換性が必要","品質ゲートには評価インフラストラクチャが必要","回復制御の実装が要求される"],"ko":["v1.8+ 이상의 에이전트 프레임워크 호환성 필요","품질 게이트를 위한 평가 인프라 필요","복구 제어 구현 필요"],"es":["Requiere compatibilidad con el framework de agente v1.8+","Necesita infraestructura de evaluación para las compuertas de calidad","Requiere la implementación de controles de recuperación"],"fr":["Nécessite une compatibilité avec le framework d''agent v1.8+","Requiert une infrastructure d''évaluation pour les portes de qualité","Exige la mise en œuvre de contrôles de récupération"],"de":["Erfordert Kompatibilität mit dem Agent Framework v1.8+","Benötigt eine Evaluierungsinfrastruktur für Quality Gates","Erfordert die Implementierung von Recovery-Controls"],"pt":["Requer compatibilidade com o framework de agente v1.8+","Necessita de infraestrutura de avaliação para portões de qualidade","Exige implementação de controlo de recuperação"],"ru":["Требуется совместимость с фреймворком агента версии 1.8+","Требуется инфраструктура оценки для контрольных точек качества","Требует реализации механизмов восстановления"],"ar":["يتطلب توافقًا مع إطار عمل الوكلاء الإصدار 1.8 أو أعلى","يحتاج إلى بنية تحتية للتقييم لبوابات الجودة","يتطلب تنفيذ ضوابط الاستعادة"]},"version":4},"contentHash":"9a014a9cf31cbc43dc2e48e4323438de562fa28de017a9c3b9bad8863d16eb6d","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":65}');
