INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/continuous-agent-loop', 'continuous-agent-loop', 'affaan-m', 'everything-claude-code', 'official', 'continuous-agent-loop affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The continuous-agent-loop skill provides canonical patterns for building autonomous AI agent loops with built-in quality gates, evaluations, and recovery controls. It is designed for developers using MCP servers and Claude to create robust, self-correcting AI agent workflows. 持续代理循环是一种实现AI代理高效开发的模式，包括质量门、评估和恢复控制等功能 連続エージェントループは、AIエージェントの効率的な開発を実現するためのパターンです 연속 에이전트 루프는 효율적인 AI 에이전트 개발을 위한 패턴으로, 품질 게이트, 평가, 복구 제어 등을 포함 El patrón de continuous-agent-loop permite la creación de bucles autónomos continuos con control de calidad y recuperación para agentes de IA Le modèle de continuous-agent-loop permet la création de boucles autonomes continues avec contrôle de qualité et récupération pour les agents d''IA Das Muster von continuous-agent-loop ermöglicht die Erstellung kontinuierlicher autonome Schleifen mit Qualitätskontrolle und Wiederherstellung für KI-Agents O Continuous Agent Loop é um padrão para loops autônomos contínuos com portas de qualidade, avaliações e controles de recuperação. Aprenda a configurá-lo para melhorar a produtividade dos seus projetos de desenvolvimento de AI Agents Continuous Agent Loop - это шаблон для непрерывных автономных циклов с контрольными воротами, оценками и механизмами восстановления. Узнайте, как настроить его для повышения производительности ваших проектов по разработке ИИ Агентов Continuous Agent Loop هو نمط لتحقيق التكرارات المستقلة المستمرة مع بوابات جودة وتقييمات وضوابط استعادة. تعرف على كيفية إعدادها لتحسين إنتاجية مشاريعك في مجال تطوير الإي جي أجهزة how to use continuous-agent-loop what is continuous-agent-loop continuous-agent-loop vs autonomous-loops continuous-agent-loop install continuous-agent-loop setup guide mcp continuous agent loops claude code autonomous agent patterns rfc-dag pattern implementation ai agent quality gates AI代理 持续代理循环 质量门 评估 恢复控制 连续PR控制 RFC分解 AI工具 AI开发 Provides a loop selection flow for sequential, continuous-pr, rfc-dag, and infinite patterns Supersedes the `autonomous-loops` skill while maintaining backward compatibility Includes built-in quality gates and evaluation controls for agent output Implements recovery controls for handling agent loop failures Supports RFC decomposition for complex task breakdown via the rfc-dag pattern continuous-agent-loop is a canonical skill for v1.8+ that provides patterns for implementing continuous autonomous agent loops. It features a loop selection flow for different use cases and includes quality gates, evals, and recovery controls for building reliable AI agent systems.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('langwatch/langwatch/e2e', 'community', 'langwatch', 'langwatch', 'langwatch/langwatch', 'e2e', 2833, 254, 64, '2026-02-24T16:59:56Z', '2026-03-06T06:25:14.920Z', '63e2b31f0fbd4aaed2474d2be69213131ebe35498abcea6fbf953d76de82a05f', '{"id":"langwatch/langwatch/e2e","name":"e2e","description":{"en":"The e2e platform enables coordinated E2E test creation and verification for AI agents, utilizing technologies like Docker and OpenAI. It benefits developers and testers working with LLM evaluations.","zh":"E2E测试生成工作流是一种协调E2E测试创建和验证的平台","ja":"E2Eテスト生成ワークフローは、E2Eテストの作成と検証を調整するためのプラットフォーム","ko":"E2E 테스트 생성 워크플로우는 E2E 테스트 생성과 검증을 조정하는 플랫폼","es":"e2e es una plataforma para evaluar y probar agentes de inteligencia artificial, que permite la creación y verificación de pruebas de extremo a extremo","fr":"e2e est une plateforme pour évaluer et tester les agents d''intelligence artificielle, qui permet la création et la vérification de tests de bout en bout","de":"e2e ist eine Plattform für die Bewertung und das Testen von KI-Agents, die die Erstellung und Überprüfung von End-to-End-Tests ermöglicht","pt":"O E2E é uma plataforma para avaliar e testar agentes de IA, permitindo a coordenação de testes e a verificação de resultados.","ru":"E2E - это платформа для оценки и тестирования ИИ Агентов, позволяющая координировать тесты и проверять результаты.","ar":"E2E هي منصة لتقييم واختبار وكلاء الذكاء الاصطناعي، تمكن من تنسيق الاختبارات ومراجعة النتائج."},"seo":{"title":{"en":"e2e: E2E Test Generation Workflow for AI Agents | AI Agen...","zh":"E2E测试生成工作流Setup Guide","ja":"E2Eテスト生成ワークフローBest Practices","ko":"E2E 테스트 생성 워크플로우 Tutorial","es":"Guía de configuración de e2e para pruebas de agentes de i...","fr":"Guide de configuration e2e pour les tests d''agents d''inte...","de":"E2E-Konfigurationsleitfaden für KI-Agenten-Tests","pt":"