INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('navi-language/navi/navi', 'navi', 'navi-language', 'navi', 'community', 'navi navi-language navi community navi is a high-performance programming language designed for complex computing tasks, offering script-like execution with compiled performance. It benefits developers seeking reliable and efficient code execution. Navi 是一种高性能、静态类型的编译语言，设计用于复杂的计算任务。它提供了脚本式执行和编译后的性能 Navi は、高性能で静的に型付けされたコンパイル言語です。複雑なコンピューティングタスクに最適化された設計です Navi는 고성능 정적 타입 컴파일 언어로 복잡한 컴퓨팅 작업을 위해 설계되었습니다. 스크립트와 유사한 실행 및 컴파일된 성능을 제공합니다 Navi es un lenguaje de programación de alto rendimiento con tipado estático y compilación. Ofrece ejecución de scripts con rendimiento comparable a Go, Rust y C. Navi est un langage de programmation haute performance avec typage statique et compilation. Il offre une exécution de scripts avec des performances comparables à Go, Rust et C. Navi ist eine Hochleistungs-Programmiersprache mit statischer Typisierung und Kompilierung. Sie bietet Skriptausführung mit Leistungen vergleichbar mit Go, Rust und C. Navi é uma linguagem de programação de alto desempenho, estáticamente tipada e compilada, projetada para tarefas de computação complexas. Navi - это высокопроизводительный язык программирования, статически типизированный и компилируемый, предназначенный для сложных вычислительных задач. نافي هي لغة برمجة عالية الأداء، محوسبة بشكل ثابت ومجمّعة، مصممة لمهام الحوسبة المعقدة. how to use navi what is navi navi alternative navi vs rust navi install navi setup guide navi programming language statically-typed language compiled language Navi 编程语言 静态类型编程语言 高性能编程语言 现代可选类型 综合错误处理 编译后的性能 AI 编程工具 AIエージェント Statically typed with type inference for reliable code execution No NULL pointer exceptions for enhanced code stability Modern optional types similar to Rust''s Option for flexible coding Comprehensive error handling with throws, try, try?, and try! for robust error management Built-in support for script-like execution with compiled performance comparable to Go, Rust, and C navi is a high-performance, statically-typed compiled language designed for complex computing tasks, offering features like type inference and modern optional types.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('oimiragieo/agent-studio/agent-evaluation', 'community', 'oimiragieo', 'agent-studio', 'oimiragieo/agent-studio', 'agent-evaluation', 14, 0, 64, '2026-03-02T01:27:17Z', '2026-03-06T06:44:05.538Z', 'cd4fd70eeb53b06c6d7fb50721868abe1b408d7bec1745b609a0b3a7402498bb', '{"id":"oimiragieo/agent-studio/agent-evaluation","name":"agent-evaluation","description":{"en":"The agent-evaluation skill is a systematic quality verification framework that scores AI-generated content using a 1-5 rubric, benefiting AI agent developers and users alike.","zh":"AI代理评估技能是一种LLM-as-judge评估框架，使用1-5评分标准评估AI生成内容的5个维度","ja":"AIエージェント評価スキルは、LLM-as-judge評価フレームワークを使用し、AI生成コンテンツの5つの要素を1-5評価基準で評価します","ko":"AI 에이전트 평가 스킬은 LLM-as-judge 평가 프레임워크를 사용하여 AI 생성 콘텐츠의 5개 요소를 1-5 평가 기준으로 평가합니다","es":"El agent-evaluation es un marco de evaluación que califica el contenido generado por IA en 5 dimensiones. Permite una verificación sistemática de la calidad","fr":"L''agent-evaluation est un cadre d''évaluation qui note le contenu généré par l''IA sur 5 dimensions. Il permet une vérification systématique de la qualité","de":"Das agent-evaluation ist ein Bewertungsrahmen, der den von KI generierten Inhalt in 5 Dimensionen bewertet. Es ermöglicht eine systematische Qualitätsverifizierung","pt":"O Agent-Evaluation é um framework de avaliação que utiliza uma rubrica de 1-5 para avaliar a qualidade do conteúdo gerado por IA, com base em 5 dimensões","ru":"Agent-Evaluation - это framework для оценки качества контента, сгенерированного ИИ, на основе 5 измерений и шкалы 1-5","ar":"Agent-Evaluation هو إطار تقييم يستخدم تصنيف 1-5 لتقويم جودة المحتوى التوليدي بالاعتماد على 5 أبعاد"},"seo":{"title":{"en":"agent-evaluation: LLM-as-Judge Evaluation Framework for A...","zh":"AI代理评估技能设置指南","ja":"AIエージェント評価スキルのベストプラクティス","ko":"AI 에이전트 평가 스킬 구축 가이드","es":"Guía de configuración de agent-evaluation para AI Agentes","fr":"Mise en place de l''agent-evaluation pour les outils d''IA","de":"Einrichtungsleitfaden für agent-evaluation in KI-Agenten","pt":"Guia de Configuração do Agent-Evaluation para Verificação...","ru":"ИИ Агенты: Руководство по Настройке Agent-Evaluation для ...","ar":"دليل إعداد وتشغيل Agent-Evaluation لتقويم جودة المحتوى ال..."},"description":{"en":"Discover how agent-evaluation scores AI-generated content on 5 dimensions. Learn to implement this LLM-as-judge framework and improve your AI agent''s output ...","zh":"了解AI代理评估技能的技术细节和应用场景，实现系统化的质量验证","ja":"AIエージェント評価スキルの技術的な詳細と応用シーンを学び、体系的な品質検証を実現する","ko":"AI 에이전트 평가 스킬의 기술적 세부 사항과 적용 사례를 알아보고 체계적인 품질 검증을 구현하세요","es":"Aprende a utilizar agent-evaluation para evaluar la calidad de contenido generado por IA. Descubre cómo funciona y mejora la verificación de calidad","fr":"Découvrez comment utiliser l''agent-evaluation pour évaluer la qualité du contenu généré par l''IA. Améliorez la vérification de la qualité","de":"Erfahren Sie, wie Sie agent-evaluation verwenden, um die Qualität von KI-generiertem Inhalt zu bewerten. Verbessern Sie die Qualitätsverifizierung","pt":"Aprenda a configurar o Agent-Evaluation para avaliar a qualidade do conteúdo gerado por IA, com base em 5 dimensões e uma rubrica de 1-5","ru":"Узнайте, как настроить Agent-Evaluation для оценки качества контента, сгенерированного ИИ, на основе 5 измерений и шкалы 1-5","ar":"تعرف على كيفية إعداد Agent-Evaluation لتقويم جودة المحتوى التوليدي بالاستناد إلى 5 أبعاد وتصنيف 1-5"},"definition":{"en":"agent-evaluation is a LLM-as-judge evaluation framework that assesses AI-generated content quality using a weighted composite score and structured verdict with evidence citations.","zh":"AI代理评估技能是一种用于评估AI生成内容质量的技术","ja":"AIエージェント評価スキルは、AI生成コンテンツの品質を評価する技術です","ko":"AI 에이전트 평가 스킬은 AI 생성 콘텐츠의 품질을 평가하는 기술입니다","es":"El agent-evaluation es un marco de evaluación de la calidad de contenido generado por IA","fr":"L''agent-evaluation est un cadre d''évaluation de la qualité du contenu généré par l''IA","de":"Das agent-evaluation ist ein Bewertungsrahmen für die Qualität von KI-generiertem Inhalt","pt":"O que é Agent-Evaluation? É um framework de avaliação de qualidade de conteúdo gerado por IA","ru":"Что такое Agent-Evaluation? Это framework для оценки качества контента, сгенерированного ИИ","ar":"ما هو Agent-Evaluation? هو إطار تقييم لجودة المحتوى التوليدي بالاستناد إلى تقنيات الذكاء الاصطناعي"},"features":{"en":["Scores AI-generated content on 5 dimensions using a 1-5 rubric","Computes a weighted composite score for comprehensive evaluation","Emits a structured verdict with evidence citations for transparency","Systematic quality verification before claiming task completion","Pairs with task completion to ensure high-quality output"],"zh":["使用LLM-as-judge评估框架","评估AI生成内容的5个维度","使用1-5评分标准","计算加权合成评分","输出结构化的评估结果"],"ja":["LLM-as-judge評価フレームワークを使用","AI生成コンテンツの5つの要素を評価","1-5評価基準を使用","加重合成評価スコアを計算","構造化された評価結果を出力"],"ko":["LLM-as-judge 평가 프레임워크를 사용","AI 생성 콘텐츠의 5개 요소를 평가","1-5 평가 기준을 사용","가중 합성 평가 점수를 계산","구조화된 평가 결과를 출력"],"es":["Evaluación en 5 dimensiones","Puntuación compuesta ponderada","Verificación sistemática de la calidad","Emisión de un veredicto estructurado con citas de evidencia","Integración con la plataforma Agent-Studio"],"fr":["Évaluation sur 5 dimensions","Score composite pondéré","Vérification systématique de la qualité","Émission d''un verdict structuré avec des citations de preuves","Intégration avec la plateforme Agent-Studio"],"de":["Bewertung in 5 Dimensionen","Gewichteter Gesamtscore","Systematische Qualitätsverifizierung","Ausgabe eines strukturierten Urteils mit Beweiszitaten","Integration mit der Agent-Studio-Plattform"],"pt":["Avaliação de conteúdo gerado por IA com base em 5 dimensões","Utilização de uma rubrica de 1-5 para avaliar a qualidade do conteúdo","Cálculo de uma pontuação composta ponderada","Emissão de um veredicto estruturado com citações de evidências","Integração com o framework LLM-as-judge"],"ru":["Оценка контента, сгенерированного ИИ, на основе 5 измерений","Использование шкалы 1-5 для оценки качества контента","Расчет взвешенного составного балла","Выдача структурированного вердикта с цитатами доказательств","Интеграция с фреймворком LLM-as-judge"],"ar":["تقويم المحتوى التوليدي بالاستناد إلى 5 أبعاد","استخدام تصنيف 1-5 لتقويم جودة المحتوى","حساب درجة مركبة موزونة","إصدار حكم منظم مع إشارات إلى أدلة","التكامل مع إطار LLM-as-judge"]},"keywords":{"en":["how to use agent-evaluation","what is agent-evaluation","agent-evaluation alternative","agent-evaluation vs LLM","agent-evaluation install","agent-evaluation setup guide","LLM-as-judge evaluation framework","AI-generated content quality assessment"],"zh":["AI代理评估技能","LLM-as-judge评估框架","AI生成内容评估","质量验证","系统化评估","AI技术"],"ja":["AIエージェント評価スキル","LLM-as-judge評価フレームワーク","AI生成コンテンツの評価","品質検証","体系的な評価","AI技術"],"ko":["AI 에이전트 평가 스킬","LLM-as-judge 평가 프레임워크","AI 생성 콘텐츠 평가","품질 검증","체계적인 평가","AI 기술"],"es":["agent-evaluation","evaluación de contenido generado por IA","verificación de calidad","AI Agentes","Agent-Studio","evaluación en 5 dimensiones","puntuación compuesta","vérification sistemática"],"fr":["agent-evaluation","évaluation de contenu généré par l''IA","vérification de la qualité","outils d''IA","Agent-Studio","évaluation sur 5 dimensions","score composite","vérification systématique"],"de":["agent-evaluation","Bewertung von KI-generiertem Inhalt","Qualitätsverifizierung","KI-Agenten","Agent-Studio","Bewertung in 5 Dimensionen","Gewichteter Gesamtscore","systematische Qualitätsverifizierung"],"pt":["Agent-Evaluation","avaliação de qualidade de conteúdo","IA","conteúdo gerado por IA","rubrica de 1-5","pontuação composta","veredicto estruturado","LLM-as-judge"],"ru":["Agent-Evaluation","оценка качества контента","ИИ","контент, сгенерированный ИИ","шкала 1-5","взвешенный составной балл","структурированный вердикт","LLM-as-judge"],"ar":["Agent-Evaluation","تقويم جودة المحتوى","الذكاء الاصطناعي","المحتوى التوليدي","تصنيف 1-5","درجة مركبة","حكم منظم","LLM-as-judge"]}},"owner":"oimiragieo","repo":"agent-studio","repoPath":"oimiragieo/agent-studio","stars":14,"forks":0,"updatedAt":"2026-03-02T01:27:17Z","topics":[],"category":"community","skillMd":{"name":"agent-evaluation","description":"LLM-as-judge evaluation framework with 5-dimension rubric (accuracy, groundedness, coherence, completeness, helpfulness) for scoring AI-generated content quality with weighted composite scores and evidence citations","version":"1.2.0","tags":["evaluation","llm-judge","quality","rubric","scoring","ai-output"],"bodyPreview":"# Agent Evaluation\n\n## Overview\n\nLLM-as-judge evaluation framework that scores AI-generated content on 5 dimensions using a 1-5 rubric. Agents evaluate outputs, compute a weighted composite score, and emit a structured verdict with evidence citations.\n\n**Core principle:** Systematic quality verification before claiming completion. Agent-studio currently has no way to verify agent output quality — this skill fills that gap.\n\n## When to Use\n\n**Always:**\n\n- Before marking a task complete (pair with","body":"# Agent Evaluation\n\n## Overview\n\nLLM-as-judge evaluation framework that scores AI-generated content on 5 dimensions using a 1-5 rubric. Agents evaluate outputs, compute a weighted composite score, and emit a structured verdict with evidence citations.\n\n**Core principle:** Systematic quality verification before claiming completion. Agent-studio currently has no way to verify agent output quality — this skill fills that gap.\n\n## When to Use\n\n**Always:**\n\n- Before marking a task complete (pair with `verification-before-completion`)\n- After a plan is generated (evaluate plan quality)\n- After code review outputs (evaluate review quality)\n- During reflection cycles (evaluate agent responses)\n- When comparing multiple agent outputs\n\n**Don''t Use:**\n\n- For binary pass/fail checks (use `verification-before-completion` instead)\n- For security audits (use `security-architect` skill)\n- For syntax/lint checking (use `pnpm lint:fix`)\n\n## The 5-Dimension Rubric\n\nEvery evaluation scores all 5 dimensions on a 1-5 scale:\n\n| Dimension        | Weight | What It Measures                                                                  |\n| ---------------- | ------ | --------------------------------------------------------------------------------- |\n| **Accuracy**     | 30%    | Factual correctness; no hallucinations; claims are verifiable                     |\n| **Groundedness** | 25%    | Claims are supported by citations, file references, or evidence from the codebase |\n| **Coherence**    | 15%    | Logical flow; internally consistent; no contradictions                            |\n| **Completeness** | 20%    | All required aspects addressed; no critical gaps                                  |\n| **Helpfulness**  | 10%    | Actionable; provides concrete next steps; reduces ambiguity                       |\n\n### Scoring Scale (1-5)\n\n| Score | Meaning                                                       |\n| ----- | ------------------------------------------------------------- |\n| **5** | Excellent — fully meets the dimension''s criteria with no gaps |\n| **4** | Good — meets criteria with minor gaps                         |\n| **3** | Adequate — partially meets criteria; some gaps present        |\n| **2** | Poor — significant gaps or errors in this dimension           |\n| **1** | Failing — does not meet the dimension''s criteria              |\n\n## Execution Process\n\n### Step 1: Load the Output to Evaluate\n\nIdentify what is being evaluated:\n\n```\n- Agent response (text)\n- Plan document (file path)\n- Code review output (text/file)\n- Skill invocation result (text)\n- Task completion claim (TaskGet metadata)\n```\n\n### Step 2: Score Each Dimension\n\nFor each of the 5 dimensions, provide:\n\n1. **Score (1-5)**: The numeric score\n2. **Evidence**: Direct quote or file reference from the evaluated output\n3. **Rationale**: Why this score was given (1-2 sentences)\n\n**Dimension 1: Accuracy**\n\n```\nChecklist:\n- [ ] Claims are factually correct (verify against codebase if possible)\n- [ ] No hallucinated file paths, function names, or API calls\n- [ ] Numbers and counts are accurate\n- [ ] No contradictions with existing documentation\n```\n\n**Dimension 2: Groundedness**\n\n```\nChecklist:\n- [ ] Claims cite specific files, line numbers, or task IDs\n- [ ] Recommendations reference observable evidence\n- [ ] No unsupported assertions (\"this is probably X\")\n- [ ] Code examples use actual project patterns\n```\n\n**Dimension 3: Coherence**\n\n```\nChecklist:\n- [ ] Logical flow from problem → analysis → recommendation\n- [ ] No internal contradictions\n- [ ] Terminology is consistent throughout\n- [ ] Steps are in a rational order\n```\n\n**Dimension 4: Completeness**\n\n```\nChecklist:\n- [ ] All required aspects of the task are addressed\n- [ ] Edge cases are mentioned (if relevant)\n- [ ] No critical gaps that would block action\n- [ ] Follow-up steps are included\n```\n\n**Dimension 5: Helpfulness**\n\n```\nChecklist:\n- [ ] Provides actionable next steps (not just observations)\n- [ ] Concrete enough to act on without further clarification\n- [ ] Reduces ambiguity rather than adding it\n- [ ] Appropriate for the intended audience\n```\n\n### Step 3: Compute Weighted Composite Score\n\n```\ncomposite = (accuracy × 0.30) + (groundedness × 0.25) + (completeness × 0.20) + (coherence × 0.15) + (helpfulness × 0.10)\n```\n\n### Step 4: Determine Verdict\n\n| Composite Score | Verdict   | Action                              |\n| --------------- | --------- | ----------------------------------- |\n| 4.5 – 5.0       | EXCELLENT | Approve; proceed                    |\n| 3.5 – 4.4       | GOOD      | Approve with minor notes            |\n| 2.5 – 3.4       | ADEQUATE  | Request targeted improvements       |\n| 1.5 – 2.4       | POOR      | Reject; requires significant rework |\n| 1.0 – 1.4       | FAILING   | Reject; restart task                |\n\n### Step 5: Emit Structured Verdict\n\nOutput the verdict in this format:\n\n```markdown\n## Evaluation Verdict\n\n**Output Evaluated**: [Brief description of what was evaluated]\n**Evaluator**: [Agent name / task ID]\n**Date**: [ISO 8601 date]\n\n### Dimension Scores\n\n| Dimension     | Score | Weight | Weighted Score |\n| ------------- | ----- | ------ | -------------- |\n| Accuracy      | X/5   | 30%    | X.X            |\n| Groundedness  | X/5   | 25%    | X.X            |\n| Completeness  | X/5   | 20%    | X.X            |\n| Coherence     | X/5   | 15%    | X.X            |\n| Helpfulness   | X/5   | 10%    | X.X            |\n| **Composite** |       |        | **X.X / 5.0**  |\n\n### Evidence Citations\n\n**Accuracy (X/5)**:\n\n> [Direct quote or file:line reference]\n> Rationale: [Why this score]\n\n**Groundedness (X/5)**:\n\n> [Direct quote or file:line reference]\n> Rationale: [Why this score]\n\n**Completeness (X/5)**:\n\n> [Direct quote or file:line reference]\n> Rationale: [Why this score]\n\n**Coherence (X/5)**:\n\n> [Direct quote or file:line reference]\n> Rationale: [Why this score]\n\n**Helpfulness (X/5)**:\n\n> [Direct quote or file:line reference]\n> Rationale: [Why this score]\n\n### Verdict: [EXCELLENT | GOOD | ADEQUATE | POOR | FAILING]\n\n**Summary**: [1-2 sentence overall assessment]\n\n**Required Actions** (if verdict is ADEQUATE or worse):\n\n1. [Specific improvement needed]\n2. [Specific improvement needed]\n```\n\n## Usage Examples\n\n### Evaluate a Plan Document\n\n```javascript\n// Load plan document\nRead({ file_path: ''.claude/context/plans/auth-design-plan-2026-02-21.md'' });\n\n// Evaluate against 5-dimension rubric\nSkill({ skill: ''agent-evaluation'' });\n// Provide the plan content as the output to evaluate\n```\n\n### Evaluate Agent Response Before Completion\n\n```javascript\n// Agent generates implementation summary\n// Before marking task complete, evaluate the summary quality\nSkill({ skill: ''agent-evaluation'' });\n// If composite < 3.5, request improvements before TaskUpdate(completed)\n```\n\n### Evaluate Code Review Output\n\n```javascript\n// After code-reviewer runs, evaluate the review quality\nSkill({ skill: ''agent-evaluation'' });\n// Ensures review is grounded in actual code evidence, not assertions\n```\n\n### Batch Evaluation (comparing two outputs)\n\n```javascript\n// Evaluate output A\n// Save verdict A\n// Evaluate output B\n// Save verdict B\n// Compare composites → choose higher scoring output\n```\n\n## Integration with Verification-Before-Completion\n\nThe recommended quality gate pattern:\n\n```javascript\n// Step 1: Do the work\n// Step 2: Evaluate with agent-evaluation\nSkill({ skill: ''agent-evaluation'' });\n// If verdict is POOR or FAILING → rework before proceeding\n// If verdict is ADEQUATE or better → proceed to verification\n// Step 3: Final gate\nSkill({ skill: ''verification-before-completion'' });\n// Step 4: Mark complete\nTaskUpdate({ taskId: ''X'', status: ''completed'' });\n```\n\n## Iron Laws\n\n1. **NO COMPLETION CLAIM WITHOUT EVALUATION EVIDENCE** — If composite score < 2.5 (POOR or FAILING), rework the output before marking any task complete.\n2. **ALWAYS score all 5 dimensions** — never skip dimensions to save time; each dimension catches different failure modes (accuracy ≠ completeness ≠ groundedness).\n3. **ALWAYS cite specific evidence** for every dimension score — `\"Evidence: [file:line or direct quote]\"` is mandatory, not optional. Assertions without grounding are invalid.\n4. **ALWAYS use the weighted composite** — `accuracy×0.30 + groundedness×0.25 + completeness×0.20 + coherence×0.15 + helpfulness×0.10`. Never use simple average.\n5. **NEVER evaluate before the work is complete** — evaluating incomplete outputs produces falsely low scores and wastes context budget.\n\n## Anti-Patterns\n\n| Anti-Pattern                       | Why It Fails                                                 | Correct Approach                                         |\n| ---------------------------------- | ------------------------------------------------------------ | -------------------------------------------------------- |\n| Skipping dimensions to save time   | Each dimension catches different failures                    | Always score all 5 dimensions                            |\n| No evidence citation per dimension | Assertions without grounding are invalid                     | Quote specific text or file:line for every score         |\n| Using simple average for composite | Accuracy (30%) matters more than helpfulness (10%)           | Use the weighted composite formula                       |\n| Only checking EXCELLENT vs FAILING | ADEQUATE outputs need targeted improvements, not full rework | Use all 5 verdict tiers with appropriate action per tier |\n| Evaluating before work is done     | Incomplete outputs score falsely low                         | Evaluate completed outputs only                          |\n| Treating evaluation as binary gate | Quality is a spectrum; binary pass/fail loses nuance         | Use composite score + per-dimension breakdown together   |\n\n## Assigned Agents\n\nThis skill is used by:\n\n- `qa` — Primary: validates test outputs and QA reports before completion\n- `code-reviewer` — Supporting: evaluates code review quality\n- `reflection-agent` — Supporting: evaluates agent responses during reflection cycles\n\n## Memory Protocol (MANDATORY)\n\n**Before starting:**\n\n```bash\ncat .claude/context/memory/learnings.md\n```\n\nCheck for:\n\n- Previous evaluation scores for similar outputs\n- Known quality patterns in this codebase\n- Common failure modes for this task type\n\n**After completing:**\n\n- Evaluation pattern found -> `.claude/context/memory/learnings.md`\n- Quality issue identified -> `.claude/context/memory/issues.md`\n- Decision about rubric weights -> `.claude/context/memory/decisions.md`\n\n> ASSUME INTERRUPTION: Your context may reset. If it''s not in memory, it didn''t happen.\n"},"lastSynced":"2026-03-06T06:44:05.538Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing systematic quality verification of generated content, such as Cursor, Windsurf, or Claude Code, to ensure high-quality output.","zh":"非常适合需要系统性质量验证的AI代理生成内容，例如Cursor、Windsurf或Claude Code，以确保高质量输出。","ja":"AIエージェントが生成したコンテンツの体系的な品質検証を必要とする場合、たとえばCursor、Windsurf、またはClaude Codeの場合に最適で、高品質の出力が保証されます。","ko":"시스템적인 품질 검증이 필요한 AI 에이전트가 생성한 콘텐츠에 적합합니다. 예를 들어 Cursor, Windsurf 또는 Claude Code와 같은 경우에 높은 품질의 출력을 보장합니다.","es":"Perfecto para Agentes de IA que necesitan una verificación de calidad sistemática del contenido generado, como Cursor, Windsurf o Claude Code, para garantizar una salida de alta calidad.","fr":"Parfait pour les agents IA ayant besoin d''une vérification de qualité systématique du contenu généré, tels que Cursor, Windsurf ou Claude Code, pour assurer une sortie de haute qualité.","de":"Perfekt für KI-Agents, die eine systematische Qualitätsverifizierung des generierten Inhalts benötigen, wie z.B. Cursor, Windsurf oder Claude Code, um eine hochwertige Ausgabe zu gewährleisten.","pt":"Perfeito para Agentes de IA que necessitam de verificação de qualidade sistemática do conteúdo gerado, como Cursor, Windsurf ou Claude Code, para garantir saída de alta qualidade.","ru":"Идеально подходит для агентов ИИ, которым требуется систематическая проверка качества сгенерированного контента, такой как Cursor, Windsurf или Claude Code, для обеспечения высококачественного вывода.","ar":"مثالي لعمليات التحقق من جودة المحتوى المُ生的 بواسطة وكلاء الذكاء الاصطناعي، مثل Cursor و Windsurf و Claude Code، لضمان الإخراج عالي الجودة."},"recommendation":{"en":"Empowers agents to evaluate AI-generated content using a 1-5 rubric, providing a weighted composite score and structured verdict with evidence citations, leveraging LLM-as-judge evaluation framework and supporting protocols like LangChain.","zh":"赋予代理评估AI生成的内容的能力，使用1-5评分标准，提供加权综合评分和结构化判决，并附有证据引用，利用LLM-as-judge评估框架和支持的协议，如LangChain。","ja":"エージェントにAI生成コンテンツを評価する能力を付与し、1-5のルーブリックを使用して加重合計スコアと構造化された判決を提供し、証拠引用を付与し、LLM-as-judge評価フレームワークとLangChainなどのサポートプロトコルを利用します。","ko":"에이전트가 AI 생성 콘텐츠를 평가할 수 있는 기능을 부여하여 1-5 평점 기준을 사용하고 가중 합계 점수와 구조화된 판단을 제공하며 증거 인용을 첨부하고 LLM-as-judge 평가 프레임워크와 LangChain 같은 지원 프로토콜을 활용합니다.","es":"Habilita a los agentes a evaluar el contenido generado por IA utilizando una rúbrica de 1 a 5, proporcionando una puntuación compuesta ponderada y un veredicto estructurado con citas de evidencia, aprovechando el marco de evaluación LLM-as-judge y protocolos como LangChain.","fr":"Permet aux agents d''évaluer le contenu généré par IA en utilisant une rubrique de 1 à 5, fournissant un score composite pondéré et un verdict structuré avec des citations de preuves, en exploitant le cadre d''évaluation LLM-as-judge et des protocoles comme LangChain.","de":"Ermöglicht es Agents, den von KI generierten Inhalt unter Verwendung einer 1-5-Rubrik zu bewerten, indem eine gewichtete Zusammensetzungs-Punktzahl und ein strukturierter Verdikt mit Beweiszitaten bereitgestellt werden, wobei das LLM-as-judge-Bewertungsframework und Protokolle wie LangChain genutzt werden.","pt":"Habilita os agentes a avaliar o conteúdo gerado por IA usando uma rubrica de 1-5, fornecendo uma pontuação composta ponderada e um veredicto estruturado com citações de evidências, aproveitando o quadro de avaliação LLM-as-judge e protocolos como LangChain.","ru":"Наделяет агентов возможностью оценивать контент, сгенерированный ИИ, используя рубрику 1-5, предоставляя взвешенный композитный балл и структурированный вердикт с ссылками на доказательства, используя оценочный фреймворк LLM-as-judge и поддерживаемые протоколы, такие как LangChain.","ar":"تمكّن الوكلاء من تقييم المحتوى المُ生的 بواسطة الذكاء الاصطناعي باستخدام روب리카 1-5، مع توفير درجة مركبة موزونة و حكم منظم مع إشارات إلى الأدلة، مستفيداً من إطار التقييم LLM-as-judge و البروتوكولات المدعومة مثل LangChain."},"useCases":{"en":["Evaluating chatbot responses for accuracy","Assessing code quality generated by AutoGPT","Validating content created by AI agents for completeness and coherence"],"zh":["评估聊天机器人响应的准确性","评估AutoGPT生成的代码质量","验证AI代理创建的内容的完整性和连贯性"],"ja":["チャットボットの応答の正確性を評価する","AutoGPTによって生成されたコードの品質を評価する","AIエージェントによって生成されたコンテンツの完全性と一貫性を検証する"],"ko":["채팅봇 응답의 정확성을 평가한다","AutoGPT로 생성된 코드 품질을 평가한다","AI 에이전트가 생성한 콘텐츠의 완전성과 일관성을 검증한다"],"es":["Evaluar las respuestas de los chatbots para precisión","Evaluar la calidad del código generado por AutoGPT","Validar el contenido creado por los agentes de IA para completitud y coherencia"],"fr":["Évaluer les réponses des chatbots pour l''exactitude","Évaluer la qualité du code généré par AutoGPT","Valider le contenu créé par les agents IA pour l''exhaustivité et la cohérence"],"de":["Die Antworten von Chatbots auf Genauigkeit bewerten","Die Qualität des von AutoGPT generierten Codes bewerten","Den von KI-Agents erstellten Inhalt auf Vollständigkeit und Kohärenz überprüfen"],"pt":["Avaliando respostas de chatbot para precisão","Avaliando a qualidade do código gerado por AutoGPT","Validando o conteúdo criado por agentes de IA para completude e coerência"],"ru":["Оценка ответов чат-бота на точность","Оценка качества кода, сгенерированного AutoGPT","Проверка контента, созданного агентами ИИ, на полноту и связность"],"ar":["تقييم استجابات برنامج المحادثة لالدقة","تقييم جودة الكود المُ生的 بواسطة AutoGPT","التحقق من المحتوى المُ生的 بواسطة وكلاء الذكاء الاصطناعي للكامل والمنطق"]},"limitations":{"en":["Requires LLM-as-judge evaluation framework integration","Limited to 5-dimensional scoring rubric"],"zh":["需要LLM-as-judge评估框架集成","仅限5维评分标准"],"ja":["LLM-as-judge評価フレームワークの統合が必要","5次元の評価基準のみ"],"ko":["LLM-as-judge 평가 프레임워크 통합이 필요하다","5차원 평점 기준만 해당"],"es":["Requiere la integración del marco de evaluación LLM-as-judge","Limitado a una rúbrica de puntuación de 5 dimensiones"],"fr":["Nécessite l''intégration du cadre d''évaluation LLM-as-judge","Limité à une rubrique de notation à 5 dimensions"],"de":["Erfordert die Integration des LLM-as-judge-Bewertungsframeworks","Begrenzt auf eine 5-dimensionale Bewertungsrubrik"],"pt":["Exige integração do quadro de avaliação LLM-as-judge","Limitado a uma rubrica de avaliação de 5 dimensões"],"ru":["Требует интеграции оценочного фреймворка LLM-as-judge","Ограничен рубрикой оценки 5-мерной"],"ar":["يتطلب دمج إطار التقييم LLM-as-judge","محدود بروبリカ 5-أبعاد"]},"version":4},"contentHash":"cd4fd70eeb53b06c6d7fb50721868abe1b408d7bec1745b609a0b3a7402498bb","qualityScore":64}');
