INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('oimiragieo/agent-studio/agent-evaluation', 'agent-evaluation', 'oimiragieo', 'agent-studio', 'community', 'agent-evaluation oimiragieo agent-studio community The agent-evaluation skill is a systematic quality verification framework that scores AI-generated content using a 1-5 rubric, benefiting AI agent developers and users alike. AI代理评估技能是一种LLM-as-judge评估框架，使用1-5评分标准评估AI生成内容的5个维度 AIエージェント評価スキルは、LLM-as-judge評価フレームワークを使用し、AI生成コンテンツの5つの要素を1-5評価基準で評価します AI 에이전트 평가 스킬은 LLM-as-judge 평가 프레임워크를 사용하여 AI 생성 콘텐츠의 5개 요소를 1-5 평가 기준으로 평가합니다 El agent-evaluation es un marco de evaluación que califica el contenido generado por IA en 5 dimensiones. Permite una verificación sistemática de la calidad L''agent-evaluation est un cadre d''évaluation qui note le contenu généré par l''IA sur 5 dimensions. Il permet une vérification systématique de la qualité Das agent-evaluation ist ein Bewertungsrahmen, der den von KI generierten Inhalt in 5 Dimensionen bewertet. Es ermöglicht eine systematische Qualitätsverifizierung O Agent-Evaluation é um framework de avaliação que utiliza uma rubrica de 1-5 para avaliar a qualidade do conteúdo gerado por IA, com base em 5 dimensões Agent-Evaluation - это framework для оценки качества контента, сгенерированного ИИ, на основе 5 измерений и шкалы 1-5 Agent-Evaluation هو إطار تقييم يستخدم تصنيف 1-5 لتقويم جودة المحتوى التوليدي بالاعتماد على 5 أبعاد how to use agent-evaluation what is agent-evaluation agent-evaluation alternative agent-evaluation vs LLM agent-evaluation install agent-evaluation setup guide LLM-as-judge evaluation framework AI-generated content quality assessment AI代理评估技能 LLM-as-judge评估框架 AI生成内容评估 质量验证 系统化评估 AI技术 Scores AI-generated content on 5 dimensions using a 1-5 rubric Computes a weighted composite score for comprehensive evaluation Emits a structured verdict with evidence citations for transparency Systematic quality verification before claiming task completion Pairs with task completion to ensure high-quality output agent-evaluation is a LLM-as-judge evaluation framework that assesses AI-generated content quality using a weighted composite score and structured verdict with evidence citations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vamseeachanta/workspace-hub/state-directory-manager', 'community', 'vamseeachanta', 'workspace-hub', 'vamseeachanta/workspace-hub', 'state-directory-manager', 0, 0, 64, '2026-03-08T01:57:15.303Z', '2026-03-08T02:01:45.533Z', '8f7d8b1f282e83826f6fb54180381c3bfb5f821edee1c9ae5bc11c0396de2d08', '{"id":"vamseeachanta/workspace-hub/state-directory-manager","name":"state-directory-manager","description":{"en":"state-directory-manager is a centralized management system for multiple GitHub repositories, enabling modular organization and persistent state management. It benefits developers working with bash scripts and requiring data persistence.","zh":"State Directory Manager 是一个按 XDG 基础目录规范管理持久状态、配置和缓存目录的集中管理系统，适用于需要持久数据的 Bash 脚本","ja":"State Directory Manager は、AIエージェントによるモジュラーなディレクトリ管理を提供する集中管理システムです","ko":"State Directory Manager는 Bash 스크립트의 모듈러 디렉토리 관리를 위한集中 관리 시스템입니다","es":"State-directory-manager es un sistema de gestión centralizado para múltiples repositorios de GitHub con organización modular, ideal para persistir datos entre ejecuciones y almacenar preferencias de usuario","fr":"State-directory-manager est un système de gestion centralisé pour plusieurs dépôts GitHub avec organisation modulaire, idéal pour persister des données entre exécutions et stocker les préférences utilisateur","de":"State-directory-manager ist ein zentrales Management-System für mehrere GitHub-Repositorys mit modularem Aufbau, ideal für die Persistenz von Daten zwischen Ausführungen und die Speicherung von Benutzervorlieben","pt":"O state-directory-manager é um sistema de gerenciamento centralizado para repositórios GitHub, permitindo uma organização modular","ru":"State-directory-manager — это централизованная система управления репозиториями GitHub с модульной организацией","ar":"state-directory-manager هو نظام إدارة مركزي لمستودعات GitHub، مما يسمح بالتنظيم المودуляري"},"seo":{"title":{"en":"state-directory-manager: Centralized GitHub Repo Manageme...","zh":"State Directory Manager 设置指南 - 按 XDG 基础目录规范管理持久状态","ja":"State Directory Manager のベストプラクティス - AIエージェントによるモジュラー管理","ko":"State Directory Manager 사용 가이드 - Bash 스크립트를 위한 모듈러 디렉토리 관리","es":"Guía de configuración de state-directory-manager para her...","fr":"Meilleures pratiques pour state-directory-manager, outil ...","de":"Einrichtungsleitfaden für state-directory-manager, ein ze...","pt":"Guia de Configuração do state-directory-manager para Ferr...","ru":"Настройка ИИ Агентов с state-directory-manager для Продук...","ar":"دليل إعداد state-directory-manager لأدوات التطوير الذكية"},"description":{"en":"Discover how to manage multiple GitHub repositories with state-directory-manager. Learn to persist data, store user preferences, and cache results for perfor...","zh":"使用 State Directory Manager 按 XDG 基础目录规范管理持久状态、配置和缓存目录，适用于需要持久数据的 Bash 脚本","ja":"AIエージェントを使用して、モジュラーなディレクトリ管理を実現する State Directory Manager の機能と使い方を紹介します","ko":"Bash 스크립트의 모듈러 디렉토리 관리를 위한 State Directory Manager 사용법과 장점을 소개합니다","es":"Aprenda a utilizar state-directory-manager para gestionar múltiples repositorios de GitHub con organización modular y siguiendo la especificación XDG Base Di...","fr":"Découvrez comment utiliser state-directory-manager pour gérer plusieurs dépôts GitHub avec une organisation modulaire et suivre la spécification XDG Base Dir...","de":"Erfahren Sie, wie Sie state-directory-manager verwenden können, um mehrere GitHub-Repositorys mit modularem Aufbau zu verwalten und die XDG-Base-Directory-Sp...","pt":"Aprenda a gerenciar repositórios GitHub de forma eficaz com o state-directory-manager e melhore a produtividade do seu time de desenvolvimento","ru":"Узнайте, как настроить ИИ Агенты с state-directory-manager для управления репозиториями GitHub и повысьте производительность вашей команды разработчиков","ar":"تعرف على كيفية إعداد state-directory-manager لتحسين إدارة مستودعات GitHub وزيادة إنتاجية فريق التطوير الخاص بك"},"definition":{"en":"state-directory-manager is a centralized management system following XDG Base Directory specification for managing persistent state, configuration, and cache directories in bash scripts.","zh":"State Directory Manager 是一个集中管理系统，用于管理 Bash 脚本的持久状态、配置和缓存目录","ja":"State Directory Manager は、AIエージェントによるモジュラーなディレクトリ管理を提供するシステムです","ko":"State Directory Manager는 Bash 스크립트의 모듈러 디렉토리 관리를 위한 시스템입니다","es":"State-directory-manager es un patrón para gestionar directorios de estado, configuración y caché en scripts de bash siguiendo la especificación XDG Base Directory","fr":"State-directory-manager est un patron pour gérer des répertoires d''état, de configuration et de cache dans des scripts bash suivant la spécification XDG Base Directory","de":"State-directory-manager ist ein Muster für die Verwaltung von Status-, Konfigurations- und Cache-Verzeichnissen in Bash-Skripten unter Einhaltung der XDG-Base-Directory-Spezifikation","pt":"O state-directory-manager é um sistema que gerencia pastas de estado, configuração e cache em scripts bash","ru":"State-directory-manager — это система, которая управляет папками состояния, конфигурации и кэша в скриптах bash","ar":"state-directory-manager هو نظام يدير مجلدات الحالة والتهيئة والแคش في سكريبتات bash"},"features":{"en":["Manages persistent state, configuration, and cache directories in bash scripts","Follows XDG Base Directory specification for modular organization","Enables data persistence between script runs","Supports storing user preferences and configuration","Caches results for improved performance","Manages log files with rotation for efficient logging"],"zh":["按 XDG 基础目录规范管理持久状态","支持配置和缓存目录的管理","适用于需要持久数据的 Bash 脚本","提供模块化的目录管理","支持日志文件的轮替"],"ja":["AIエージェントによるモジュラーなディレクトリ管理","XDG 基礎ディレクトリ仕様に従った永続状態管理","設定とキャッシュディレクトリの管理をサポート","永続データを必要とする Bash スクリプトに適しています","モジュラーなディレクトリ管理を提供","ログファイルのローテーションをサポート"],"ko":["Bash 스크립트의 모듈러 디렉토리 관리","XDG 基础目录规范에 따른 영속 상태 관리","설정과 캐시 디렉토리의 관리를 지원","영속 데이터를 필요로 하는 Bash 스크립트에 적합","모듈러한 디렉토리 관리를 제공","로그 파일의轮替를 지원"],"es":["Gestión de directorios de estado y configuración","Seguimiento de la especificación XDG Base Directory","Persistencia de datos entre ejecuciones","Almacenamiento de preferencias de usuario","Gestión de archivos de registro con rotación","Creación de herramientas de línea de comandos portátiles"],"fr":["Gestion des répertoires d''état et de configuration","Suivi de la spécification XDG Base Directory","Persistance des données entre exécutions","Stockage des préférences utilisateur","Gestion des fichiers de journal avec rotation","Création d''outils de ligne de commande portables"],"de":["Verwaltung von Status- und Konfigurationsverzeichnissen","Einhaltung der XDG-Base-Directory-Spezifikation","Persistenz von Daten zwischen Ausführungen","Speicherung von Benutzervorlieben","Verwaltung von Log-Dateien mit Rotation","Erstellung portabler Kommandozeilen-Tools"],"pt":["Gerenciamento de pastas de estado e configuração","Suporte à especificação XDG Base Directory","Organização modular de repositórios GitHub","Cache de resultados para melhorar o desempenho","Geração de logs com rotação"],"ru":["Управление папками состояния и конфигурации","Поддержка спецификации XDG Base Directory","Модульная организация репозиториев GitHub","Кэширование результатов для повышения производительности","Генерация логов с ротацией"],"ar":["إدارة مجلدات الحالة والتهيئة","دعم مواصفات XDG Base Directory","تنظيم مودуляري لمستودعات GitHub","تخزين النتائج لتحسين الأداء","توليد سجلات مع الدوران"]},"keywords":{"en":["how to use state-directory-manager","state-directory-manager setup guide","what is state-directory-manager","state-directory-manager alternative","state-directory-manager vs git","state-directory-manager install","bash script state management","XDG Base Directory specification","persistent state management"],"zh":["State Directory Manager","XDG 基础目录规范","Bash 脚本","持久状态管理","配置管理","缓存管理","AI 工具","集中管理系统"],"ja":["State Directory Manager","AIエージェント","XDG 基礎ディレクトリ仕様","Bash スクリプト","永続状態管理","設定管理","キャッシュ管理","モジュラーなディレクトリ管理"],"ko":["State Directory Manager","Bash 스크립트","XDG 基础目录规范","영속 상태 관리","설정 관리","캐시 관리","모듈러한 디렉토리 관리","AI 도구"],"es":["state-directory-manager","herramientas de AI","gestión de estado","configuración de GitHub","XDG Base Directory","persistencia de datos","almacenamiento de preferencias de usuario","gestión de archivos de registro"],"fr":["state-directory-manager","outils d''IA","gestion d''état","configuration de GitHub","XDG Base Directory","persistance des données","stockage des préférences utilisateur","gestion des fichiers de journal"],"de":["state-directory-manager","AI-Tools","Statusverwaltung","GitHub-Konfiguration","XDG-Base-Directory","Datenpersistenz","Speicherung von Benutzervorlieben","Verwaltung von Log-Dateien"],"pt":["state-directory-manager","gerenciamento de repositórios github","organização modular","xdg base directory","cache de resultados","geração de logs","ferramentas de desenvolvimento","produtividade de desenvolvedores"],"ru":["state-directory-manager","управление репозиториями github","модульная организация","xdg base directory","кэширование результатов","генерация логов","инструменты разработки","производительность разработчиков","ИИ Агенты"],"ar":["state-directory-manager","إدارة مستودعات github","تنظيم مودуляري","xdg base directory","تخزين النتائج","توليد سجلات","أدوات التطوير","إنتاجية المطورين","أدوات الذكاء الاصطناعي"]}},"owner":"vamseeachanta","repo":"workspace-hub","repoPath":"vamseeachanta/workspace-hub","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.303Z","topics":[],"category":"community","skillMd":{"name":"state-directory-manager","description":"Manage persistent state directories for bash scripts","version":"1.0.0","tags":["bash","state","persistence","config","directory","xdg"],"bodyPreview":"# State Directory Manager\n\nPatterns for managing persistent state, configuration, and cache directories in bash scripts following XDG Base Directory specification.\n\n## When to Use This Skill\n\n✅ **Use when:**\n- Scripts need to persist data between runs\n- Storing user preferences or configuration\n- Caching results for performance\n- Managing log files with rotation\n- Creating portable CLI tools\n\n❌ **Avoid when:**\n- One-time scripts that don''t need state\n- Scripts that should be purely stateless\n- W","body":"# State Directory Manager\n\nPatterns for managing persistent state, configuration, and cache directories in bash scripts following XDG Base Directory specification.\n\n## When to Use This Skill\n\n✅ **Use when:**\n- Scripts need to persist data between runs\n- Storing user preferences or configuration\n- Caching results for performance\n- Managing log files with rotation\n- Creating portable CLI tools\n\n❌ **Avoid when:**\n- One-time scripts that don''t need state\n- Scripts that should be purely stateless\n- When environment variables are sufficient\n\n## Core Capabilities\n\n### 1. XDG Base Directory Standard\n\nFollow the XDG specification for directory locations:\n\n```bash\n#!/bin/bash\n# ABOUTME: XDG Base Directory compliant state management\n# ABOUTME: Cross-platform directory locations\n\n# XDG Base Directories with fallbacks\nXDG_CONFIG_HOME=\"${XDG_CONFIG_HOME:-$HOME/.config}\"\nXDG_DATA_HOME=\"${XDG_DATA_HOME:-$HOME/.local/share}\"\nXDG_STATE_HOME=\"${XDG_STATE_HOME:-$HOME/.local/state}\"\nXDG_CACHE_HOME=\"${XDG_CACHE_HOME:-$HOME/.cache}\"\n\n# Application-specific directories\nAPP_NAME=\"my-tool\"\nCONFIG_DIR=\"$XDG_CONFIG_HOME/$APP_NAME\"\nDATA_DIR=\"$XDG_DATA_HOME/$APP_NAME\"\nSTATE_DIR=\"$XDG_STATE_HOME/$APP_NAME\"\nCACHE_DIR=\"$XDG_CACHE_HOME/$APP_NAME\"\nLOG_DIR=\"$STATE_DIR/logs\"\n\n# Initialize directories\ninit_directories() {\n    mkdir -p \"$CONFIG_DIR\"\n    mkdir -p \"$DATA_DIR\"\n    mkdir -p \"$STATE_DIR\"\n    mkdir -p \"$CACHE_DIR\"\n    mkdir -p \"$LOG_DIR\"\n}\n```\n\n### 2. Workspace-Hub Pattern\n\nAlternative using home directory (from workspace-hub scripts):\n\n```bash\n#!/bin/bash\n# ABOUTME: Workspace-hub style state directory management\n# ABOUTME: Simple $HOME/.app-name pattern\n\nAPP_NAME=\"workspace-hub\"\nAPP_DIR=\"${HOME}/.${APP_NAME}\"\n\n# Directory structure\nCONFIG_DIR=\"$APP_DIR/config\"\nDATA_DIR=\"$APP_DIR/data\"\nLOGS_DIR=\"$APP_DIR/logs\"\nCACHE_DIR=\"$APP_DIR/cache\"\nTEMP_DIR=\"$APP_DIR/tmp\"\n\n# Initialize with proper permissions\ninit_app_dirs() {\n    local dirs=(\"$CONFIG_DIR\" \"$DATA_DIR\" \"$LOGS_DIR\" \"$CACHE_DIR\" \"$TEMP_DIR\")\n\n    for dir in \"${dirs[@]}\"; do\n        if [[ ! -d \"$dir\" ]]; then\n            mkdir -p \"$dir\"\n            chmod 700 \"$dir\"  # Private by default\n        fi\n    done\n}\n\n# Clean old temp files\nclean_temp() {\n    find \"$TEMP_DIR\" -type f -mtime +1 -delete 2>/dev/null || true\n}\n```\n\n### 3. Configuration File Management\n\nRead and write configuration files:\n\n```bash\n#!/bin/bash\n# ABOUTME: Configuration file management\n# ABOUTME: Key-value pairs with defaults\n\nCONFIG_FILE=\"$CONFIG_DIR/config\"\n\n# Default configuration\ndeclare -A DEFAULT_CONFIG=(\n    [\"parallel_workers\"]=\"5\"\n    [\"log_level\"]=\"INFO\"\n    [\"auto_sync\"]=\"true\"\n    [\"timeout\"]=\"30\"\n)\n\n# Initialize config with defaults\ninit_config() {\n    if [[ ! -f \"$CONFIG_FILE\" ]]; then\n        {\n            echo \"# Configuration for $APP_NAME\"\n            echo \"# Generated: $(date)\"\n            echo \"\"\n            for key in \"${!DEFAULT_CONFIG[@]}\"; do\n                echo \"${key}=${DEFAULT_CONFIG[$key]}\"\n            done\n        } > \"$CONFIG_FILE\"\n    fi\n}\n\n# Read config value\nget_config() {\n    local key=\"$1\"\n    local default=\"${2:-${DEFAULT_CONFIG[$key]:-}}\"\n\n    if [[ -f \"$CONFIG_FILE\" ]]; then\n        local value\n        value=$(grep \"^${key}=\" \"$CONFIG_FILE\" 2>/dev/null | cut -d''='' -f2-)\n        echo \"${value:-$default}\"\n    else\n        echo \"$default\"\n    fi\n}\n\n# Write config value\nset_config() {\n    local key=\"$1\"\n    local value=\"$2\"\n\n    init_config\n\n    if grep -q \"^${key}=\" \"$CONFIG_FILE\" 2>/dev/null; then\n        # Update existing\n        sed -i \"s|^${key}=.*|${key}=${value}|\" \"$CONFIG_FILE\"\n    else\n        # Add new\n        echo \"${key}=${value}\" >> \"$CONFIG_FILE\"\n    fi\n}\n\n# Load all config into associative array\nload_config() {\n    declare -gA CONFIG\n\n    # Start with defaults\n    for key in \"${!DEFAULT_CONFIG[@]}\"; do\n        CONFIG[$key]=\"${DEFAULT_CONFIG[$key]}\"\n    done\n\n    # Override with file values\n    if [[ -f \"$CONFIG_FILE\" ]]; then\n        while IFS=''='' read -r key value; do\n            [[ \"$key\" =~ ^#.*$ || -z \"$key\" ]] && continue\n            CONFIG[$key]=\"$value\"\n        done < \"$CONFIG_FILE\"\n    fi\n}\n\n# Usage\ninit_config\nload_config\necho \"Parallel workers: ${CONFIG[parallel_workers]}\"\nset_config \"parallel_workers\" \"10\"\n```\n\n### 4. State File Operations\n\nTrack persistent state between runs:\n\n```bash\n#!/bin/bash\n# ABOUTME: State file operations\n# ABOUTME: Track last run, progress, etc.\n\nSTATE_FILE=\"$STATE_DIR/state.json\"\n\n# Initialize state\ninit_state() {\n    if [[ ! -f \"$STATE_FILE\" ]]; then\n        cat > \"$STATE_FILE\" << EOF\n{\n    \"version\": \"1.0.0\",\n    \"created\": \"$(date -Iseconds)\",\n    \"last_run\": null,\n    \"run_count\": 0,\n    \"last_status\": null\n}\nEOF\n    fi\n}\n\n# Get state value (requires jq)\nget_state() {\n    local key=\"$1\"\n    local default=\"${2:-null}\"\n\n    if [[ -f \"$STATE_FILE\" ]] && command -v jq &>/dev/null; then\n        jq -r \".$key // $default\" \"$STATE_FILE\"\n    else\n        echo \"$default\"\n    fi\n}\n\n# Update state value (requires jq)\nset_state() {\n    local key=\"$1\"\n    local value=\"$2\"\n\n    init_state\n\n    if command -v jq &>/dev/null; then\n        local temp=$(mktemp)\n        jq \".$key = $value\" \"$STATE_FILE\" > \"$temp\" && mv \"$temp\" \"$STATE_FILE\"\n    fi\n}\n\n# Record run\nrecord_run() {\n    local status=\"$1\"\n\n    set_state \"last_run\" \"\\\"$(date -Iseconds)\\\"\"\n    set_state \"last_status\" \"\\\"$status\\\"\"\n    set_state \"run_count\" \"$(($(get_state run_count 0) + 1))\"\n}\n\n# Simple key-value state (no jq required)\nSTATE_KV_FILE=\"$STATE_DIR/state.kv\"\n\nget_state_kv() {\n    local key=\"$1\"\n    local default=\"$2\"\n\n    if [[ -f \"$STATE_KV_FILE\" ]]; then\n        grep \"^${key}=\" \"$STATE_KV_FILE\" 2>/dev/null | cut -d''='' -f2- || echo \"$default\"\n    else\n        echo \"$default\"\n    fi\n}\n\nset_state_kv() {\n    local key=\"$1\"\n    local value=\"$2\"\n\n    mkdir -p \"$(dirname \"$STATE_KV_FILE\")\"\n\n    if [[ -f \"$STATE_KV_FILE\" ]] && grep -q \"^${key}=\" \"$STATE_KV_FILE\"; then\n        sed -i \"s|^${key}=.*|${key}=${value}|\" \"$STATE_KV_FILE\"\n    else\n        echo \"${key}=${value}\" >> \"$STATE_KV_FILE\"\n    fi\n}\n```\n\n### 5. Cache Management\n\nImplement caching with expiration:\n\n```bash\n#!/bin/bash\n# ABOUTME: Cache management with TTL\n# ABOUTME: Store and retrieve cached data\n\nCACHE_TTL=\"${CACHE_TTL:-3600}\"  # 1 hour default\n\n# Get cache file path\ncache_path() {\n    local key=\"$1\"\n    local hash=$(echo -n \"$key\" | md5sum | cut -c1-16)\n    echo \"$CACHE_DIR/${hash}\"\n}\n\n# Check if cache is valid\ncache_valid() {\n    local key=\"$1\"\n    local ttl=\"${2:-$CACHE_TTL}\"\n    local path=$(cache_path \"$key\")\n\n    if [[ -f \"$path\" ]]; then\n        local age=$(($(date +%s) - $(stat -c %Y \"$path\" 2>/dev/null || stat -f %m \"$path\")))\n        [[ $age -lt $ttl ]]\n    else\n        return 1\n    fi\n}\n\n# Get from cache\ncache_get() {\n    local key=\"$1\"\n    local ttl=\"${2:-$CACHE_TTL}\"\n    local path=$(cache_path \"$key\")\n\n    if cache_valid \"$key\" \"$ttl\"; then\n        cat \"$path\"\n        return 0\n    fi\n    return 1\n}\n\n# Set cache\ncache_set() {\n    local key=\"$1\"\n    local value=\"$2\"\n    local path=$(cache_path \"$key\")\n\n    mkdir -p \"$CACHE_DIR\"\n    echo \"$value\" > \"$path\"\n}\n\n# Delete cache\ncache_delete() {\n    local key=\"$1\"\n    local path=$(cache_path \"$key\")\n    rm -f \"$path\"\n}\n\n# Clear all cache\ncache_clear() {\n    rm -rf \"$CACHE_DIR\"/*\n}\n\n# Clean expired cache entries\ncache_clean() {\n    local ttl=\"${1:-$CACHE_TTL}\"\n    find \"$CACHE_DIR\" -type f -mmin \"+$((ttl / 60))\" -delete 2>/dev/null || true\n}\n\n# Usage with automatic caching\nget_with_cache() {\n    local key=\"$1\"\n    local command=\"$2\"\n    local ttl=\"${3:-$CACHE_TTL}\"\n\n    if cache_valid \"$key\" \"$ttl\"; then\n        cache_get \"$key\"\n    else\n        local result\n        result=$(eval \"$command\")\n        cache_set \"$key\" \"$result\"\n        echo \"$result\"\n    fi\n}\n\n# Example\nresult=$(get_with_cache \"api_response\" \"curl -s https://api.example.com/data\" 300)\n```\n\n### 6. Log File Management\n\nManage logs with rotation:\n\n```bash\n#!/bin/bash\n# ABOUTME: Log file management with rotation\n# ABOUTME: Automatic cleanup of old logs\n\nLOG_FILE=\"$LOG_DIR/app.log\"\nLOG_MAX_SIZE=$((10 * 1024 * 1024))  # 10MB\nLOG_MAX_FILES=5\n\n# Initialize logging\ninit_logging() {\n    mkdir -p \"$LOG_DIR\"\n    touch \"$LOG_FILE\"\n}\n\n# Write to log\nlog_to_file() {\n    local level=\"$1\"\n    shift\n    local message=\"$*\"\n    local timestamp=$(date ''+%Y-%m-%d %H:%M:%S'')\n\n    echo \"[$timestamp] $level: $message\" >> \"$LOG_FILE\"\n\n    # Check if rotation needed\n    maybe_rotate_logs\n}\n\n# Rotate logs if needed\nmaybe_rotate_logs() {\n    if [[ -f \"$LOG_FILE\" ]]; then\n        local size=$(stat -c %s \"$LOG_FILE\" 2>/dev/null || stat -f %z \"$LOG_FILE\")\n\n        if [[ $size -gt $LOG_MAX_SIZE ]]; then\n            rotate_logs\n        fi\n    fi\n}\n\n# Perform log rotation\nrotate_logs() {\n    # Remove oldest\n    rm -f \"${LOG_FILE}.${LOG_MAX_FILES}\"\n\n    # Shift existing\n    for ((i=LOG_MAX_FILES-1; i>=1; i--)); do\n        if [[ -f \"${LOG_FILE}.$i\" ]]; then\n            mv \"${LOG_FILE}.$i\" \"${LOG_FILE}.$((i+1))\"\n        fi\n    done\n\n    # Rotate current\n    if [[ -f \"$LOG_FILE\" ]]; then\n        mv \"$LOG_FILE\" \"${LOG_FILE}.1\"\n        touch \"$LOG_FILE\"\n    fi\n}\n\n# Clean old logs\nclean_old_logs() {\n    local days=\"${1:-30}\"\n    find \"$LOG_DIR\" -name \"*.log*\" -mtime \"+$days\" -delete 2>/dev/null || true\n}\n\n# View recent logs\ntail_logs() {\n    local lines=\"${1:-50}\"\n    tail -n \"$lines\" \"$LOG_FILE\"\n}\n\n# Search logs\nsearch_logs() {\n    local pattern=\"$1\"\n    grep -h \"$pattern\" \"$LOG_DIR\"/*.log* 2>/dev/null | tail -100\n}\n```\n\n## Complete Example: State Manager Module\n\n```bash\n#!/bin/bash\n# ABOUTME: Complete state directory manager\n# ABOUTME: Reusable module for bash scripts\n\n# ─────────────────────────────────────────────────────────────────\n# State Directory Manager v1.0.0\n# ─────────────────────────────────────────────────────────────────\n\n# Application identity (override in your script)\n: \"${STATE_APP_NAME:=my-app}\"\n\n# Directory setup\nSTATE_BASE_DIR=\"${HOME}/.${STATE_APP_NAME}\"\nSTATE_CONFIG_DIR=\"$STATE_BASE_DIR/config\"\nSTATE_DATA_DIR=\"$STATE_BASE_DIR/data\"\nSTATE_CACHE_DIR=\"$STATE_BASE_DIR/cache\"\nSTATE_LOG_DIR=\"$STATE_BASE_DIR/logs\"\nSTATE_TMP_DIR=\"$STATE_BASE_DIR/tmp\"\n\n# File paths\nSTATE_CONFIG_FILE=\"$STATE_CONFIG_DIR/config\"\nSTATE_STATE_FILE=\"$STATE_DATA_DIR/state\"\nSTATE_LOG_FILE=\"$STATE_LOG_DIR/app.log\"\n\n# Settings\nSTATE_CACHE_TTL=\"${STATE_CACHE_TTL:-3600}\"\nSTATE_LOG_MAX_SIZE=\"${STATE_LOG_MAX_SIZE:-10485760}\"\nSTATE_LOG_MAX_FILES=\"${STATE_LOG_MAX_FILES:-5}\"\n\n# ─────────────────────────────────────────────────────────────────\n# Initialization\n# ─────────────────────────────────────────────────────────────────\n\nstate_init() {\n    local dirs=(\n        \"$STATE_CONFIG_DIR\"\n        \"$STATE_DATA_DIR\"\n        \"$STATE_CACHE_DIR\"\n        \"$STATE_LOG_DIR\"\n        \"$STATE_TMP_DIR\"\n    )\n\n    for dir in \"${dirs[@]}\"; do\n        if [[ ! -d \"$dir\" ]]; then\n            mkdir -p \"$dir\"\n            chmod 700 \"$dir\"\n        fi\n    done\n\n    # Initialize files\n    [[ -f \"$STATE_CONFIG_FILE\" ]] || touch \"$STATE_CONFIG_FILE\"\n    [[ -f \"$STATE_STATE_FILE\" ]] || touch \"$STATE_STATE_FILE\"\n    [[ -f \"$STATE_LOG_FILE\" ]] || touch \"$STATE_LOG_FILE\"\n}\n\n# ─────────────────────────────────────────────────────────────────\n# Config Functions\n# ─────────────────────────────────────────────────────────────────\n\nstate_config_get() {\n    local key=\"$1\"\n    local default=\"$2\"\n    grep \"^${key}=\" \"$STATE_CONFIG_FILE\" 2>/dev/null | cut -d''='' -f2- || echo \"$default\"\n}\n\nstate_config_set() {\n    local key=\"$1\"\n    local value=\"$2\"\n\n    if grep -q \"^${key}=\" \"$STATE_CONFIG_FILE\" 2>/dev/null; then\n        sed -i \"s|^${key}=.*|${key}=${value}|\" \"$STATE_CONFIG_FILE\"\n    else\n        echo \"${key}=${value}\" >> \"$STATE_CONFIG_FILE\"\n    fi\n}\n\nstate_config_list() {\n    cat \"$STATE_CONFIG_FILE\" 2>/dev/null | grep -v ''^#'' | grep -v ''^$''\n}\n\n# ─────────────────────────────────────────────────────────────────\n# State Functions\n# ─────────────────────────────────────────────────────────────────\n\nstate_get() {\n    local key=\"$1\"\n    local default=\"$2\"\n    grep \"^${key}=\" \"$STATE_STATE_FILE\" 2>/dev/null | cut -d''='' -f2- || echo \"$default\"\n}\n\nstate_set() {\n    local key=\"$1\"\n    local value=\"$2\"\n\n    if grep -q \"^${key}=\" \"$STATE_STATE_FILE\" 2>/dev/null; then\n        sed -i \"s|^${key}=.*|${key}=${value}|\" \"$STATE_STATE_FILE\"\n    else\n        echo \"${key}=${value}\" >> \"$STATE_STATE_FILE\"\n    fi\n}\n\n# ─────────────────────────────────────────────────────────────────\n# Cache Functions\n# ─────────────────────────────────────────────────────────────────\n\nstate_cache_key() {\n    echo -n \"$1\" | md5sum | cut -c1-16\n}\n\nstate_cache_get() {\n    local key=\"$1\"\n    local ttl=\"${2:-$STATE_CACHE_TTL}\"\n    local path=\"$STATE_CACHE_DIR/$(state_cache_key \"$key\")\"\n\n    if [[ -f \"$path\" ]]; then\n        local age=$(($(date +%s) - $(stat -c %Y \"$path\" 2>/dev/null || stat -f %m \"$path\")))\n        if [[ $age -lt $ttl ]]; then\n            cat \"$path\"\n            return 0\n        fi\n    fi\n    return 1\n}\n\nstate_cache_set() {\n    local key=\"$1\"\n    local value=\"$2\"\n    local path=\"$STATE_CACHE_DIR/$(state_cache_key \"$key\")\"\n    echo \"$value\" > \"$path\"\n}\n\nstate_cache_clear() {\n    rm -rf \"$STATE_CACHE_DIR\"/*\n}\n\n# ─────────────────────────────────────────────────────────────────\n# Log Functions\n# ─────────────────────────────────────────────────────────────────\n\nstate_log() {\n    local level=\"$1\"\n    shift\n    local message=\"$*\"\n    echo \"[$(date ''+%Y-%m-%d %H:%M:%S'')] $level: $message\" >> \"$STATE_LOG_FILE\"\n\n    # Auto-rotate\n    local size=$(stat -c %s \"$STATE_LOG_FILE\" 2>/dev/null || echo 0)\n    if [[ $size -gt $STATE_LOG_MAX_SIZE ]]; then\n        state_log_rotate\n    fi\n}\n\nstate_log_rotate() {\n    rm -f \"${STATE_LOG_FILE}.${STATE_LOG_MAX_FILES}\"\n    for ((i=STATE_LOG_MAX_FILES-1; i>=1; i--)); do\n        [[ -f \"${STATE_LOG_FILE}.$i\" ]] && mv \"${STATE_LOG_FILE}.$i\" \"${STATE_LOG_FILE}.$((i+1))\"\n    done\n    mv \"$STATE_LOG_FILE\" \"${STATE_LOG_FILE}.1\"\n    touch \"$STATE_LOG_FILE\"\n}\n\nstate_log_tail() {\n    tail -n \"${1:-50}\" \"$STATE_LOG_FILE\"\n}\n\n# ─────────────────────────────────────────────────────────────────\n# Cleanup Functions\n# ─────────────────────────────────────────────────────────────────\n\nstate_cleanup() {\n    # Clean temp files older than 1 day\n    find \"$STATE_TMP_DIR\" -type f -mtime +1 -delete 2>/dev/null || true\n\n    # Clean expired cache\n    find \"$STATE_CACHE_DIR\" -type f -mmin \"+$((STATE_CACHE_TTL / 60))\" -delete 2>/dev/null || true\n\n    # Clean old logs\n    find \"$STATE_LOG_DIR\" -name \"*.log.*\" -mtime +30 -delete 2>/dev/null || true\n}\n\nstate_reset() {\n    rm -rf \"$STATE_BASE_DIR\"\n    state_init\n}\n\n# ─────────────────────────────────────────────────────────────────\n# Auto-initialize\n# ─────────────────────────────────────────────────────────────────\n\nstate_init\n```\n\n## Usage in Scripts\n\n```bash\n#!/bin/bash\n# Your script that uses the state manager\n\n# Set app name before sourcing\nSTATE_APP_NAME=\"my-tool\"\n\n# Source the state manager\nsource /path/to/state-manager.sh\n\n# Now use it\nstate_config_set \"api_key\" \"abc123\"\napi_key=$(state_config_get \"api_key\")\n\nstate_set \"last_run\" \"$(date -Iseconds)\"\nstate_log \"INFO\" \"Script started\"\n\n# Use cache\nif ! result=$(state_cache_get \"api_response\"); then\n    result=$(curl -s https://api.example.com/data)\n    state_cache_set \"api_response\" \"$result\"\nfi\n```\n\n## Best Practices\n\n1. **Use Standard Locations** - Follow XDG or `$HOME/.app-name`\n2. **Initialize Early** - Call init before any operations\n3. **Handle Permissions** - Use 700 for private data\n4. **Clean Up Regularly** - Remove old temp/cache files\n5. **Rotate Logs** - Prevent unbounded growth\n\n## Resources\n\n- [XDG Base Directory Spec](https://specifications.freedesktop.org/basedir-spec/basedir-spec-latest.html)\n- [File Hierarchy Standard](https://refspecs.linuxfoundation.org/FHS_3.0/fhs/index.html)\n\n---\n\n## Version History\n\n- **1.0.0** (2026-01-14): Initial release - extracted from workspace-hub patterns\n"},"lastSynced":"2026-03-08T02:01:45.533Z","agentAnalysis":{"suitability":{"en":"Perfect for CLI Agents needing persistent state management and modular organization across multiple GitHub repositories.","zh":"非常适合需要持久状态管理和跨多个GitHub仓库的模块化组织的CLI代理。","ja":"CLIエージェントが永続的な状態管理と複数のGitHubリポジトリを横断するモジュラーな組織が必要な場合に最適です。","ko":"CLI 에이전트가 지속적인 상태 관리와 여러 GitHub 저장소를横断하는 모듈식 구성이 필요한 경우에 적합합니다.","es":"Perfecto para agentes de CLI que necesitan gestión de estado persistente y organización modular en varios repositorios de GitHub.","fr":"Parfait pour les agents CLI nécessitant une gestion d''état persistante et une organisation modulaire à travers plusieurs référentiels GitHub.","de":"Perfekt für CLI-Agents, die eine persistente Zustandsverwaltung und eine modulare Organisation über mehrere GitHub-Repositorys benötigen.","pt":"Perfeito para Agentes CLI que necessitam de gerenciamento de estado persistente e organização modular em vários repositórios GitHub.","ru":"Идеально подходит для агентов CLI, требующих управления постоянным состоянием и модульной организации на нескольких репозиториях GitHub.","ar":"مثالي لعميل CLI الذي يحتاج إلى إدارة حالة مستدامة وتنظيم مدمج عبر مستودعات GitHub المتعددة."},"recommendation":{"en":"Empowers agents to manage persistent state, configuration, and cache directories in bash scripts following the XDG Base Directory specification, enabling data persistence and performance caching with log file rotation.","zh":"赋予代理管理持久状态、配置和缓存目录的能力，使用bash脚本遵循XDG Base Directory规范，实现数据持久性和性能缓存，并具有日志文件轮换功能。","ja":"エージェントがXDG Base Directory仕様に従ってbashスクリプトで永続的な状態、設定、およびキャッシュディレクトリを管理できるようにし、データの永続性とパフォーマンスのキャッシュを実現し、ログファイルをローテーションすることができます。","ko":"에이전트가 XDG Base Directory 사양을 따르는 bash 스크립트에서 지속적인 상태, 구성 및 캐시 디렉토리를 관리할 수 있도록 하여 데이터 지속성 및 성능 캐싱을 가능하게 하며 로그 파일을 회전하는 기능을 제공합니다.","es":"Habilita a los agentes a gestionar el estado persistente, la configuración y los directorios de caché en scripts de bash siguiendo la especificación de directorios base XDG, lo que permite la persistencia de datos y la caché de rendimiento con rotación de archivos de registro.","fr":"Permet aux agents de gérer l''état persistant, la configuration et les répertoires de cache dans les scripts bash suivant la spécification des répertoires de base XDG, permettant ainsi la persistance des données et la mise en cache des performances avec rotation des fichiers journaux.","de":"Ermöglicht es Agenten, persistente Zustände, Konfigurationen und Cache-Verzeichnisse in bash-Skripten zu verwalten, die der XDG-Base-Directory-Spezifikation folgen, wodurch Datenpersistenz und Leistungs-Caching mit Log-Datei-Rotation ermöglicht wird.","pt":"Habilita os agentes a gerenciar estado persistente, configuração e diretórios de cache em scripts bash seguindo a especificação XDG Base Directory, permitindo persistência de dados e cache de desempenho com rotação de arquivos de log.","ru":"Предоставляет агентам возможность управления постоянным состоянием, конфигурацией и кэш-каталогами в скриптах bash, следующих спецификации XDG Base Directory, обеспечивая сохранение данных и кэширование производительности с ротацией лог-файлов.","ar":"يمنح الوكلاء القدرة على إدارة الحالة المستدامة والتهيئة ومكاتب ذاكرة التخزين المؤقت في سكربتات باش تتبع مواصفة دليل قاعدة XDG ، وتمكين استمرار البيانات وتخزين ذاكرة التخزين المؤقت للأداء مع دوران ملفات السجل."},"useCases":{"en":["Automating script persistence for data between runs","Generating portable CLI tools with user preferences","Caching results for performance optimization"],"zh":["在运行之间为数据实现脚本持久性","生成具有用户首选项的便携式CLI工具","缓存结果以实现性能优化"],"ja":["実行間でデータのスクリプトの永続性を実現する","ユーザーの好みを備えたポータブルなCLIツールを生成する","パフォーマンス最適化のために結果をキャッシュする"],"ko":["실행 간에 데이터에 대한 스크립트 지속성을 구현하는 것","사용자 선호도를 갖춘 이식 가능한 CLI 도구를 생성하는 것","성능 최적화를 위해 결과를 캐시하는 것"],"es":["Automatizar la persistencia de scripts para datos entre ejecuciones","Generar herramientas de CLI portátiles con preferencias de usuario","Almacenar en caché resultados para la optimización del rendimiento"],"fr":["Automatiser la persistance des scripts pour les données entre les exécutions","Générer des outils CLI portables avec des préférences utilisateur","Mettre en cache les résultats pour l''optimisation des performances"],"de":["Automatisieren der Skript-Persistenz für Daten zwischen Ausführungen","Erzeugen portabler CLI-Tools mit Benutzervorlieben","Zwischenspeichern von Ergebnissen für die Leistungsoptimierung"],"pt":["Automatizar persistência de script para dados entre execuções","Gerar ferramentas CLI portáteis com preferências do usuário","Armazenar resultados para otimização de desempenho"],"ru":["Автоматизация сохранения скрипта для данных между запусками","Генерация переносных инструментов CLI с предпочтениями пользователя","Кэширование результатов для оптимизации производительности"],"ar":["تأتمتة استمرار السكربت للبيانات بين التشغيل","توليد أدوات CLI محمولة مع تفضيلات المستخدم","مخزنة النتائج لتحسين الأداء"]},"limitations":{"en":["Requires bash script compatibility","Intended for scripts needing state persistence, not one-time or stateless scripts"],"zh":["需要bash脚本兼容性","仅适用于需要状态持久性的脚本，不适用于一次性或无状态脚本"],"ja":["bashスクリプトの互換性が必要","状態の永続性が必要なスクリプトにのみ使用し、一時的なスクリプトやステートレススクリプトに使用しない"],"ko":["bash 스크립트 호환성이 필요함","상태 지속성이 필요한 스크립트에만 사용하며, 일회성 또는 상태가 없는 스크립트에는 사용하지 않음"],"es":["Requiere compatibilidad con scripts de bash","Diseñado para scripts que necesitan persistencia de estado, no para scripts de una sola vez o sin estado"],"fr":["Nécessite la compatibilité avec les scripts bash","Conçu pour les scripts nécessitant une persistance d''état, et non pour les scripts à usage unique ou sans état"],"de":["Benötigt Kompatibilität mit bash-Skripten","Dient für Skripte, die eine Zustandspersistenz benötigen, nicht für Skripte, die nur einmal ausgeführt werden oder zustandslos sind"],"pt":["Exige compatibilidade com script bash","Destina-se a scripts que necessitam de persistência de estado, não a scripts de uma vez ou sem estado"],"ru":["Требует совместимости со скриптом bash","Предназначен для скриптов, требующих сохранения состояния, а не для скриптов с одним запуском или без состояния"],"ar":["يتطلب التوافق مع سكربت باش","مصمم لسكربتات تحتاج إلى استمرار الحالة، وليس سكربتات مرة واحدة أو بدون حالة"]},"version":4},"contentHash":"8f7d8b1f282e83826f6fb54180381c3bfb5f821edee1c9ae5bc11c0396de2d08","qualityScore":64}');
