INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vamseeachanta/workspace-hub/state-directory-manager', 'state-directory-manager', 'vamseeachanta', 'workspace-hub', 'community', 'state-directory-manager vamseeachanta workspace-hub community state-directory-manager is a centralized management system for multiple GitHub repositories, enabling modular organization and persistent state management. It benefits developers working with bash scripts and requiring data persistence. State Directory Manager 是一个按 XDG 基础目录规范管理持久状态、配置和缓存目录的集中管理系统，适用于需要持久数据的 Bash 脚本 State Directory Manager は、AIエージェントによるモジュラーなディレクトリ管理を提供する集中管理システムです State Directory Manager는 Bash 스크립트의 모듈러 디렉토리 관리를 위한集中 관리 시스템입니다 State-directory-manager es un sistema de gestión centralizado para múltiples repositorios de GitHub con organización modular, ideal para persistir datos entre ejecuciones y almacenar preferencias de usuario State-directory-manager est un système de gestion centralisé pour plusieurs dépôts GitHub avec organisation modulaire, idéal pour persister des données entre exécutions et stocker les préférences utilisateur State-directory-manager ist ein zentrales Management-System für mehrere GitHub-Repositorys mit modularem Aufbau, ideal für die Persistenz von Daten zwischen Ausführungen und die Speicherung von Benutzervorlieben O state-directory-manager é um sistema de gerenciamento centralizado para repositórios GitHub, permitindo uma organização modular State-directory-manager — это централизованная система управления репозиториями GitHub с модульной организацией state-directory-manager هو نظام إدارة مركزي لمستودعات GitHub، مما يسمح بالتنظيم المودуляري how to use state-directory-manager state-directory-manager setup guide what is state-directory-manager state-directory-manager alternative state-directory-manager vs git state-directory-manager install bash script state management XDG Base Directory specification persistent state management State Directory Manager XDG 基础目录规范 Bash 脚本 持久状态管理 配置管理 缓存管理 AI 工具 集中管理系统 Manages persistent state, configuration, and cache directories in bash scripts Follows XDG Base Directory specification for modular organization Enables data persistence between script runs Supports storing user preferences and configuration Caches results for improved performance Manages log files with rotation for efficient logging state-directory-manager is a centralized management system following XDG Base Directory specification for managing persistent state, configuration, and cache directories in bash scripts.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('catlog22/Claude-Code-Workflow/team-lifecycle', 'community', 'catlog22', 'Claude-Code-Workflow', 'catlog22/Claude-Code-Workflow', 'team-lifecycle', 1331, 111, 64, '2026-02-25T02:23:09Z', '2026-02-26T08:27:28.009Z', 'a70cc9c77d0d73bf9f03aee6351d74e33ffcd83cec739090bad4349c731a3d1f', '{"id":"catlog22/Claude-Code-Workflow/team-lifecycle","name":"team-lifecycle","description":{"zh":"一种JSON驱动的多智能体开发框架，具有智能CLI编排和工作流自动化功能","ja":"JSON駆動のマルチエージェント開発フレームワークで、インテリジェントCLIオーケストレーションとワークフロー自動化を実現","ko":"JSON 기반의 멀티 에이전트 개발 프레임워크로 지능형 CLI 오케스트레이션과 워크플로우 자동화를 제공","es":"El marco de desarrollo multiagente es una plataforma JSON-driven con orquestación de CLI inteligente y arquitectura de contexto para automatizar flujos de trabajo","fr":"Le cadre de développement multi-agent est une plateforme JSON-driven avec une orchestration de CLI intelligente et une architecture de contexte pour automatiser les workflows","de":"Das Rahmenwerk für Multiagenten-Entwicklung ist eine JSON-driven-Plattform mit intelligenter CLI-Orchestrierung und Kontext-Architektur für die Automatisierung von Workflows","pt":"O team-lifecycle é um framework de desenvolvimento de multi-agente impulsionado por JSON, com orquestração CLI inteligente e arquitetura de contexto","ru":"Team-lifecycle - это JSON-ориентированный фреймворк для разработки многоагентных систем с интеллектуальной оркестрацией CLI и контекстно-ориентированной архитектурой","ar":"team-lifecycle هو إطار عمل متعدد الوكلاء مدفوع بواسطة JSON، مع تحكمًا ذكيًا في واجهة سطر الأوامر وهندسة معمارية لسياق","en":" JSON-driven multi-agent development framework with   intelligent CLI orchestration (Gemini/Qwen/Codex),   context-first architecture, and automated workflow   execution"},"seo":{"title":{"zh":"AI智能代理团队生命周期管理","ja":"AIエージェントのチームライフサイクル管理","ko":"AI 에이전트 팀 라이프사이클 관리","es":"Herramientas de Agentes de IA: Marco de Desarrollo Multia...","fr":"Outils d''Agents IA: Cadre de Développement Multi-Agent","de":"KI-Agenten-Tools: Rahmenwerk für Multiagenten-Entwicklung","pt":"Ferramentas de Agente de IA: Team-Lifecycle","ru":"ИИ Агенты: Team-Lifecycle","ar":"أدوات وكلاء الذكاء الاصطناعي: team-lifecycle","en":"team-lifecycle"},"description":{"zh":"一种JSON驱动的多智能体开发框架，具有智能CLI编排和工作流自动化功能","ja":"JSON駆動のマルチエージェント開発フレームワークで、インテリジェントCLIオーケストレーションとワークフロー自動化を実現","ko":"JSON 기반의 멀티 에이전트 개발 프레임워크로 지능형 CLI 오케스트레이션과 워크플로우 자동화를 제공","es":"El marco de desarrollo multiagente es una plataforma JSON-driven con orquestación de CLI inteligente y arquitectura de contexto para automatizar flujos de tr...","fr":"Le cadre de développement multi-agent est une plateforme JSON-driven avec une orchestration de CLI intelligente et une architecture de contexte pour automati...","de":"Das Rahmenwerk für Multiagenten-Entwicklung ist eine JSON-driven-Plattform mit intelligenter CLI-Orchestrierung und Kontext-Architektur für die Automatisieru...","pt":"O team-lifecycle é um framework de desenvolvimento de multi-agente impulsionado por JSON, com orquestração CLI inteligente e arquitetura de contexto","ru":"Team-lifecycle - это JSON-ориентированный фреймворк для разработки многоагентных систем с интеллектуальной оркестрацией CLI и контекстно-ориентированной архи...","ar":"team-lifecycle هو إطار عمل متعدد الوكلاء مدفوع بواسطة JSON، مع تحكمًا ذكيًا في واجهة سطر الأوامر وهندسة معمارية لسياق","en":" JSON-driven multi-agent development framework with   intelligent CLI orchestration (Gemini/Qwen/Codex),   context-first architecture, and automated workflow..."},"definition":{"en":" JSON-driven multi-agent development framework with   intelligent CLI orchestration (Gemini/Qwen/Codex),   context-first architecture, and automated workflow   execution"},"features":{"zh":["JSON驱动的多智能体开发框架","智能CLI编排","工作流自动化","上下文优先架构","Gemini/Qwen/Codex集成"],"ja":["JSON駆動のマルチエージェント開発フレームワーク","インテリジェントCLIオーケストレーション","ワークフロー自動化","コンテキ