INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('catlog22/Claude-Code-Workflow/team-lifecycle', 'team-lifecycle', 'catlog22', 'Claude-Code-Workflow', 'community', 'team-lifecycle catlog22 Claude-Code-Workflow community claude claude-code cli-tools codex context-management gemini-cli json-driven qwen-code task-orchestration workflow-automation 一种JSON驱动的多智能体开发框架，具有智能CLI编排和工作流自动化功能 JSON駆動のマルチエージェント開発フレームワークで、インテリジェントCLIオーケストレーションとワークフロー自動化を実現 JSON 기반의 멀티 에이전트 개발 프레임워크로 지능형 CLI 오케스트레이션과 워크플로우 자동화를 제공 El marco de desarrollo multiagente es una plataforma JSON-driven con orquestación de CLI inteligente y arquitectura de contexto para automatizar flujos de trabajo Le cadre de développement multi-agent est une plateforme JSON-driven avec une orchestration de CLI intelligente et une architecture de contexte pour automatiser les workflows Das Rahmenwerk für Multiagenten-Entwicklung ist eine JSON-driven-Plattform mit intelligenter CLI-Orchestrierung und Kontext-Architektur für die Automatisierung von Workflows O team-lifecycle é um framework de desenvolvimento de multi-agente impulsionado por JSON, com orquestração CLI inteligente e arquitetura de contexto Team-lifecycle - это JSON-ориентированный фреймворк для разработки многоагентных систем с интеллектуальной оркестрацией CLI и контекстно-ориентированной архитектурой team-lifecycle هو إطار عمل متعدد الوكلاء مدفوع بواسطة JSON، مع تحكمًا ذكيًا في واجهة سطر الأوامر وهندسة معمارية لسياق JSON-driven multi-agent development framework with intelligent CLI orchestration (Gemini/Qwen/Codex), context-first architecture, and automated workflow execution AI智能代理 团队生命周期管理 JSON驱动开发 智能CLI编排 工作流自动化 上下文优先架构 Gemini/Qwen/Codex 如何使用AI智能代理 AI智能代理的优点 JSON-driven multi-agent development framework with intelligent CLI orchestration (Gemini/Qwen/Codex), context-first architecture, and automated workflow execution');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anthropics/skills/doc-coauthoring', 'official', 'anthropics', 'skills', 'anthropics/skills', 'doc-coauthoring', 85097, 8974, 64, '2026-03-06T03:11:21Z', '2026-03-06T03:15:58.949Z', '2e47d78846faeea4a56e9809c52700087a15a2155a3f293a3efbaded81398ef4', '{"id":"anthropics/skills/doc-coauthoring","name":"doc-coauthoring","description":{"en":"The doc-coauthoring skill is an AI agent workflow that guides developers through a structured, three-stage process for co-authoring technical documentation. It helps technical writers and engineering teams efficiently create specs, proposals, and decision documents.","zh":"doc-coauthoring AI代理技能提供结构化三阶段工作流，指导用户高效完成技术文档、提案、设计文档和决策文档的协作创作。通过上下文转移、迭代优化和读者验证确保文档质量。","ja":"doc-coauthoring AIエージェントスキルは、技術文書、提案書、設計ドキュメントの共同作成を支援する構造化された3段階ワークフローを提供。コンテキスト転送、反復改良、読者検証を通じて品質を確保。","ko":"doc-coauthoring AI 에이전트 스킬은 기술 문서, 제안서, 설계 문서의 협업 생성을 위한 구조화된 3단계 워크플로우를 제공. 컨텍스트 이전, 반복 개선, 독자 검증을 통한 품질 보장.","pt":"O fluxo de coautoria de documentos é uma habilidade que fornece uma estrutura para a criação colaborativa de documentos. Ele ajuda a transferir contexto, refinar conteúdo e testar a documentação.","ru":"Поток совместного создания документации - это навык, который предоставляет структуру для совместного создания документов. Он помогает передавать контекст, совершенствовать содержание и тестировать документацию.","ar":"Flux لco-authoring الوثائق هو مهارة توفر هيكلاً لإنشاء الوثائق بالتعاون. يساعد في نقل السياق وتنقيح المحتوى واختبار الوثائق"},"owner":"anthropics","repo":"skills","repoPath":"anthropics/skills","stars":85097,"forks":8974,"updatedAt":"2026-03-06T03:11:21Z","topics":["agent-skills"],"skillMd":{"name":"doc-coauthoring","description":"Guide users through a structured workflow for co-authoring documentation. Use when user wants to write documentation, proposals, technical specs, decision docs, or similar structured content. This workflow helps users efficiently transfer context, refine content through iteration, and verify the doc works for readers. Trigger when user mentions writing docs, creating proposals, drafting specs, or similar documentation tasks.","bodyPreview":"# Doc Co-Authoring Workflow\n\nThis skill provides a structured workflow for guiding users through collaborative document creation. Act as an active guide, walking users through three stages: Context Gathering, Refinement & Structure, and Reader Testing.\n\n## When to Offer This Workflow\n\n**Trigger conditions:**\n- User mentions writing documentation: \"write a doc\", \"draft a proposal\", \"create a spec\", \"write up\"\n- User mentions specific doc types: \"PRD\", \"design doc\", \"decision doc\", \"RFC\"\n- User se","body":"# Doc Co-Authoring Workflow\n\nThis skill provides a structured workflow for guiding users through collaborative document creation. Act as an active guide, walking users through three stages: Context Gathering, Refinement & Structure, and Reader Testing.\n\n## When to Offer This Workflow\n\n**Trigger conditions:**\n- User mentions writing documentation: \"write a doc\", \"draft a proposal\", \"create a spec\", \"write up\"\n- User mentions specific doc types: \"PRD\", \"design doc\", \"decision doc\", \"RFC\"\n- User seems to be starting a substantial writing task\n\n**Initial offer:**\nOffer the user a structured workflow for co-authoring the document. Explain the three stages:\n\n1. **Context Gathering**: User provides all relevant context while Claude asks clarifying questions\n2. **Refinement & Structure**: Iteratively build each section through brainstorming and editing\n3. **Reader Testing**: Test the doc with a fresh Claude (no context) to catch blind spots before others read it\n\nExplain that this approach helps ensure the doc works well when others read it (including when they paste it into Claude). Ask if they want to try this workflow or prefer to work freeform.\n\nIf user declines, work freeform. If user accepts, proceed to Stage 1.\n\n## Stage 1: Context Gathering\n\n**Goal:** Close the gap between what the user knows and what Claude knows, enabling smart guidance later.\n\n### Initial Questions\n\nStart by asking the user for meta-context about the document:\n\n1. What type of document is this? (e.g., technical spec, decision doc, proposal)\n2. Who''s the primary audience?\n3. What''s the desired impact when someone reads this?\n4. Is there a template or specific format to follow?\n5. Any other constraints or context to know?\n\nInform them they can answer in shorthand or dump information however works best for them.\n\n**If user provides a template or mentions a doc type:**\n- Ask if they have a template document to share\n- If they provide a link to a shared document, use the appropriate integration to fetch it\n- If they provide a file, read it\n\n**If user mentions editing an existing shared document:**\n- Use the appropriate integration to read the current state\n- Check for images without alt-text\n- If images exist without alt-text, explain that when others use Claude to understand the doc, Claude won''t be able to see them. Ask if they want alt-text generated. If so, request they paste each image into chat for descriptive alt-text generation.\n\n### Info Dumping\n\nOnce initial questions are answered, encourage the user to dump all the context they have. Request information such as:\n- Background on the project/problem\n- Related team discussions or shared documents\n- Why alternative solutions aren''t being used\n- Organizational context (team dynamics, past incidents, politics)\n- Timeline pressures or constraints\n- Technical architecture or dependencies\n- Stakeholder concerns\n\nAdvise them not to worry about organizing it - just get it all out. Offer multiple ways to provide context:\n- Info dump stream-of-consciousness\n- Point to team channels or threads to read\n- Link to shared documents\n\n**If integrations are available** (e.g., Slack, Teams, Google Drive, SharePoint, or other MCP servers), mention that these can be used to pull in context directly.\n\n**If no integrations are detected and in Claude.ai or Claude app:** Suggest they can enable connectors in their Claude settings to allow pulling context from messaging apps and document storage directly.\n\nInform them clarifying questions will be asked once they''ve done their initial dump.\n\n**During context gathering:**\n\n- If user mentions team channels or shared documents:\n  - If integrations available: Inform them the content will be read now, then use the appropriate integration\n  - If integrations not available: Explain lack of access. Suggest they enable connectors in Claude settings, or paste the relevant content directly.\n\n- If user mentions entities/projects that are unknown:\n  - Ask if connected tools should be searched to learn more\n  - Wait for user confirmation before searching\n\n- As user provides context, track what''s being learned and what''s still unclear\n\n**Asking clarifying questions:**\n\nWhen user signals they''ve done their initial dump (or after substantial context provided), ask clarifying questions to ensure understanding:\n\nGenerate 5-10 numbered questions based on gaps in the context.\n\nInform them they can use shorthand to answer (e.g., \"1: yes, 2: see #channel, 3: no because backwards compat\"), link to more docs, point to channels to read, or just keep info-dumping. Whatever''s most efficient for them.\n\n**Exit condition:**\nSufficient context has been gathered when questions show understanding - when edge cases and trade-offs can be asked about without needing basics explained.\n\n**Transition:**\nAsk if there''s any more context they want to provide at this stage, or if it''s time to move on to drafting the document.\n\nIf user wants to add more, let them. When ready, proceed to Stage 2.\n\n## Stage 2: Refinement & Structure\n\n**Goal:** Build the document section by section through brainstorming, curation, and iterative refinement.\n\n**Instructions to user:**\nExplain that the document will be built section by section. For each section:\n1. Clarifying questions will be asked about what to include\n2. 5-20 options will be brainstormed\n3. User will indicate what to keep/remove/combine\n4. The section will be drafted\n5. It will be refined through surgical edits\n\nStart with whichever section has the most unknowns (usually the core decision/proposal), then work through the rest.\n\n**Section ordering:**\n\nIf the document structure is clear:\nAsk which section they''d like to start with.\n\nSuggest starting with whichever section has the most unknowns. For decision docs, that''s usually the core proposal. For specs, it''s typically the technical approach. Summary sections are best left for last.\n\nIf user doesn''t know what sections they need:\nBased on the type of document and template, suggest 3-5 sections appropriate for the doc type.\n\nAsk if this structure works, or if they want to adjust it.\n\n**Once structure is agreed:**\n\nCreate the initial document structure with placeholder text for all sections.\n\n**If access to artifacts is available:**\nUse `create_file` to create an artifact. This gives both Claude and the user a scaffold to work from.\n\nInform them that the initial structure with placeholders for all sections will be created.\n\nCreate artifact with all section headers and brief placeholder text like \"[To be written]\" or \"[Content here]\".\n\nProvide the scaffold link and indicate it''s time to fill in each section.\n\n**If no access to artifacts:**\nCreate a markdown file in the working directory. Name it appropriately (e.g., `decision-doc.md`, `technical-spec.md`).\n\nInform them that the initial structure with placeholders for all sections will be created.\n\nCreate file with all section headers and placeholder text.\n\nConfirm the filename has been created and indicate it''s time to fill in each section.\n\n**For each section:**\n\n### Step 1: Clarifying Questions\n\nAnnounce work will begin on the [SECTION NAME] section. Ask 5-10 clarifying questions about what should be included:\n\nGenerate 5-10 specific questions based on context and section purpose.\n\nInform them they can answer in shorthand or just indicate what''s important to cover.\n\n### Step 2: Brainstorming\n\nFor the [SECTION NAME] section, brainstorm [5-20] things that might be included, depending on the section''s complexity. Look for:\n- Context shared that might have been forgotten\n- Angles or considerations not yet mentioned\n\nGenerate 5-20 numbered options based on section complexity. At the end, offer to brainstorm more if they want additional options.\n\n### Step 3: Curation\n\nAsk which points should be kept, removed, or combined. Request brief justifications to help learn priorities for the next sections.\n\nProvide examples:\n- \"Keep 1,4,7,9\"\n- \"Remove 3 (duplicates 1)\"\n- \"Remove 6 (audience already knows this)\"\n- \"Combine 11 and 12\"\n\n**If user gives freeform feedback** (e.g., \"looks good\" or \"I like most of it but...\") instead of numbered selections, extract their preferences and proceed. Parse what they want kept/removed/changed and apply it.\n\n### Step 4: Gap Check\n\nBased on what they''ve selected, ask if there''s anything important missing for the [SECTION NAME] section.\n\n### Step 5: Drafting\n\nUse `str_replace` to replace the placeholder text for this section with the actual drafted content.\n\nAnnounce the [SECTION NAME] section will be drafted now based on what they''ve selected.\n\n**If using artifacts:**\nAfter drafting, provide a link to the artifact.\n\nAsk them to read through it and indicate what to change. Note that being specific helps learning for the next sections.\n\n**If using a file (no artifacts):**\nAfter drafting, confirm completion.\n\nInform them the [SECTION NAME] section has been drafted in [filename]. Ask them to read through it and indicate what to change. Note that being specific helps learning for the next sections.\n\n**Key instruction for user (include when drafting the first section):**\nProvide a note: Instead of editing the doc directly, ask them to indicate what to change. This helps learning of their style for future sections. For example: \"Remove the X bullet - already covered by Y\" or \"Make the third paragraph more concise\".\n\n### Step 6: Iterative Refinement\n\nAs user provides feedback:\n- Use `str_replace` to make edits (never reprint the whole doc)\n- **If using artifacts:** Provide link to artifact after each edit\n- **If using files:** Just confirm edits are complete\n- If user edits doc directly and asks to read it: mentally note the changes they made and keep them in mind for future sections (this shows their preferences)\n\n**Continue iterating** until user is satisfied with the section.\n\n### Quality Checking\n\nAfter 3 consecutive iterations with no substantial changes, ask if anything can be removed without losing important information.\n\nWhen section is done, confirm [SECTION NAME] is complete. Ask if ready to move to the next section.\n\n**Repeat for all sections.**\n\n### Near Completion\n\nAs approaching completion (80%+ of sections done), announce intention to re-read the entire document and check for:\n- Flow and consistency across sections\n- Redundancy or contradictions\n- Anything that feels like \"slop\" or generic filler\n- Whether every sentence carries weight\n\nRead entire document and provide feedback.\n\n**When all sections are drafted and refined:**\nAnnounce all sections are drafted. Indicate intention to review the complete document one more time.\n\nReview for overall coherence, flow, completeness.\n\nProvide any final suggestions.\n\nAsk if ready to move to Reader Testing, or if they want to refine anything else.\n\n## Stage 3: Reader Testing\n\n**Goal:** Test the document with a fresh Claude (no context bleed) to verify it works for readers.\n\n**Instructions to user:**\nExplain that testing will now occur to see if the document actually works for readers. This catches blind spots - things that make sense to the authors but might confuse others.\n\n### Testing Approach\n\n**If access to sub-agents is available (e.g., in Claude Code):**\n\nPerform the testing directly without user involvement.\n\n### Step 1: Predict Reader Questions\n\nAnnounce intention to predict what questions readers might ask when trying to discover this document.\n\nGenerate 5-10 questions that readers would realistically ask.\n\n### Step 2: Test with Sub-Agent\n\nAnnounce that these questions will be tested with a fresh Claude instance (no context from this conversation).\n\nFor each question, invoke a sub-agent with just the document content and the question.\n\nSummarize what Reader Claude got right/wrong for each question.\n\n### Step 3: Run Additional Checks\n\nAnnounce additional checks will be performed.\n\nInvoke sub-agent to check for ambiguity, false assumptions, contradictions.\n\nSummarize any issues found.\n\n### Step 4: Report and Fix\n\nIf issues found:\nReport that Reader Claude struggled with specific issues.\n\nList the specific issues.\n\nIndicate intention to fix these gaps.\n\nLoop back to refinement for problematic sections.\n\n---\n\n**If no access to sub-agents (e.g., claude.ai web interface):**\n\nThe user will need to do the testing manually.\n\n### Step 1: Predict Reader Questions\n\nAsk what questions people might ask when trying to discover this document. What would they type into Claude.ai?\n\nGenerate 5-10 questions that readers would realistically ask.\n\n### Step 2: Setup Testing\n\nProvide testing instructions:\n1. Open a fresh Claude conversation: https://claude.ai\n2. Paste or share the document content (if using a shared doc platform with connectors enabled, provide the link)\n3. Ask Reader Claude the generated questions\n\nFor each question, instruct Reader Claude to provide:\n- The answer\n- Whether anything was ambiguous or unclear\n- What knowledge/context the doc assumes is already known\n\nCheck if Reader Claude gives correct answers or misinterprets anything.\n\n### Step 3: Additional Checks\n\nAlso ask Reader Claude:\n- \"What in this doc might be ambiguous or unclear to readers?\"\n- \"What knowledge or context does this doc assume readers already have?\"\n- \"Are there any internal contradictions or inconsistencies?\"\n\n### Step 4: Iterate Based on Results\n\nAsk what Reader Claude got wrong or struggled with. Indicate intention to fix those gaps.\n\nLoop back to refinement for any problematic sections.\n\n---\n\n### Exit Condition (Both Approaches)\n\nWhen Reader Claude consistently answers questions correctly and doesn''t surface new gaps or ambiguities, the doc is ready.\n\n## Final Review\n\nWhen Reader Testing passes:\nAnnounce the doc has passed Reader Claude testing. Before completion:\n\n1. Recommend they do a final read-through themselves - they own this document and are responsible for its quality\n2. Suggest double-checking any facts, links, or technical details\n3. Ask them to verify it achieves the impact they wanted\n\nAsk if they want one more review, or if the work is done.\n\n**If user wants final review, provide it. Otherwise:**\nAnnounce document completion. Provide a few final tips:\n- Consider linking this conversation in an appendix so readers can see how the doc was developed\n- Use appendices to provide depth without bloating the main doc\n- Update the doc as feedback is received from real readers\n\n## Tips for Effective Guidance\n\n**Tone:**\n- Be direct and procedural\n- Explain rationale briefly when it affects user behavior\n- Don''t try to \"sell\" the approach - just execute it\n\n**Handling Deviations:**\n- If user wants to skip a stage: Ask if they want to skip this and write freeform\n- If user seems frustrated: Acknowledge this is taking longer than expected. Suggest ways to move faster\n- Always give user agency to adjust the process\n\n**Context Management:**\n- Throughout, if context is missing on something mentioned, proactively ask\n- Don''t let gaps accumulate - address them as they come up\n\n**Artifact Management:**\n- Use `create_file` for drafting full sections\n- Use `str_replace` for all edits\n- Provide artifact link after every change\n- Never use artifacts for brainstorming lists - that''s just conversation\n\n**Quality over Speed:**\n- Don''t rush through stages\n- Each iteration should make meaningful improvements\n- The goal is a document that actually works for readers\n"},"category":"official","lastSynced":"2026-03-06T03:15:58.949Z","seo":{"title":{"en":"doc-coauthoring: Structured Documentation Workflow | AI A...","zh":"文档协同写作AI代理设置指南：结构化技术文档工作流","ja":"ドキュメント共作AIエージェントのベストプラクティス：技術文書作成ワークフロー","ko":"문서 공동 작성 AI 에이전트 설정 가이드: 구조적 기술 문서 워크플로우","pt":"Guia de Configuração do Fluxo de Coautoria de Documentos ...","ru":"Настройка Работы с ИИ Агентами для Совместного Создания Д...","ar":"دليل إعداد Flux لco-authoring الوثائق مع أدوات الذكاء الا..."},"description":{"en":"Accelerate technical writing with the doc-coauthoring AI agent skill. This structured workflow guides you through context gathering, iterative refinement, an...","zh":"AI代理的文档协同写作技能提供三阶段结构化工作流：上下文收集、内容迭代优化和读者测试验证。适用于技术文档、提案、设计文档和RFC的协作创作。","ja":"AIエージェントのドキュメント共作スキルは、コンテキスト収集、反復的なコンテンツ改良、読者テストの3段階ワークフローを提供。技術文書、提案書、設計ドキュメントの共同作成に最適。","ko":"AI 에이전트의 문서 공동 작성 스킬은 컨텍스트 수집, 반복적 콘텐츠 개선, 독자 테스트의 3단계 워크플로우를 제공. 기술 문서, 제안서, 설계 문서 협업에 최적화.","pt":"Aprenda a usar o fluxo de coautoria de documentos para criar documentos eficazes com a ajuda de ferramentas de IA. Melhore a colaboração e a qualidade da doc...","ru":"Узнайте, как использовать поток совместного создания документации с помощью ИИ Агентов, чтобы повысить эффективность сотрудничества и качество документов.","ar":"تعرف على كيفية استخدام Flux لco-authoring الوثائق مع أدوات الذكاء الاصطناعي لتحسين التعاون وجودة الوثائق"},"definition":{"en":"doc-coauthoring is an AI agent skill that provides a structured workflow for collaborative document creation. It acts as an active guide through three specific stages: Context Gathering, Refinement & Structure, and Reader Testing to produce high-quality technical content.","zh":"doc-coauthoring是一种AI代理技能，专门指导用户通过结构化三阶段工作流（上下文收集、迭代优化、读者测试）协作创作技术文档、提案、设计文档和决策文档。","ja":"doc-coauthoringは、構造化された3段階ワークフロー（コンテキスト収集、反復改良、読者テスト）を通じて技術文書、提案書、設計ドキュメントの共同作成を導くAIエージェントスキルです。","ko":"doc-coauthoring는 구조화된 3단계 워크플로우(컨텍스트 수집, 반복 개선, 독자 테스트)를 통해 기술 문서, 제안서, 설계 문서의 공동 생성을 안내하는 AI 에이전트 스킬입니다.","pt":"O que é fluxo de coautoria de documentos? É uma habilidade que fornece uma estrutura para a criação colaborativa de documentos.","ru":"Что такое поток совместного создания документации? Это навык, который предоставляет структуру для совместного создания документов.","ar":"ما هو Flux لco-authoring الوثائق؟ هو مهارة توفر هيكلاً لإنشاء الوثائق بالتعاون"},"features":{"en":["Guides users through a structured three-stage workflow: Context Gathering, Refinement & Structure, and Reader Testing","Triggers on mentions of specific documentation tasks like ''write a doc'' or ''draft a proposal''","Activates on references to specific doc types including PRDs, design docs, decision docs, and RFCs","Designed for collaborative document creation and efficient context transfer","Helps refine content through iterative processes","Verifies documentation effectiveness for target readers"],"zh":["三阶段结构化工作流：上下文收集→迭代优化→读者测试","支持PRD、设计文档、决策文档、RFC等特定文档类型","自动化上下文转移机制，减少信息丢失","迭代式内容优化流程，支持多轮修订","读者测试验证功能，确保文档可读性","响应\"write doc\"、\"draft proposal\"等触发指令"],"ja":["3段階構造化ワークフロー：コンテキスト収集→反復改良→読者テスト","PRD、設計ドキュメント、意思決定ドキュメント、RFC対応","自動コンテキスト転送メカニズムによる情報損失の軽減","多段階修订をサポートする反復的なコンテンツ最適化","文档の可読性を確保する読者テスト検証機能","\"write doc\"、\"draft proposal\"などのトリガー指令に対応"],"ko":["3단계 구조화 워크플로우: 컨텍스트 수집→반복 개선→독자 테스트","PRD, 설계 문서, 결정 문서, RFC 지원","자동 컨텍스트 이전 메커니즘으로 정보 손실 감소","다단계 수정 지원 반복적 콘텐츠 최적화","문서 가독성 보장을 위한 독자 테스트 검증 기능","\"write doc\", \"draft proposal\" 등 트리거 명령어 응답"],"pt":["Estrutura para criação colaborativa de documentos","Transferência de contexto para melhorar a colaboração","Refinamento de conteúdo através de iterações","Teste de leitura para garantir a qualidade da documentação","Integração com ferramentas de IA para automação de tarefas","Suporte a vários tipos de documentos, incluindo PRD, design doc e decision doc"],"ru":["Структура для совместного создания документов","Передача контекста для улучшения сотрудничества","Совершенствование содержания через итерации","Тестирование чтения для обеспечения качества документации","Интеграция с ИИ Агентами для автоматизации задач","Поддержка нескольких типов документов, включая PRD, дизайн-док и решение-док"],"ar":["هيكل لإنشاء الوثائق بالتعاون","نقل السياق لتحسين التعاون","تنقيح المحتوى من خلال التكرارات","اختبار القراءة لضمان جودة الوثائق","التكامل مع أدوات الذكاء الاصطناعي لل автоматизация المهام","دعم أنواع متعددة من الوثائق، بما في ذلك PRD وتصميم الوثائق ووثائق القرار"]},"keywords":{"en":["what is doc-coauthoring","how to use doc-coauthoring workflow","doc-coauthoring vs manual drafting","doc-coauthoring setup guide","doc-coauthoring for technical specs","doc-coauthoring for RFCs","AI agent for documentation","structured documentation workflow"],"zh":["文档协同写作AI代理","技术文档协作工作流","AI代理文档创作","结构化文档编写","PRD编写AI工具","设计文档协作","决策文档AI辅助","RFC文档自动化","上下文转移技术","读者测试验证"],"ja":["ドキュメント共作AIエージェント","技術文書協働ワークフロー","AIエージェント文档作成","構造化文档執筆","PRD作成AIツール","設計ドキュメント協業","意思決定文档AI支援","RFC文档自動化","コンテキスト転送技術","読者テスト検証"],"ko":["문서 공동 작성 AI 에이전트","기술 문서 협업 워크플로우","AI 에이전트 문서 생성","구조화 문서 작성","PRD 작성 AI 도구","설계 문서 협업","결정 문서 AI 지원","RFC 문서 자동화","컨텍스트 이전 기술","독자 테스트 검증"],"pt":["coautoria de documentos","ferramentas de IA para documentação","fluxo de trabalho de documentação","criação colaborativa de documentos","transferência de contexto","refinamento de conteúdo","teste de leitura","PRD","design doc","decision doc"],"ru":["совместное создание документации","ИИ Агенты для документации","поток работы документации","совместное создание документов","передача контекста","совершенствование содержания","тестирование чтения","PRD","дизайн-док","решение-док"],"ar":["co-authoring الوثائق","أدوات الذكاء الاصطناعي للوثائق","Flux لco-authoring الوثائق","إنشاء الوثائق بالتعاون","نقل السياق","تنقيح المحتوى","اختبار القراءة","PRD","تصميم الوثائق","وثائق القرار"]}},"agentAnalysis":{"suitability":{"en":"Essential for Documentation Agents guiding users through structured content creation workflows.","zh":"对于指导用户完成结构化内容创建工作流程的文档代理（Documentation Agents）至关重要。","ja":"構造化されたコンテンツ作成ワークフローをユーザーに案内するドキュメンテーションエージェント（Documentation Agents）に不可欠です。","ko":"구조화된 콘텐츠 생성 워크플로우를 통해 사용자를 안내하는 문서화 에이전트(Documentation Agents)에 필수적입니다.","es":"Esencial para agentes de documentación que guían a los usuarios a través de flujos de trabajo estructurados de creación de contenido.","fr":"Essentiel pour les agents de documentation guidant les utilisateurs à travers des flux de travail structurés de création de contenu.","de":"Essenziell für Dokumentations-Agents, die Benutzer durch strukturierte Workflows zur Erstellung von Inhalten führen.","pt":"Essencial para Agentes de Documentação que orientam os utilizadores através de fluxos de trabalho estruturados de criação de conteúdo.","ru":"Необходим для Агентов Документации, которые проводят пользователей через структурированные рабочие процессы создания контента.","ar":"أساسي لوكلاء التوثيق الذين يوجهون المستخدمين خلال سير عمل منظمة لإنشاء المحتوى."},"recommendation":{"en":"Enables agents to facilitate comprehensive document co-authoring through context gathering, iterative refinement, and reader testing phases. Provides structured frameworks for technical specs, proposals, decision docs, and PRDs with verification mechanisms.","zh":"使代理能够通过上下文收集、迭代优化和读者测试阶段，促进全面的文档共同创作。为技术规格、提案、决策文档和PRD提供带有验证机制的结构化框架。","ja":"コンテキスト収集、反復的な改良、およびリーダーテスト段階を通じて、エージェントが包括的なドキュメントの共同作成を促進できるようにします。検証メカニズムを備えた技術仕様、提案、意思決定文書、およびPRDのための構造化されたフレームワークを提供します。","ko":"에이전트가 컨텍스트 수집, 반복적 개선 및 독자 테스트 단계를 통해 포괄적인 문서 공동 작성을 용이하게 할 수 있도록 합니다. 검증 메커니즘을 갖춘 기술 사양, 제안서, 결정 문서 및 PRD를 위한 구조화된 프레임워크를 제공합니다.","es":"Permite a los agentes facilitar la coautoría integral de documentos a través de fases de recopilación de contexto, refinamiento iterativo y pruebas con lectores. Proporciona marcos estructurados para especificaciones técnicas, propuestas, documentos de decisión y PRDs con mecanismos de verificación.","fr":"Permet aux agents de faciliter la co-rédaction complète de documents grâce à des phases de collecte de contexte, de raffinement itératif et de tests avec les lecteurs. Fournit des cadres structurés pour les spécifications techniques, les propositions, les documents de décision et les PRD avec des mécanismes de vérification.","de":"Ermöglicht es Agents, eine umfassende Co-Autorenschaft von Dokumenten durch Kontexterfassung, iteratives Verfeinern und Lesertestphasen zu erleichtern. Bietet strukturierte Frameworks für technische Spezifikationen, Vorschläge, Entscheidungsdokumente und PRDs mit Verifizierungsmechanismen.","pt":"Permite que os agentes facilitem a coautoria abrangente de documentos através das fases de recolha de contexto, refinamento iterativo e teste do leitor. Fornece estruturas estruturadas para especificações técnicas, propostas, documentos de decisão e PRDs com mecanismos de verificação.","ru":"Позволяет агентам обеспечивать всестороннее совместное создание документов посредством сбора контекста, итеративного уточнения и этапов тестирования читателем. Предоставляет структурированные фреймворки для технических спецификаций, предложений, документов о решениях и PRD с механизмами проверки.","ar":"يمكن الوكلاء من تسهيل المشاركة الشاملة في كتابة المستندات من خلال مراحل جمع السياق، التنقيح التكراري، واختبار القارئ. يوفر أطرًا منظمة للمواصفات التقنية، المقترحات، وثائق القرار، ومستندات متطلبات المنتج (PRDs) مع آليات التحقق."},"useCases":{"en":["Drafting technical specifications with iterative feedback","Creating structured decision documentation (RFCs, design docs)","Developing product requirements documents (PRDs) with stakeholder input","Refining proposal documents through systematic iteration"],"zh":["通过迭代反馈起草技术规格","创建结构化的决策文档（RFC、设计文档）","通过利益相关者输入制定产品需求文档（PRD）","通过系统迭代优化提案文档"],"ja":["反復的なフィードバックによる技術仕様の起草","構造化された意思決定文書（RFC、設計文書）の作成","ステークホルダーの入力による製品要求文書（PRD）の開発","体系的な反復を通じた提案文書の改良"],"ko":["반복적 피드백을 통한 기술 사양 초안 작성","구조화된 결정 문서(RFC, 디자인 문서) 생성","이해관계자 입력을 통한 제품 요구 사항 문서(PRD) 개발","체계적인 반복을 통한 제안 문서 개선"],"es":["Redacción de especificaciones técnicas con retroalimentación iterativa","Creación de documentación de decisiones estructurada (RFCs, documentos de diseño)","Desarrollo de documentos de requisitos de producto (PRDs) con aportes de las partes interesadas","Refinamiento de documentos de propuesta mediante iteración sistemática"],"fr":["Rédaction de spécifications techniques avec retours d''information itératifs","Création d''une documentation de décision structurée (RFCs, documents de conception)","Développement de documents d''exigences produit (PRDs) avec l''apport des parties prenantes","Raffinement de documents de proposition par itération systématique"],"de":["Erstellung technischer Spezifikationen mit iterativem Feedback","Erstellen strukturierter Entscheidungsdokumentation (RFCs, Design-Dokumente)","Entwicklung von Produktanforderungsdokumenten (PRDs) mit Stakeholder-Input","Verfeinerung von Vorschlagsdokumenten durch systematische Iteration"],"pt":["Elaboração de especificações técnicas com feedback iterativo","Criação de documentação de decisão estruturada (RFCs, documentos de design)","Desenvolvimento de documentos de requisitos do produto (PRDs) com contribuição das partes interessadas","Refinamento de documentos de proposta através de iteração sistemática"],"ru":["Составление технических спецификаций с итеративной обратной связью","Создание структурированной документации по решениям (RFC, дизайн-документы)","Разработка документов требований к продукту (PRD) с участием заинтересованных сторон","Уточнение документов предложений посредством систематической итерации"],"ar":["صياغة المواصفات التقنية مع ملاحظات تكرارية","إنشاء وثائق قرار منظمة (RFCs، وثائق التصميم)","تطوير مستندات متطلبات المنتج (PRDs) مع مدخلات أصحاب المصلحة","تنقيح وثائق المقترحات من خلال التكرار المنهجي"]},"limitations":{"en":["Requires user engagement for context transfer","Depends on user-provided content for refinement","Reader testing phase requires additional input validation"],"zh":["需要用户参与以进行上下文传递","依赖用户提供的内容进行优化","读者测试阶段需要额外的输入验证"],"ja":["コンテキスト転送にはユーザーの関与が必要","改良にはユーザーが提供するコンテンツに依存","リーダーテスト段階では追加の入力検証が必要"],"ko":["컨텍스트 전달을 위한 사용자 참여 필요","개선을 위해 사용자가 제공한 콘텐츠에 의존","독자 테스트 단계에는 추가 입력 검증 필요"],"es":["Requiere la participación del usuario para la transferencia de contexto","Depende del contenido proporcionado por el usuario para el refinamiento","La fase de prueba con lectores requiere validación de entrada adicional"],"fr":["Nécessite l''engagement de l''utilisateur pour le transfert de contexte","Dépend du contenu fourni par l''utilisateur pour le raffinement","La phase de test avec les lecteurs nécessite une validation d''entrée supplémentaire"],"de":["Erfordert Benutzerbeteiligung für den Kontexttransfer","Ist von benutzerbereitgestellten Inhalten für die Verfeinerung abhängig","Die Lesertestphase erfordert eine zusätzliche Eingabevalidierung"],"pt":["Requer envolvimento do utilizador para transferência de contexto","Depende do conteúdo fornecido pelo utilizador para refinamento","A fase de teste do leitor requer validação adicional de entrada"],"ru":["Требует вовлечения пользователя для передачи контекста","Зависит от предоставленного пользователем контента для уточнения","Этап тестирования читателем требует дополнительной проверки ввода"],"ar":["يتطلب مشاركة المستخدم لنقل السياق","يعتمد على المحتوى المقدم من المستخدم للتنقيح","مرحلة اختبار القارئ تتطلب التحقق الإضافي من المدخلات"]},"version":4},"contentHash":"2e47d78846faeea4a56e9809c52700087a15a2155a3f293a3efbaded81398ef4","repoEtag":"W/\"7edb6fc0761f3427176a5845d10a3b3b8776acf53d512a10f8fa720076c3c761\"","qualityScore":64}');
