INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('anthropics/skills/doc-coauthoring', 'doc-coauthoring', 'anthropics', 'skills', 'official', 'doc-coauthoring anthropics skills official agent-skills The doc-coauthoring skill is an AI agent workflow that guides developers through a structured, three-stage process for co-authoring technical documentation. It helps technical writers and engineering teams efficiently create specs, proposals, and decision documents. doc-coauthoring AI代理技能提供结构化三阶段工作流，指导用户高效完成技术文档、提案、设计文档和决策文档的协作创作。通过上下文转移、迭代优化和读者验证确保文档质量。 doc-coauthoring AIエージェントスキルは、技術文書、提案書、設計ドキュメントの共同作成を支援する構造化された3段階ワークフローを提供。コンテキスト転送、反復改良、読者検証を通じて品質を確保。 doc-coauthoring AI 에이전트 스킬은 기술 문서, 제안서, 설계 문서의 협업 생성을 위한 구조화된 3단계 워크플로우를 제공. 컨텍스트 이전, 반복 개선, 독자 검증을 통한 품질 보장. O fluxo de coautoria de documentos é uma habilidade que fornece uma estrutura para a criação colaborativa de documentos. Ele ajuda a transferir contexto, refinar conteúdo e testar a documentação. Поток совместного создания документации - это навык, который предоставляет структуру для совместного создания документов. Он помогает передавать контекст, совершенствовать содержание и тестировать документацию. Flux لco-authoring الوثائق هو مهارة توفر هيكلاً لإنشاء الوثائق بالتعاون. يساعد في نقل السياق وتنقيح المحتوى واختبار الوثائق what is doc-coauthoring how to use doc-coauthoring workflow doc-coauthoring vs manual drafting doc-coauthoring setup guide doc-coauthoring for technical specs doc-coauthoring for RFCs AI agent for documentation structured documentation workflow 文档协同写作AI代理 技术文档协作工作流 AI代理文档创作 结构化文档编写 PRD编写AI工具 设计文档协作 决策文档AI辅助 RFC文档自动化 上下文转移技术 读者测试验证 Guides users through a structured three-stage workflow: Context Gathering, Refinement & Structure, and Reader Testing Triggers on mentions of specific documentation tasks like ''write a doc'' or ''draft a proposal'' Activates on references to specific doc types including PRDs, design docs, decision docs, and RFCs Designed for collaborative document creation and efficient context transfer Helps refine content through iterative processes Verifies documentation effectiveness for target readers doc-coauthoring is an AI agent skill that provides a structured workflow for collaborative document creation. It acts as an active guide through three specific stages: Context Gathering, Refinement & Structure, and Reader Testing to produce high-quality technical content.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anthropics/skills/frontend-design', 'official', 'anthropics', 'skills', 'anthropics/skills', 'frontend-design', 85097, 8974, 64, '2026-03-06T03:11:21Z', '2026-03-06T03:17:41.819Z', 'b81e2ff87ed8fa4d6c377ccb127a7254c9e6a77e3ae94f21e6b514f7bb2945a0', '{"id":"anthropics/skills/frontend-design","name":"frontend-design","description":{"en":"The frontend-design skill enables AI agents to generate distinctive, production-grade web interfaces like React components and HTML/CSS layouts. It is designed for developers and designers who need to rapidly create high-quality, non-generic UI artifacts.","zh":"frontend-design是一项AI代理技能，专门用于创建具有高设计质量的独特生产级前端界面。它生成创意精美的代码和UI设计，避免通用AI美学，适用于构建Web组件、页面、应用程序和HTML/CSS布局。","ja":"frontend-designは、高いデザイン品質を備えた独自のプロダクショングレードフロントエンドインターフェースを作成するAIエージェントスキルです。一般的なAI美学を避け、Webコンポーネント、ページ、アプリケーション、HTML/CSSレイアウトの構築に適しています。","ko":"frontend-design은 높은 디자인 품질을 가진 독특한 프로덕션급 프론트엔드 인터페이스를 생성하는 AI 에이전트 스킬입니다. 일반적인 AI 미학을 피하고 웹 컴포넌트, 페이지, 애플리케이션, HTML/CSS 레이아웃 구축에 적합합니다.","es":"Este skill de IA Agents genera interfaces frontend distintivas y listas para producción, evitando estéticos genéricos de IA. Crea código funcional en HTML, CSS y componentes React con decisiones de diseño creativas y audaces.","fr":"Cette compétence d''outils IA crée des interfaces frontend distinctives de qualité production, évitant les esthétiques génériques d''IA. Génère du code fonctionnel en HTML, CSS et composants React avec des choix de design créatifs et audacieux.","de":"Diese KI Tools Fähigkeit erstellt distinctive, produktionsreife Frontend-Schnittstellen ohne generische KI-Ästhetik. Generiert funktionierenden Code für HTML, CSS und React-Komponenten mit kreativen und mutigen Designentscheidungen.","pt":"O skill frontend-design permite criar interfaces frontend de alto nível estético e técnico. Gera código React, HTML e CSS funcional e polido, ideal para componentes, landing pages e dashboards, evitando o visual genérico de ferramentas de IA.","ru":"Навык frontend-design создает фронтенд-интерфейсы с высоким эстетическим и техническим качеством. Генерирует рабочий код на React, HTML и CSS для компонентов, лендингов и дашбордов, избегая шаблонного вида ИИ.","ar":"تمكّن مهارة frontend-design من إنشاء واجهات أمامية عالية الجودة من الناحية الجمالية والتقنية. تُنتج أكود React وHTML وCSS عاملة ومصقولة للمكونات وصفحات الهبوط ولوحات التحكم، متجنبة المظهر العام لأدوات الذكاء الاصطناعي."},"owner":"anthropics","repo":"skills","repoPath":"anthropics/skills","stars":85097,"forks":8974,"updatedAt":"2026-03-06T03:11:21Z","topics":["agent-skills"],"skillMd":{"name":"frontend-design","description":"Create distinctive, production-grade frontend interfaces with high design quality. Use this skill when the user asks to build web components, pages, artifacts, posters, or applications (examples include websites, landing pages, dashboards, React components, HTML/CSS layouts, or when styling/beautifying any web UI). Generates creative, polished code and UI design that avoids generic AI aesthetics.","bodyPreview":"This skill guides creation of distinctive, production-grade frontend interfaces that avoid generic \"AI slop\" aesthetics. Implement real working code with exceptional attention to aesthetic details and creative choices.\n\nThe user provides frontend requirements: a component, page, application, or interface to build. They may include context about the purpose, audience, or technical constraints.\n\n## Design Thinking\n\nBefore coding, understand the context and commit to a BOLD aesthetic direction:\n- *","body":"This skill guides creation of distinctive, production-grade frontend interfaces that avoid generic \"AI slop\" aesthetics. Implement real working code with exceptional attention to aesthetic details and creative choices.\n\nThe user provides frontend requirements: a component, page, application, or interface to build. They may include context about the purpose, audience, or technical constraints.\n\n## Design Thinking\n\nBefore coding, understand the context and commit to a BOLD aesthetic direction:\n- **Purpose**: What problem does this interface solve? Who uses it?\n- **Tone**: Pick an extreme: brutally minimal, maximalist chaos, retro-futuristic, organic/natural, luxury/refined, playful/toy-like, editorial/magazine, brutalist/raw, art deco/geometric, soft/pastel, industrial/utilitarian, etc. There are so many flavors to choose from. Use these for inspiration but design one that is true to the aesthetic direction.\n- **Constraints**: Technical requirements (framework, performance, accessibility).\n- **Differentiation**: What makes this UNFORGETTABLE? What''s the one thing someone will remember?\n\n**CRITICAL**: Choose a clear conceptual direction and execute it with precision. Bold maximalism and refined minimalism both work - the key is intentionality, not intensity.\n\nThen implement working code (HTML/CSS/JS, React, Vue, etc.) that is:\n- Production-grade and functional\n- Visually striking and memorable\n- Cohesive with a clear aesthetic point-of-view\n- Meticulously refined in every detail\n\n## Frontend Aesthetics Guidelines\n\nFocus on:\n- **Typography**: Choose fonts that are beautiful, unique, and interesting. Avoid generic fonts like Arial and Inter; opt instead for distinctive choices that elevate the frontend''s aesthetics; unexpected, characterful font choices. Pair a distinctive display font with a refined body font.\n- **Color & Theme**: Commit to a cohesive aesthetic. Use CSS variables for consistency. Dominant colors with sharp accents outperform timid, evenly-distributed palettes.\n- **Motion**: Use animations for effects and micro-interactions. Prioritize CSS-only solutions for HTML. Use Motion library for React when available. Focus on high-impact moments: one well-orchestrated page load with staggered reveals (animation-delay) creates more delight than scattered micro-interactions. Use scroll-triggering and hover states that surprise.\n- **Spatial Composition**: Unexpected layouts. Asymmetry. Overlap. Diagonal flow. Grid-breaking elements. Generous negative space OR controlled density.\n- **Backgrounds & Visual Details**: Create atmosphere and depth rather than defaulting to solid colors. Add contextual effects and textures that match the overall aesthetic. Apply creative forms like gradient meshes, noise textures, geometric patterns, layered transparencies, dramatic shadows, decorative borders, custom cursors, and grain overlays.\n\nNEVER use generic AI-generated aesthetics like overused font families (Inter, Roboto, Arial, system fonts), cliched color schemes (particularly purple gradients on white backgrounds), predictable layouts and component patterns, and cookie-cutter design that lacks context-specific character.\n\nInterpret creatively and make unexpected choices that feel genuinely designed for the context. No design should be the same. Vary between light and dark themes, different fonts, different aesthetics. NEVER converge on common choices (Space Grotesk, for example) across generations.\n\n**IMPORTANT**: Match implementation complexity to the aesthetic vision. Maximalist designs need elaborate code with extensive animations and effects. Minimalist or refined designs need restraint, precision, and careful attention to spacing, typography, and subtle details. Elegance comes from executing the vision well.\n\nRemember: Claude is capable of extraordinary creative work. Don''t hold back, show what can truly be created when thinking outside the box and committing fully to a distinctive vision.\n"},"category":"official","lastSynced":"2026-03-06T03:17:41.819Z","seo":{"title":{"en":"frontend-design: Build Production-Grade UI Components | A...","zh":"frontend-design AI代理技能：打造生产级前端界面的最佳实践","ja":"frontend-design AIエージェントスキル：プロダクショングレードのフロントエンドUI構築ガイド","ko":"frontend-design AI 에이전트 스킬: 프로덕션급 프론트엔드 인터페이스 구축 가이드","es":"frontend-design: Guía para Crear Interfaces de Alta Calidad","fr":"frontend-design: Guide pour Créer des Interfaces de Produ...","de":"frontend-design: Leitfaden für hochwertige Frontend-Entwi...","pt":"frontend-design: Guia para Interfaces de Alta Qualidade c...","ru":"frontend-design: Руководство по созданию интерфейсов с ИИ...","ar":"frontend-design: دليل إنشاء واجهات عالية الجودة باستخدام ..."},"description":{"en":"Generate creative, polished HTML/CSS layouts, React components, and dashboards that avoid generic AI aesthetics. This AI agent skill focuses on bold design t...","zh":"使用frontend-design AI代理技能创建独特的生产级前端界面，避免通用AI美学。生成创意、精美的代码和UI设计，适用于网站、着陆页、仪表板、React组件和HTML/CSS布局。","ja":"frontend-design AIエージェントスキルを使用して、一般的なAI美学を避けた独自のプロダクショングレードフロントエンドインターフェースを作成。ウェブサイト、ランディングページ、ダッシュボード、Reactコンポーネント、HTML/CSSレイアウトに対応。","ko":"frontend-design AI 에이전트 스킬로 일반적인 AI 미학을 피한 독특한 프로덕션급 프론트엔드 인터페이스를 생성합니다. 웹사이트, 랜딩 페이지, 대시보드, React 컴포넌트, HTML/CSS 레이아웃에 적합합니다.","es":"Aprende a usar el skill frontend-design de IA Agents para generar código HTML/CSS y componentes React con diseño único y listo para producción.","fr":"Découvrez comment utiliser la compétence frontend-design des outils IA pour générer du code HTML/CSS et des composants React avec un design distinctif de qua...","de":"Erfahren Sie, wie Sie die frontend-design Fähigkeit von KI Tools verwenden, um produktionsreifen HTML/CSS-Code und React-Komponenten mit einzigartigem Design...","pt":"Use o skill frontend-design para gerar código React, HTML e CSS de produção com design distinto. Evite estéticas genéricas de IA e crie componentes, landing ...","ru":"Используйте навык frontend-design для создания продакшен-кода на React, HTML и CSS с уникальным дизайном. Избегайте шаблонной эстетики ИИ для компонентов, ле...","ar":"استخدم مهارة frontend-design لإنشاء أكود React وHTML وCSS جاهزة للإنتاج بتصميم متميز. تجنب الجماليات العامة للذكاء الاصطناعي وأنشئ مكونات وصفحات ولوحات تحكم ..."},"definition":{"en":"frontend-design is an AI agent skill that creates production-grade frontend interfaces, including web components, pages, and applications. It focuses on generating creative, polished code and UI design that avoids generic AI aesthetics through a dedicated design thinking process.","zh":"frontend-design是一项AI代理技能，专注于生成具有卓越美学细节和创意选择的生产级前端代码。它根据用户提供的前端需求（如组件、页面或应用程序）创建独特且精美的UI设计，避免通用的“AI垃圾”美学。","ja":"frontend-designは、卓越した美的詳細と創造的な選択を備えたプロダクショングレードのフロントエンドコードを生成することに特化したAIエージェントスキルです。コンポーネント、ページ、アプリケーションなどのフロントエンド要件に基づいて、一般的な「AIスラップ」美学を避けた独自のUIデザインを作成します。","ko":"frontend-design은 뛰어난 미적 세부 사항과 창의적인 선택을 갖춘 프로덕션급 프론트엔드 코드 생산에 중점을 둔 AI 에이전트 스킬입니다. 컴포넌트, 페이지, 애플리케이션과 같은 프론트엔드 요구 사항을 기반으로 일반적인 ''AI slop'' 미학을 피한 독특한 UI 디자인을 생성합니다.","es":"frontend-design es un skill de IA Agents especializado en crear interfaces web de alta calidad de diseño y listas para producción. Genera código HTML/CSS, componentes React y layouts evitando estéticas genéricas de IA mediante un proceso de design thinking con direcciones estéticas audaces.","fr":"frontend-design est une compétence d''outils IA spécialisée dans la création d''interfaces web de qualité production avec un design distinctif. Génère du code HTML/CSS, des composants React et des layouts en évitant les esthétiques génériques d''IA grâce à un processus de design thinking avec des directions esthétiques audacieuses.","de":"frontend-design ist eine KI Tools Fähigkeit zur Erstellung von produktionsreifen Web-Schnittstellen mit distinctivem Design. Generiert HTML/CSS-Code, React-Komponenten und Layouts ohne generische KI-Ästhetik durch einen Design-Thinking-Prozess mit mutigen ästhetischen Richtungen.","pt":"frontend-design é um skill de Agente IA especializado em gerar código frontend de produção (React, HTML, CSS) com design distinto e criativo. Foca em evitar estéticas genéricas de IA, produzindo interfaces polidas para componentes, páginas e aplicações web.","ru":"frontend-design — это навык ИИ Агента для генерации продакшен-кода фронтенда (React, HTML, CSS) с уникальным и креативным дизайном. Избегает шаблонной эстетики ИИ, создавая polished интерфейсы для компонентов, страниц и веб-приложений.","ar":"frontend-design هي مهارة خاصة بأدوات الذكاء الاصطناعي تُستخدم لإنشاء أكود واجهة أمامية جاهزة للإنتاج (React, HTML, CSS) بتصميم متميز وإبداعي. تركز على تجنب المظهر العام للذكاء الاصطناعي وإنتاج واجهات مصقولة للمكونات والصفحات والتطبيقات."},"features":{"en":["Generates production-grade HTML/CSS layouts and code","Creates React components and web interfaces","Implements a design thinking process for bold aesthetic direction","Builds distinctive dashboards and landing pages","Produces creative UI artifacts that avoid generic ''AI slop''"],"zh":["生成生产级前端代码，注重美学细节","创建独特UI设计，避免通用AI美学","支持React组件和HTML/CSS布局开发","适用于网站、着陆页和仪表板构建","基于设计思维采用大胆的美学方向","处理技术约束和上下文需求"],"ja":["美的詳細に注意を払ったプロダクショングレードのフロントエンドコードを生成","一般的なAI美学を避けた独自のUIデザインを作成","ReactコンポーネントとHTML/CSSレイアウト開発をサポート","ウェブサイト、ランディングページ、ダッシュボード構築に適用","デザイン思考に基づいた大胆な美学方向を採用","技術的制約とコンテキスト要件を処理"],"ko":["미적 세부 사항에 중점을 둔 프로덕션급 프론트엔드 코드 생성","일반적인 AI 미학을 피한 독특한 UI 디자인 생성","React 컴포넌트 및 HTML/CSS 레이아웃 개발 지원","웹사이트, 랜딩 페이지, 대시보드 구축에 적용","디자인 사고를 기반으로 한 대담한 미학 방향 채택","기술적 제약과 컨텍스트 요구 사항 처리"],"es":["Generación de código HTML/CSS listo para producción","Creación de componentes React con alto diseño estético","Diseño de layouts y páginas web evitando ''AI slop''","Proceso de design thinking con direcciones estéticas audaces","Implementación de interfaces creativas y distintivas","Generación de dashboards y landing pages pulidas"],"fr":["Génération de code HTML/CSS de qualité production","Création de composants React avec design esthétique élevé","Conception de layouts et pages web évitant le ''AI slop''","Processus de design thinking avec directions esthétiques audacieuses","Implémentation d''interfaces créatives et distinctives","Génération de dashboards et landing pages polis"],"de":["Generierung von produktionsreifem HTML/CSS-Code","Erstellung von React-Komponenten mit hoher Designqualität","Gestaltung von Layouts und Webseiten ohne ''AI slop''","Design-Thinking-Prozess mit mutigen ästhetischen Richtungen","Implementierung von kreativen und distinctive Schnittstellen","Generierung von polierten Dashboards und Landing Pages"],"pt":["Geração de código React, HTML e CSS funcional e pronto para produção","Compromisso com direções estéticas arrojadas e criativas (BOLD aesthetic)","Foco em evitar a estética genérica de ''AI slop''","Criação de componentes web, landing pages e dashboards polidos","Atenção excepcional aos detalhes estéticos e de design","Interpretação de contextos, propósitos e restrições técnicas do usuário"],"ru":["Генерация рабочего продакшен-кода на React, HTML и CSS","Приверженность смелым и креативным эстетическим направлениям (BOLD aesthetic)","Фокус на избегании шаблонной эстетики ''AI slop''","Создание polished веб-компонентов, лендингов и дашбордов","Исключительное внимание к эстетическим и дизайнерским деталям","Интерпретация контекста, целей и технических ограничений пользователя"],"ar":["إنشاء أكود React وHTML وCSS عاملة وجاهزة للإنتاج","الالتزام باتجاهات جمالية جريئة وإبداعية (BOLD aesthetic)","التركيز على تجنب المظهر العام ''AI slop''","إنشاء مكونات ويب وصفحات هبوط ولوحات تحكم مصقولة","اهتمام استثنائي بالتفاصيل الجمالية والتصميمية","تفسير سياقات المستخدم وأهدافه وقيده التقنية"]},"keywords":{"en":["how to use frontend-design AI skill","frontend-design vs generic UI generators","frontend-design setup guide","what is frontend-design agent skill","frontend-design alternative","frontend-design install","build React components with AI","generate HTML CSS layouts AI"],"zh":["frontend-design AI代理","生产级前端界面","React组件开发","HTML CSS布局","避免AI美学","前端UI设计","着陆页构建","仪表板开发"],"ja":["frontend-design AIエージェント","プロダクショングレードフロントエンド","Reactコンポーネント開発","HTML CSSレイアウト","AI美学回避","フロントエンドUIデザイン","ランディングページ構築","ダッシュボード開発"],"ko":["frontend-design AI 에이전트","프로덕션급 프론트엔드","React 컴포넌트 개발","HTML CSS 레이아웃","AI 미학 회피","프론트엔드