INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('anthropics/skills/frontend-design', 'frontend-design', 'anthropics', 'skills', 'official', 'frontend-design anthropics skills official agent-skills The frontend-design skill enables AI agents to generate distinctive, production-grade web interfaces like React components and HTML/CSS layouts. It is designed for developers and designers who need to rapidly create high-quality, non-generic UI artifacts. frontend-design是一项AI代理技能，专门用于创建具有高设计质量的独特生产级前端界面。它生成创意精美的代码和UI设计，避免通用AI美学，适用于构建Web组件、页面、应用程序和HTML/CSS布局。 frontend-designは、高いデザイン品質を備えた独自のプロダクショングレードフロントエンドインターフェースを作成するAIエージェントスキルです。一般的なAI美学を避け、Webコンポーネント、ページ、アプリケーション、HTML/CSSレイアウトの構築に適しています。 frontend-design은 높은 디자인 품질을 가진 독특한 프로덕션급 프론트엔드 인터페이스를 생성하는 AI 에이전트 스킬입니다. 일반적인 AI 미학을 피하고 웹 컴포넌트, 페이지, 애플리케이션, HTML/CSS 레이아웃 구축에 적합합니다. Este skill de IA Agents genera interfaces frontend distintivas y listas para producción, evitando estéticos genéricos de IA. Crea código funcional en HTML, CSS y componentes React con decisiones de diseño creativas y audaces. Cette compétence d''outils IA crée des interfaces frontend distinctives de qualité production, évitant les esthétiques génériques d''IA. Génère du code fonctionnel en HTML, CSS et composants React avec des choix de design créatifs et audacieux. Diese KI Tools Fähigkeit erstellt distinctive, produktionsreife Frontend-Schnittstellen ohne generische KI-Ästhetik. Generiert funktionierenden Code für HTML, CSS und React-Komponenten mit kreativen und mutigen Designentscheidungen. O skill frontend-design permite criar interfaces frontend de alto nível estético e técnico. Gera código React, HTML e CSS funcional e polido, ideal para componentes, landing pages e dashboards, evitando o visual genérico de ferramentas de IA. Навык frontend-design создает фронтенд-интерфейсы с высоким эстетическим и техническим качеством. Генерирует рабочий код на React, HTML и CSS для компонентов, лендингов и дашбордов, избегая шаблонного вида ИИ. تمكّن مهارة frontend-design من إنشاء واجهات أمامية عالية الجودة من الناحية الجمالية والتقنية. تُنتج أكود React وHTML وCSS عاملة ومصقولة للمكونات وصفحات الهبوط ولوحات التحكم، متجنبة المظهر العام لأدوات الذكاء الاصطناعي. how to use frontend-design AI skill frontend-design vs generic UI generators frontend-design setup guide what is frontend-design agent skill frontend-design alternative frontend-design install build React components with AI generate HTML CSS layouts AI frontend-design AI代理 生产级前端界面 React组件开发 HTML CSS布局 避免AI美学 前端UI设计 着陆页构建 仪表板开发 Generates production-grade HTML/CSS layouts and code Creates React components and web interfaces Implements a design thinking process for bold aesthetic direction Builds distinctive dashboards and landing pages Produces creative UI artifacts that avoid generic ''AI slop'' frontend-design is an AI agent skill that creates production-grade frontend interfaces, including web components, pages, and applications. It focuses on generating creative, polished code and UI design that avoids generic AI aesthetics through a dedicated design thinking process.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('getsentry/skills/doc-coauthoring', 'official', 'getsentry', 'skills', 'getsentry/skills', 'doc-coauthoring', 360, 11, 64, '2026-03-06T00:20:36Z', '2026-03-06T05:06:59.985Z', '819ad219b7e3f3fd8bc4b0a224dce9cf3b177df6f311b640831b87fb3b5d7730', '{"id":"getsentry/skills/doc-coauthoring","name":"doc-coauthoring","description":{"en":"The doc-coauthoring skill guides users through a structured workflow for co-authoring documentation, helping them efficiently transfer context and refine content. This skill benefits developers and technical writers working on documentation tasks.","zh":"doc-coauthoring技能提供结构化的工作流程，引导用户完成文档协作，包括上下文收集、内容完善和读者测试","ja":"doc-coauthoringスキルは、ドキュメント共同作成を促進するための構造化されたワークフローを提供し、コンテキストの収集、内容の洗練、読者テストを含む","ko":"doc-coauthoring 기능은 문서 공저를 위한 구조화된 워크플로우를 제공하여 사용자가 효율적으로 문서를 생성하고 향상시킬 수 있도록 합니다","es":"El skill de coautoría de documentos proporciona un flujo de trabajo estructurado para guiar a los usuarios en la creación colaborativa de documentos","fr":"La compétence de co-rédaction de documents fournit un workflow structuré pour guider les utilisateurs dans la création collaborative de documents","de":"Die Fähigkeit zur gemeinsamen Erstellung von Dokumenten bietet einen strukturierten Workflow, um Benutzer bei der kollaborativen Erstellung von Dokumenten zu unterstützen","pt":"O fluxo de coautoria de documentos é uma ferramenta que ajuda a guiar os usuários através de uma estrutura de trabalho colaborativa","ru":"Сотрудничество над документами - это инструмент, который помогает пользователям работать вместе над созданием контента","ar":"أداة التعاون في كتابة الوثائق هي أداة تساعد المستخدمين على العمل معاً في إطار عمل مشترك"},"owner":"getsentry","repo":"skills","repoPath":"getsentry/skills","stars":360,"forks":11,"updatedAt":"2026-03-06T00:20:36Z","topics":["tag-production"],"skillMd":{"name":"doc-coauthoring","description":"Guide users through a structured workflow for co-authoring documentation. Use when user wants to write documentation, proposals, technical specs, decision docs, or similar structured content. This workflow helps users efficiently transfer context, refine content through iteration, and verify the doc works for readers. Trigger when user mentions writing docs, creating proposals, drafting specs, or similar documentation tasks.","bodyPreview":"# Doc Co-Authoring Workflow\n\nThis skill provides a structured workflow for guiding users through collaborative document creation. Act as an active guide, walking users through three stages: Context Gathering, Refinement & Structure, and Reader Testing.\n\n## When to Offer This Workflow\n\n**Trigger conditions:**\n- User mentions writing documentation: \"write a doc\", \"draft a proposal\", \"create a spec\", \"write up\"\n- User mentions specific doc types: \"PRD\", \"design doc\", \"decision doc\", \"RFC\"\n- User se","body":"# Doc Co-Authoring Workflow\n\nThis skill provides a structured workflow for guiding users through collaborative document creation. Act as an active guide, walking users through three stages: Context Gathering, Refinement & Structure, and Reader Testing.\n\n## When to Offer This Workflow\n\n**Trigger conditions:**\n- User mentions writing documentation: \"write a doc\", \"draft a proposal\", \"create a spec\", \"write up\"\n- User mentions specific doc types: \"PRD\", \"design doc\", \"decision doc\", \"RFC\"\n- User seems to be starting a substantial writing task\n\n**Initial offer:**\nOffer the user a structured workflow for co-authoring the document. Explain the three stages:\n\n1. **Context Gathering**: User provides all relevant context while Claude asks clarifying questions\n2. **Refinement & Structure**: Iteratively build each section through brainstorming and editing\n3. **Reader Testing**: Test the doc with a fresh Claude (no context) to catch blind spots before others read it\n\nExplain that this approach helps ensure the doc works well when others read it (including when they paste it into Claude). Ask if they want to try this workflow or prefer to work freeform.\n\nIf user declines, work freeform. If user accepts, proceed to Stage 1.\n\n## Stage 1: Context Gathering\n\n**Goal:** Close the gap between what the user knows and what Claude knows, enabling smart guidance later.\n\n### Initial Questions\n\nStart by asking the user for meta-context about the document:\n\n1. What type of document is this? (e.g., technical spec, decision doc, proposal)\n2. Who''s the primary audience?\n3. What''s the desired impact when someone reads this?\n4. Is there a template or specific format to follow?\n5. Any other constraints or context to know?\n\nInform them they can answer in shorthand or dump information however works best for them.\n\n**If user provides a template or mentions a doc type:**\n- Ask if they have a template document to share\n- If they provide a link to a shared document, use the appropriate integration to fetch it\n- If they provide a file, read it\n\n**If user mentions editing an existing shared document:**\n- Use the appropriate integration to read the current state\n- Check for images without alt-text\n- If images exist without alt-text, explain that when others use Claude to understand the doc, Claude won''t be able to see them. Ask if they want alt-text generated. If so, request they paste each image into chat for descriptive alt-text generation.\n\n### Info Dumping\n\nOnce initial questions are answered, encourage the user to dump all the context they have. Request information such as:\n- Background on the project/problem\n- Related team discussions or shared documents\n- Why alternative solutions aren''t being used\n- Organizational context (team dynamics, past incidents, politics)\n- Timeline pressures or constraints\n- Technical architecture or dependencies\n- Stakeholder concerns\n\nAdvise them not to worry about organizing it - just get it all out. Offer multiple ways to provide context:\n- Info dump stream-of-consciousness\n- Point to team channels or threads to read\n- Link to shared documents\n\n**If integrations are available** (e.g., Slack, Teams, Google Drive, SharePoint, or other MCP servers), mention that these can be used to pull in context directly.\n\n**If no integrations are detected and in Claude.ai or Claude app:** Suggest they can enable connectors in their Claude settings to allow pulling context from messaging apps and document storage directly.\n\nInform them clarifying questions will be asked once they''ve done their initial dump.\n\n**During context gathering:**\n\n- If user mentions team channels or shared documents:\n  - If integrations available: Inform them the content will be read now, then use the appropriate integration\n  - If integrations not available: Explain lack of access. Suggest they enable connectors in Claude settings, or paste the relevant content directly.\n\n- If user mentions entities/projects that are unknown:\n  - Ask if connected tools should be searched to learn more\n  - Wait for user confirmation before searching\n\n- As user provides context, track what''s being learned and what''s still unclear\n\n**Asking clarifying questions:**\n\nWhen user signals they''ve done their initial dump (or after substantial context provided), ask clarifying questions to ensure understanding:\n\nGenerate 5-10 numbered questions based on gaps in the context.\n\nInform them they can use shorthand to answer (e.g., \"1: yes, 2: see #channel, 3: no because backwards compat\"), link to more docs, point to channels to read, or just keep info-dumping. Whatever''s most efficient for them.\n\n**Exit condition:**\nSufficient context has been gathered when questions show understanding - when edge cases and trade-offs can be asked about without needing basics explained.\n\n**Transition:**\nAsk if there''s any more context they want to provide at this stage, or if it''s time to move on to drafting the document.\n\nIf user wants to add more, let them. When ready, proceed to Stage 2.\n\n## Stage 2: Refinement & Structure\n\n**Goal:** Build the document section by section through brainstorming, curation, and iterative refinement.\n\n**Instructions to user:**\nExplain that the document will be built section by section. For each section:\n1. Clarifying questions will be asked about what to include\n2. 5-20 options will be brainstormed\n3. User will indicate what to keep/remove/combine\n4. The section will be drafted\n5. It will be refined through surgical edits\n\nStart with whichever section has the most unknowns (usually the core decision/proposal), then work through the rest.\n\n**Section ordering:**\n\nIf the document structure is clear:\nAsk which section they''d like to start with.\n\nSuggest starting with whichever section has the most unknowns. For decision docs, that''s usually the core proposal. For specs, it''s typically the technical approach. Summary sections are best left for last.\n\nIf user doesn''t know what sections they need:\nBased on the type of document and template, suggest 3-5 sections appropriate for the doc type.\n\nAsk if this structure works, or if they want to adjust it.\n\n**Once structure is agreed:**\n\nCreate the initial document structure with placeholder text for all sections.\n\n**If access to artifacts is available:**\nUse `create_file` to create an artifact. This gives both Claude and the user a scaffold to work from.\n\nInform them that the initial structure with placeholders for all sections will be created.\n\nCreate artifact with all section headers and brief placeholder text like \"[To be written]\" or \"[Content here]\".\n\nProvide the scaffold link and indicate it''s time to fill in each section.\n\n**If no access to artifacts:**\nCreate a markdown file in the working directory. Name it appropriately (e.g., `decision-doc.md`, `technical-spec.md`).\n\nInform them that the initial structure with placeholders for all sections will be created.\n\nCreate file with all section headers and placeholder text.\n\nConfirm the filename has been created and indicate it''s time to fill in each section.\n\n**For each section:**\n\n### Step 1: Clarifying Questions\n\nAnnounce work will begin on the [SECTION NAME] section. Ask 5-10 clarifying questions about what should be included:\n\nGenerate 5-10 specific questions based on context and section purpose.\n\nInform them they can answer in shorthand or just indicate what''s important to cover.\n\n### Step 2: Brainstorming\n\nFor the [SECTION NAME] section, brainstorm [5-20] things that might be included, depending on the section''s complexity. Look for:\n- Context shared that might have been forgotten\n- Angles or considerations not yet mentioned\n\nGenerate 5-20 numbered options based on section complexity. At the end, offer to brainstorm more if they want additional options.\n\n### Step 3: Curation\n\nAsk which points should be kept, removed, or combined. Request brief justifications to help learn priorities for the next sections.\n\nProvide examples:\n- \"Keep 1,4,7,9\"\n- \"Remove 3 (duplicates 1)\"\n- \"Remove 6 (audience already knows this)\"\n- \"Combine 11 and 12\"\n\n**If user gives freeform feedback** (e.g., \"looks good\" or \"I like most of it but...\") instead of numbered selections, extract their preferences and proceed. Parse what they want kept/removed/changed and apply it.\n\n### Step 4: Gap Check\n\nBased on what they''ve selected, ask if there''s anything important missing for the [SECTION NAME] section.\n\n### Step 5: Drafting\n\nUse `str_replace` to replace the placeholder text for this section with the actual drafted content.\n\nAnnounce the [SECTION NAME] section will be drafted now based on what they''ve selected.\n\n**If using artifacts:**\nAfter drafting, provide a link to the artifact.\n\nAsk them to read through it and indicate what to change. Note that being specific helps learning for the next sections.\n\n**If using a file (no artifacts):**\nAfter drafting, confirm completion.\n\nInform them the [SECTION NAME] section has been drafted in [filename]. Ask them to read through it and indicate what to change. Note that being specific helps learning for the next sections.\n\n**Key instruction for user (include when drafting the first section):**\nProvide a note: Instead of editing the doc directly, ask them to indicate what to change. This helps learning of their style for future sections. For example: \"Remove the X bullet - already covered by Y\" or \"Make the third paragraph more concise\".\n\n### Step 6: Iterative Refinement\n\nAs user provides feedback:\n- Use `str_replace` to make edits (never reprint the whole doc)\n- **If using artifacts:** Provide link to artifact after each edit\n- **If using files:** Just confirm edits are complete\n- If user edits doc directly and asks to read it: mentally note the changes they made and keep them in mind for future sections (this shows their preferences)\n\n**Continue iterating** until user is satisfied with the section.\n\n### Quality Checking\n\nAfter 3 consecutive iterations with no substantial changes, ask if anything can be removed without losing important information.\n\nWhen section is done, confirm [SECTION NAME] is complete. Ask if ready to move to the next section.\n\n**Repeat for all sections.**\n\n### Near Completion\n\nAs approaching completion (80%+ of sections done), announce intention to re-read the entire document and check for:\n- Flow and consistency across sections\n- Redundancy or contradictions\n- Anything that feels like \"slop\" or generic filler\n- Whether every sentence carries weight\n\nRead entire document and provide feedback.\n\n**When all sections are drafted and refined:**\nAnnounce all sections are drafted. Indicate intention to review the complete document one more time.\n\nReview for overall coherence, flow, completeness.\n\nProvide any final suggestions.\n\nAsk if ready to move to Reader Testing, or if they want to refine anything else.\n\n## Stage 3: Reader Testing\n\n**Goal:** Test the document with a fresh Claude (no context bleed) to verify it works for readers.\n\n**Instructions to user:**\nExplain that testing will now occur to see if the document actually works for readers. This catches blind spots - things that make sense to the authors but might confuse others.\n\n### Testing Approach\n\n**If access to sub-agents is available (e.g., in Claude Code):**\n\nPerform the testing directly without user involvement.\n\n### Step 1: Predict Reader Questions\n\nAnnounce intention to predict what questions readers might ask when trying to discover this document.\n\nGenerate 5-10 questions that readers would realistically ask.\n\n### Step 2: Test with Sub-Agent\n\nAnnounce that these questions will be tested with a fresh Claude instance (no context from this conversation).\n\nFor each question, invoke a sub-agent with just the document content and the question.\n\nSummarize what Reader Claude got right/wrong for each question.\n\n### Step 3: Run Additional Checks\n\nAnnounce additional checks will be performed.\n\nInvoke sub-agent to check for ambiguity, false assumptions, contradictions.\n\nSummarize any issues found.\n\n### Step 4: Report and Fix\n\nIf issues found:\nReport that Reader Claude struggled with specific issues.\n\nList the specific issues.\n\nIndicate intention to fix these gaps.\n\nLoop back to refinement for problematic sections.\n\n---\n\n**If no access to sub-agents (e.g., claude.ai web interface):**\n\nThe user will need to do the testing manually.\n\n### Step 1: Predict Reader Questions\n\nAsk what questions people might ask when trying to discover this document. What would they type into Claude.ai?\n\nGenerate 5-10 questions that readers would realistically ask.\n\n### Step 2: Setup Testing\n\nProvide testing instructions:\n1. Open a fresh Claude conversation: https://claude.ai\n2. Paste or share the document content (if using a shared doc platform with connectors enabled, provide the link)\n3. Ask Reader Claude the generated questions\n\nFor each question, instruct Reader Claude to provide:\n- The answer\n- Whether anything was ambiguous or unclear\n- What knowledge/context the doc assumes is already known\n\nCheck if Reader Claude gives correct answers or misinterprets anything.\n\n### Step 3: Additional Checks\n\nAlso ask Reader Claude:\n- \"What in this doc might be ambiguous or unclear to readers?\"\n- \"What knowledge or context does this doc assume readers already have?\"\n- \"Are there any internal contradictions or inconsistencies?\"\n\n### Step 4: Iterate Based on Results\n\nAsk what Reader Claude got wrong or struggled with. Indicate intention to fix those gaps.\n\nLoop back to refinement for any problematic sections.\n\n---\n\n### Exit Condition (Both Approaches)\n\nWhen Reader Claude consistently answers questions correctly and doesn''t surface new gaps or ambiguities, the doc is ready.\n\n## Final Review\n\nWhen Reader Testing passes:\nAnnounce the doc has passed Reader Claude testing. Before completion:\n\n1. Recommend they do a final read-through themselves - they own this document and are responsible for its quality\n2. Suggest double-checking any facts, links, or technical details\n3. Ask them to verify it achieves the impact they wanted\n\nAsk if they want one more review, or if the work is done.\n\n**If user wants final review, provide it. Otherwise:**\nAnnounce document completion. Provide a few final tips:\n- Consider linking this conversation in an appendix so readers can see how the doc was developed\n- Use appendices to provide depth without bloating the main doc\n- Update the doc as feedback is received from real readers\n\n## Tips for Effective Guidance\n\n**Tone:**\n- Be direct and procedural\n- Explain rationale briefly when it affects user behavior\n- Don''t try to \"sell\" the approach - just execute it\n\n**Handling Deviations:**\n- If user wants to skip a stage: Ask if they want to skip this and write freeform\n- If user seems frustrated: Acknowledge this is taking longer than expected. Suggest ways to move faster\n- Always give user agency to adjust the process\n\n**Context Management:**\n- Throughout, if context is missing on something mentioned, proactively ask\n- Don''t let gaps accumulate - address them as they come up\n\n**Artifact Management:**\n- Use `create_file` for drafting full sections\n- Use `str_replace` for all edits\n- Provide artifact link after every change\n- Never use artifacts for brainstorming lists - that''s just conversation\n\n**Quality over Speed:**\n- Don''t rush through stages\n- Each iteration should make meaningful improvements\n- The goal is a document that actually works for readers\n\n## Attribution\n\nThis skill was adapted from [anthropics/skills](https://github.com/anthropics/courses/tree/master/claude-code/skills/doc-coauthoring).\n"},"category":"official","lastSynced":"2026-03-06T05:06:59.985Z","seo":{"title":{"en":"doc-coauthoring: Collaborative Documentation Workflow Set...","zh":"文档协作指南：高效创建技术文档的AI工具","ja":"ドキュメント共同作成ワークフロー：AIエージェントによる効率的な文書作成","ko":"문서 공저 가이드: 효율적인 기술 문서 생성을 위한 AI 도구","es":"Guía de configuración para coautoría de documentos","fr":"Guide de démarrage pour la co-rédaction de documents","de":"Einrichtungsleitfaden für die gemeinsame Erstellung von D...","pt":"Guia de Configuração do Fluxo de Coautoria de Documentos","ru":"ИИ Агенты: Настройка Сотрудничества над Документами","ar":"دليل إعداد أداة التعاون في كتابة الوثائق"},"description":{"en":"Streamline your documentation process with doc-coauthoring. Learn how to trigger this workflow for efficient content creation and refinement. Get started now!","zh":"了解如何使用AI工具实现文档协作，提高团队效率和文档质量","ja":"AIエージェントを使用してドキュメント共同作成を実現し、チームの生産性と文書品質を向上させる","ko":"AI 도구를 사용하여 문서 공저를 구현하고 팀의 생산성과 문서 품질을 향상시키는 방법을 알아보세요","es":"Aprende a utilizar la coautoría de documentos para mejorar la eficiencia en la creación de contenido estructurado","fr":"Découvrez comment utiliser la co-rédaction de documents pour améliorer l''efficacité dans la création de contenu structuré","de":"Erfahren Sie, wie Sie die gemeinsame Erstellung von Dokumenten nutzen können, um die Effizienz bei der Erstellung von strukturiertem Inhalt zu verbessern","pt":"Aprenda a configurar o fluxo de coautoria de documentos para melhorar a eficiência e a qualidade da criação de conteúdo","ru":"Узнайте, как настроить сотрудничество над документами с помощью ИИ Агентов для повышения производительности","ar":"اكتشف كيفية إعداد أداة التعاون في كتابة الوثائق لتحسين الكفاءة والجودة"},"definition":{"en":"doc-coauthoring is a collaborative documentation workflow that guides users through context gathering, refinement, and reader testing to create effective documentation","zh":"doc-coauthoring是指使用AI工具协助团队成员共同创建和完善技术文档的过程","ja":"doc-coauthoringは、AIエージェントを使用してチームメンバーが共同で技術文書を作成し、改良するプロセスです","ko":"doc-coauthoring은 AI 도구를 사용하여 팀 구성원들이 함께 기술 문서를 생성하고 완善하는 과정입니다","es":"La coautoría de documentos es una función que permite a los usuarios crear contenido estructurado de manera colaborativa","fr":"La co-rédaction de documents est une fonction qui permet aux utilisateurs de créer du contenu structuré de manière collaborative","de":"Die gemeinsame Erstellung von Dokumenten ist eine Funktion, die es Benutzern ermöglicht, strukturierten Inhalt gemeinsam zu erstellen","pt":"O que é fluxo de coautoria de documentos? É uma ferramenta que fornece uma estrutura de trabalho colaborativa para criação de conteúdo","ru":"Что такое сотрудничество над документами? Это инструмент, который предоставляет структуру для совместной работы над контентом","ar":"ما هي أداة التعاون في كتابة الوثائق? هي أداة توفر إطار عمل مشترك لإنشاء المحتوى"},"features":{"en":["Guides users through a three-stage workflow: Context Gathering, Refinement & Structure, and Reader Testing","Triggers on user mentions of writing documentation, such as \"write a doc\" or \"draft a proposal\"","Supports specific doc types, including PRD, design doc, decision doc, and RFC","Helps users refine content through iteration and verify documentation effectiveness"],"zh":["结构化的工作流程","上下文收集和内容完善","读者测试和反馈","支持多种文档类型，包括PRD、设计文档、决策文档和RFC","提高团队效率和文档质量"],"ja":["構造化されたワークフロー","コンテキストの収集と内容の洗練","読者テストとフィードバック","多種多様な文書タイプをサポート、PRD、設計文書、意思決定文書、RFCなど","チームの生産性と文書品質の向上"],"ko":["구조화된 워크플로우","문맥 수집 및 콘텐츠 완善","독자 테스트 및 피드백","다양한 문서 유형 지원, PRD, 설계 문서, 의사 결정 문서, RFC 등","팀의 생산성과 문서 품질 향상"],"es":["Flujo de trabajo estructurado para la creación de documentos","Etapa de recopilación de contexto para garantizar la claridad","Etapa de refinamiento y estructura para mejorar la organización","Etapa de prueba de lectura para asegurar la comprensión del contenido","Compatibilidad con la creación de propuestas, especificaciones técnicas y documentos de decisión"],"fr":["Workflow structuré pour la création de documents","Étape de collecte de contexte pour assurer la clarté","Étape de raffinement et de structure pour améliorer l''organisation","Étape de test de lecture pour assurer la compréhension du contenu","Compatibilité avec la création de propositions, spécifications techniques et documents de décision"],"de":["Strukturierter Workflow für die Erstellung von Dokumenten","Kontextsammelphase, um Klarheit zu gewährleisten","Verfeinerungs- und Strukturphase, um die Organisation zu verbessern","Lesetestphase, um das Verständnis des Inhalts zu sicherzustellen","Kompatibilität mit der Erstellung von Vorschlägen, technischen Spezifikationen und Entscheidungsdokumenten"],"pt":["Fluxo de trabalho estruturado em três etapas: coleta de contexto, refinamento e estruturação e teste de leitor","Integração com tecnologias de criação de conteúdo","Suporte à colaboração em tempo real","Ferramentas de revisão e edição de conteúdo","Compatibilidade com formatos de arquivo de documentação padrão"],"ru":["Структурированный рабочий процесс из трех этапов: сбор контекста, уточнение и структуризация и тестирование читателя","Интеграция с технологиями создания контента","Поддержка сотрудничества в режиме реального времени","Инструменты проверки и редактирования контента","Совместимость с форматами файлов документации по умолчанию"],"ar":["إطار عمل من ثلاث مراحل: جمع السياق وتنقيح الهيكل واختبار القارئ","التكامل مع تقنيات إنشاء المحتوى","دعم التعاون في الوقت الفعلي","أدوات المراجعة وتصحيح المحتوى","التوافق مع تنسيقات الملفات الإفتراضية للوثائق"]},"keywords":{"en":["how to use doc-coauthoring","doc-coauthoring workflow","collaborative documentation tools","doc-coauthoring alternative","doc-coauthoring setup guide","doc-coauthoring for technical writers","doc-coauthoring vs traditional documentation methods","install doc-coauthoring","doc-coauthoring best practices"],"zh":["文档协作","AI工具","技术文档","团队效率","文档质量","结构化工作流程","上下文收集","内容完善","读者测试"],"ja":["ドキュメント共同作成","AIエージェント","技術文書","チームの生産性","文書品質","構造化されたワークフロー","コンテキストの収集","内容の洗練","読者テスト"],"ko":["문서 공저","AI 도구","기술 문서","팀의 생산성","문서 품질","구조화된 워크플로우","문맥 수집","콘텐츠 완善","독자 테스트"],"es":["coautoría de documentos","creación de contenido estructurado","flujo de trabajo colaborativo","herramientas de AI para la creación de documentos","Agente de IA para la coautoría de documentos","mejora de la eficiencia en la creación de contenido","creación de propuestas","especificaciones técnicas","documentos de decisión"],"fr":["co-rédaction de documents","création de contenu structuré","workflow collaboratif","outils d''IA pour la création de documents","Agent d''IA pour la co-rédaction de documents","amélioration de l''efficacité dans la création de contenu","création de propositions","spécifications techniques","documents de décision"],"de":["gemeinsame Erstellung von Dokumenten","Erstellung von strukturiertem Inhalt","kollaborativer Workflow","AI-Tools für die Erstellung von Dokumenten","KI-Agent für die gemeinsame Erstellung von Dokumenten","Verbesserung der Effizienz bei der Erstellung von Inhalt","Erstellung von Vorschlägen","technische Spezifikationen","Entscheidungsdokumente"],"pt":["fluxo de coautoria de documentos","colaboração em documentação","criação de conteúdo colaborativa","ferramentas de documentação","tecnologias de criação de conteúdo","colaboração em tempo real","revisão de conteúdo","edição de conteúdo"],"ru":["сотрудничество над документами","коллаборация в документации","создание контента вместе","инструменты документации","технологии создания контента","сотрудничество в режиме реального времени","проверка контента","редактирование контента"],"ar":["أداة التعاون في كتابة الوثائق","التعاون في وثائق","إنشاء المحتوى المشترك","أدوات الوثائق","تقنيات إنشاء المحتوى","التعاون في الوقت الفعلي","مراجعة المحتوى","تصحيح المحتوى"]}},"agentAnalysis":{"suitability":{"en":"Ideal for Language Agents like Claude Code, AutoGPT, or LangChain needing structured documentation collaboration capabilities.","zh":"适合于Claude Code、AutoGPT或LangChain等语言代理，需要结构化文档协作能力的场景。","ja":"Claude Code、AutoGPT、またはLangChainなどのLanguage Agentsに適しており、構造化されたドキュメントの共同作成機能が必要です。","ko":"Claude Code, AutoGPT 또는 LangChain과 같은 언어 에이전트에 적합하며 구조화된 문서 협업 기능이 필요한 경우에 사용됩니다.","es":"Ideal para Agentes de Lenguaje como Claude Code, AutoGPT o LangChain que necesitan capacidades de colaboración de documentación estructurada.","fr":"Idéal pour les agents de langage comme Claude Code, AutoGPT ou LangChain nécessitant des capacités de collaboration de documentation structurée.","de":"Ideal für Sprachagenten wie Claude Code, AutoGPT oder LangChain, die strukturierte Dokumentationskollaborationsfunktionen benötigen.","pt":"Ideal para Agentes de Linguagem como Claude Code, AutoGPT ou LangChain que necessitam de capacidades de colaboração de documentação estruturada.","ru":"Идеально для языковых агентов, таких как Claude Code, AutoGPT или LangChain, которые требуют возможностей структурированного сотрудничества в документации.","ar":"مثالي للوكلاء اللغويين مثل Claude Code و AutoGPT و LangChain الذين يحتاجون إلى إمكانيات تعاون وثائقية منظمة."},"recommendation":{"en":"Empowers agents to guide users through Context Gathering, Refinement & Structure, and Reader Testing stages, utilizing iterative content refinement and verification protocols, and supporting various documentation types such as PRD, design doc, decision doc, or RFC.","zh":"赋予代理引导用户完成上下文收集、细化和结构化、读者测试等阶段的能力，利用迭代内容细化和验证协议，并支持各种文档类型，如PRD、设计文档、决策文档或RFC。","ja":"エージェントにユーザーをコンテキストの収集、洗練、構造化、リーダーテストなどの段階でガイドする能力を付与し、イテレーションコンテンツの洗練と検証プロトコルを利用し、PRD、デザインドキュメント、意思決定ドキュメント、またはRFCなどの様々なドキュメント形式をサポートします。","ko":"에이전트가 사용자를 컨텍스트 수집, 정제 및 구조화, 리더 테스트 등의 단계에서指导할 수 있는 능력을 부여하며, 반복적인 콘텐츠 정제 및 검증 프로토콜을 활용하고, PRD, 디자인 문서, 의사 결정 문서 또는 RFC와 같은 다양한 문서 형식을 지원합니다.","es":"Permite que los agentes guíen a los usuarios a través de las etapas de Recopilación de Contexto, Refinamiento y Estructura, y Pruebas de Lector, utilizando protocolos de refinamiento y verificación de contenido iterativos, y admitiendo varios tipos de documentación como PRD, design doc, decision doc o RFC.","fr":"Permet aux agents de guider les utilisateurs à travers les étapes de Collecte de Contexte, d''Affinement et de Structure, et de Test de Lecteur, en utilisant des protocoles de raffinement et de vérification de contenu itératifs, et en prenant en charge divers types de documentation tels que PRD, design doc, decision doc ou RFC.","de":"Ermöglicht es Agenten, Benutzer durch die Stadien der Kontextsammmlung, Verfeinerung und Struktur sowie Leser-Tests zu führen, wobei iterative Inhaltsverfeinerungs- und Verifizierungsprotokolle verwendet werden und verschiedene Dokumentationstypen wie PRD, Design-Dokument, Entscheidungsdokument oder RFC unterstützt werden.","pt":"Habilita os agentes a orientar os usuários por meio das etapas de Coleta de Contexto, Refinamento e Estruturação e Testes de Leitura, utilizando protocolos de refinamento e verificação de conteúdo iterativos e suportando vários tipos de documentação, como PRD, design doc, decision doc ou RFC.","ru":"Наделяет агентов возможностью направлять пользователей через этапы сбора контекста, уточнения и структуризации, а также тестирования читаемости, используя итеративные протоколы уточнения и верификации контента и поддерживая различные типы документации, такие как PRD, дизайн-документ, документ принятия решений или RFC.","ar":"تمكّن الوكلاء من توجيه المستخدمين عبر مراحل جمع السياق و التحسين و البناء و اختبار القارئ، باستخدام بروتوكولات تحسين و تحقق المحتوى التكرارية و دعم أنواع مختلفة من الوثائق مثل PRD و وثيقة التصميم و وثيقة القرار أو RFC."},"useCases":{"en":["Automating documentation workflows for technical specs","Generating decision documents with iterative refinement","Debugging proposal drafts through structured reader testing"],"zh":["自动化技术规格的文档工作流程","通过迭代细化生成决策文档","通过结构化读者测试调试提案草稿"],"ja":["技術仕様のドキュメントのワークフローを自動化する","イテレーションの洗練によって意思決定ドキュメントを生成する","構造化されたリーダーテストによって提案の下書きをデバッグする"],"ko":["기술 규격의 문서 워크플로우를 자동화하는 것","반복적인 정제에 의해 의사결정 문서를 생성하는 것","구조화된 리더 테스트를 통해 제안 초안을 디버깅하는 것"],"es":["Automatizar flujos de trabajo de documentación para especificaciones técnicas","Generar documentos de decisión con refinamiento iterativo","Depurar borradores de propuestas a través de pruebas de lectura estructuradas"],"fr":["Automatiser les flux de travail de documentation pour les spécifications techniques","Générer des documents de décision avec un affinement itératif","Déboguer des brouillons de propositions à l''aide de tests de lecteur structurés"],"de":["Automatisierung von Dokumentationsworkflows für technische Spezifikationen","Erstellung von Entscheidungsdokumenten mit iterativer Verfeinerung","Fehlerbehebung von Vorschlag-Entwürfen durch strukturierte Lesertests"],"pt":["Automatizar fluxos de trabalho de documentação para especificações técnicas","Gerar documentos de decisão com refinamento iterativo","Depurar propostas de rascunho por meio de testes de leitura estruturados"],"ru":["Автоматизация рабочих процессов документации для технических спецификаций","Генерация документов решений с итеративным уточнением","Отладка черновиков предложений с помощью структурированного тестирования читаемости"],"ar":["توفير سير عمل وثائقية آلية للمواصفات الفنية","توليد وثائق قرارات مع تحسين تكراري","تصحيح أخطاء مسودات المقترحات من خلال اختبارات قارئية منظمة"]},"limitations":{"en":["Requires user input for context gathering","Limited to text-based documentation formats"],"zh":["需要用户输入来收集上下文","仅限于基于文本的文档格式"],"ja":["コンテキストを収集するためにユーザーの入力が必要","テキストベースのドキュメント形式のみに限定される"],"ko":["콘텍스트를 수집하기 위해 사용자 입력이 필요함","텍스트 기반 문서 형식만으로 제한됨"],"es":["Requiere la entrada del usuario para la recopilación de contexto","Limitado a formatos de documentación basados en texto"],"fr":["Nécessite une entrée utilisateur pour la collecte de contexte","Limité aux formats de documentation basés sur le texte"],"de":["Benutzereingabe für die Kontextsammmlung erforderlich","Begrenzt auf textbasierte Dokumentationsformate"],"pt":["Requer entrada do usuário para coleta de contexto","Limitado a formatos de documentação baseados em texto"],"ru":["Требует ввода пользователя для сбора контекста","Ограничен форматами документации на основе текста"],"ar":["يتطلب إدخال المستخدم لجمع السياق","محدود بتنسيقات الوثائق القائمة على النص"]},"version":4},"contentHash":"819ad219b7e3f3fd8bc4b0a224dce9cf3b177df6f311b640831b87fb3b5d7730","repoEtag":"W/\"36a09bba6a611068f31a3df860388e78cbe9407beaecc6e6da77ba4b47f9eb59\"","qualityScore":64}');
